INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u2-C1','kor',6,2,'u2',2,'면담의 뜻과 특성 — 면담은 정보를 얻으려고 면담 대상자와 주고받는 대화이고, 정보·준비·예의가 함께 있어야 하며, 찾으면 나오는 것이 아니라 그분이 겪은 일과 생각처럼 면담이라야 들을 수 있는 것을 얻는다(일상 대화와 다름: 목적·차례·답하는 쪽이 더 많이 말함)',ARRAY['6국01 듣기·말하기(초안)']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u2-C2','kor',6,2,'u2',2,'면담 요청하기와 물어서는 안 되는 것 — 직접·전화·전자 우편·누리집 등 어느 방법이든 먼저 허락을 구하고, 우리가 누구인지·목적·걸리는 시간·바라는 날짜와 장소를 밝혀 대상자의 사정에 맞추어 정하며, 사는 곳·나이·가족·버는 돈 같은 개인 정보와 곤란한 물음은 덜어 내기',ARRAY['6국01 듣기·말하기(초안)']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u2-C3','kor',6,2,'u2',3,'면담의 절차 — 면담 준비하기(모둠·목적·대상자·방식·자료·질문·역할·요청과 허락, 목적이 맨 먼저) → 면담 진행하기(면담 열기·질문하기·면담 마무리하기) → 면담 정리하기(내용 정리·과정 성찰·보고서 쓰기), 면담은 들은 것을 쓸 수 있게 남길 때 끝남',ARRAY['6국01 듣기·말하기(초안)']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u2-C4','kor',6,2,'u2',3,'질문 세 갈래와 목적에 맞는 질문 — 구체적인 사실·생각이나 느낌·앞으로의 계획이나 당부에 대한 질문을 골고루 만들고, 면담 목적과 이어지지 않는 질문은 덜어 내며, 미리 찾은 자료를 바탕으로 더 깊이 묻기',ARRAY['6국01 듣기·말하기(초안)']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u2-C5','kor',6,2,'u2',5,'면담 자료 읽기와 후속 질문 — 면담 자료에서 열기·질문하기·마무리 단계를 짚어 읽고, 답을 끝까지 듣고 그 안의 말을 붙들어 더 자세히 알려고 이어서 묻는 후속 질문을 하기(질문지는 지도이지 대본이 아님)',ARRAY['6국01 듣기·말하기(초안)']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u2-C6','kor',6,2,'u2',5,'면담 예절과 질문 점검 — 인사·감사·목적 밝히기·동의 구하기, 말씀 도중에 끊지 않고 질문은 짧게, 고개를 끄덕이며 듣기, 만든 질문을 목적에 맞는가·예의를 갖추었는가·뜻이 분명한가로 점검하고, 자료는 누가·언제 만들었는지 밝혀진 믿을 만한 출처에서 찾기',ARRAY['6국01 듣기·말하기(초안)']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u2-C7','kor',6,2,'u2',7,'매체를 고려하여 면담하기 — 매체는 소통을 이어 주는 도구와 환경이고 절차마다 쓰임이 다르며(준비 — 누리집·책, 진행 — 녹음기·영상 통화, 정리 — 다시 들으며 간추리기), 대면·비대면을 대상자의 사정에 맞추어 정하고, 담기 전에 허락받아 보고서에만 쓰고 밖으로 내보내지 않기',ARRAY['6국06 매체(초안)']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u2-C8','kor',6,2,'u2',7,'모둠 역할과 면담 내용 간추리기 — 진행·약속·질문·매체·정리 담당이 하는 일을 알고, 면담 내용을 삭제·대체·선택·구성으로 간추려 내 말로 다시 세우되 답변의 뜻은 바꾸지 않기(통째 옮기기·뭉뚱그리기 피하기)',ARRAY['6국06 매체(초안)']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u2-C9','kor',6,2,'u2',9,'면담 성찰과 면담 보고서 — 잘한 점·보완할 점·더 알고 싶은 점(+ 다음 면담에서 실천할 점)으로 절차마다 되돌아보되 사람 탓이 아니라 다음 약속으로 바꾸고, 보고서를 앞부분(목적·대상자·준비)·가운데 부분(새롭게 안 사실을 갈래로)·뒷부분(깨달은 점·달라진 생각)으로 쓰고 알려도 되는 것만 나누기',ARRAY['6국03 쓰기(초안)']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u2-C10','kor',6,2,'u2',11,'작품 속 인물과 면담하기와 바람직한 질문 — 인물에게 세 갈래로 묻고, 인물이 되어 답할 때는 작품 속 사건·말·행동만 근거로 하며(없으면 「이야기에 나오지 않습니다」), 모자란 곳을 파고들거나 억지로 답하게 하는 불쾌한 질문을 상대의 마음을 헤아리는 바람직한 질문으로 고치기',ARRAY['6국01 듣기·말하기(초안)']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-2-u2-C11','kor',6,2,'u2',11,'겹받침의 발음 — 받침에 자음이 두 개 있는 겹받침은 낱말 하나로 있을 때 하나만 소리 나고(맑다[막따]·넓다[널따]), 뒤에 모음으로 시작하는 말이 붙으면 앞 자음은 받침으로 남고 뒤 자음이 넘어가 소리 남(맑아[말가]·넓은[널븐])(기초 다지기)',ARRAY['6국04 문법(초안)']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u2-X01','kor',6,'u2',ARRAY['K6-2-u2-C1']::text[],'면담을 친해지려고 나누는 일상 대화나 누가 옳은지 가리는 겨루기로 여긴다','「무엇을 알고 싶어서 만나나?」 — 목적이 있는 대화') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u2-X02','kor',6,'u2',ARRAY['K6-2-u2-C1','K6-2-u2-C4','K6-2-u2-C5']::text[],'찾아보면 나오는 것(사전 뜻·수·기록)을 면담에서 묻거나, 면담을 검색을 사람으로 바꾼 일로 여긴다','그분이 아니면 답할 수 없는 물음인가?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u2-X03','kor',6,'u2',ARRAY['K6-2-u2-C2']::text[],'면담을 요청할 때 누구인지·목적·시간·날짜를 빠뜨리거나, 날짜를 정해 통보하고 허락을 구하지 않는다','누구 · 왜 · 얼마나 · 언제가 괜찮으신지 — 여쭈어 맞추기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u2-X04','kor',6,'u2',ARRAY['K6-2-u2-C2','K6-2-u2-C9']::text[],'궁금하면 사는 곳·나이·가족·버는 돈 같은 개인 정보도 묻거나 보고서에 적어도 된다고 여긴다','「이 질문을 내가 받으면 어떨까?」') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u2-X05','kor',6,'u2',ARRAY['K6-2-u2-C3']::text[],'면담의 절차(준비·진행·정리)나 진행 단계(열기·질문하기·마무리)의 차례와 할 일을 섞는다(목적보다 날짜·역할을 먼저 정하기 등)','만나기 전 · 만나는 동안 · 만난 뒤로 가르기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u2-X06','kor',6,'u2',ARRAY['K6-2-u2-C3','K6-2-u2-C5']::text[],'질문지를 대본처럼 차례대로 읽기만 하고 답을 끝까지 듣지 않아 후속 질문을 하지 못한다','질문지는 지도 — 답 속의 말을 붙들어 이어서 묻기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u2-X07','kor',6,'u2',ARRAY['K6-2-u2-C3','K6-2-u2-C4','K6-2-u2-C5']::text[],'준비 없이 떠오르는 대로 묻거나 면담 목적에서 벗어난 질문을 한다','목적과 하나씩 견주어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u2-X08','kor',6,'u2',ARRAY['K6-2-u2-C4','K6-2-u2-C10']::text[],'질문의 세 갈래(사실·생각이나 느낌·계획이나 당부)를 헷갈리거나 사실만 묻는다','있었던 일? 마음? 앞일과 당부?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u2-X09','kor',6,'u2',ARRAY['K6-2-u2-C4','K6-2-u2-C6']::text[],'자료를 재미·사진·검색 순서로 고르고 누가·언제 만들었는지 출처를 확인하지 않는다','누가 만들었나 · 언제 만들었나 · 목적과 이어지나') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u2-X10','kor',6,'u2',ARRAY['K6-2-u2-C6']::text[],'면담 예절을 놓친다(말씀 도중에 끊기·다시 답하게 하기·길게 묻기·감사 인사 없이 나오기)','시간을 내어 주신 분 쪽에서 생각하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u2-X11','kor',6,'u2',ARRAY['K6-2-u2-C7','K6-2-u2-C9']::text[],'허락 없이 담거나, 담아 둔 목소리·영상을 누리집·친구에게 내보내거나 다른 일에 쓴다','담아 둔 것은 빌려 온 것 — 허락 · 보고서에만 · 밖으로 안 내보내기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u2-X12','kor',6,'u2',ARRAY['K6-2-u2-C7']::text[],'매체의 뜻·절차마다의 쓰임·대면과 비대면을 헷갈린다','준비 — 찾기 · 진행 — 담기·영상 통화 · 정리 — 다시 듣기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u2-X13','kor',6,'u2',ARRAY['K6-2-u2-C8','K6-2-u2-C9']::text[],'면담 내용을 들은 그대로 통째로 옮기거나, 뭉뚱그려 남는 것이 없게 하거나, 답변의 뜻을 바꾸어 적는다','고르고 덜고 묶어 내 말로 — 뜻은 그대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u2-X14','kor',6,'u2',ARRAY['K6-2-u2-C9']::text[],'성찰을 사람 탓·잘잘못 가리기나 막연한 기분, 목소리·옷차림 같은 겉모습으로 한다','절차마다 무엇을 했나 → 다음에 무엇을 할까') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u2-X15','kor',6,'u2',ARRAY['K6-2-u2-C9']::text[],'면담 보고서의 앞부분·가운데 부분·뒷부분이 담는 내용을 헷갈리거나 느낌·시각만 적는다','앞 — 왜·누구·준비 · 가운데 — 새로 안 사실 · 뒤 — 달라진 생각') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u2-X16','kor',6,'u2',ARRAY['K6-2-u2-C10']::text[],'인물이 되어 답할 때 작품에 없는 내용을 지어내거나 내 이야기를 대신한다','이야기 속 사건·말·행동에 밑줄 — 없으면 「나오지 않습니다」') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u2-X17','kor',6,'u2',ARRAY['K6-2-u2-C10']::text[],'모자란 곳을 파고들거나 깎아내리거나 억지로 답하게 하는 불쾌한 질문을 그대로 한다','궁금함 + 상대의 마음 헤아리기 + 고를 여지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u2-X18','kor',6,'u2',ARRAY['K6-2-u2-C11']::text[],'겹받침을 모음 앞에서도 하나만 소리 내거나, 낱말 하나일 때 둘 다 소리 낸다','모음이 붙으면 뒤 자음이 넘어가요 — 맑아[말가]') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-2-u2-X19','kor',6,'u2',ARRAY['K6-2-u2-C8']::text[],'모둠 역할(진행·약속·질문·매체·정리)이 하는 일을 헷갈리거나, 면담이 두려운 친구는 빠져야 한다고 여긴다','누가 시간을 · 누가 기기를 · 누가 글로 남기나') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L02_basic#1','kor',6,2,'u2','L02','g6_2_kor_u2_L02_basic','lesson_basic','K6-2-u2-C1',1,'mc','auto','면담의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u2-X01','K6-2-u2-X02']::text[],false,'{"seq":1,"concept":"K6-2-u2-C1","difficulty":1,"kind":"mc","stem":"면담의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"정보를 얻으려고 면담 대상자와 주고받는 대화","correct":true},{"t":"친해지려고 가볍게 나누는 이야기","mis":"K6-2-u2-X01"},{"t":"누구의 말이 더 옳은지 가려내는 겨루기","mis":"K6-2-u2-X01"},{"t":"책이나 누리집에서 정보를 찾아 읽는 일","mis":"K6-2-u2-X02"}],"explanation":["면담은 대화이지만 목적이 있어요.","정보를 얻으려고 면담 대상자와 묻고 답해요.","찾아 읽는 일이나 겨루기와는 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L02_basic#2','kor',6,2,'u2','L02','g6_2_kor_u2_L02_basic','lesson_basic','K6-2-u2-C1',1,'ox','auto','면담은 갑자기 찾아가 그때그때 묻는 일이 아니라 미리 준비하는 일이에요.',ARRAY['K6-2-u2-X07']::text[],false,'{"seq":2,"concept":"K6-2-u2-C1","difficulty":1,"kind":"ox","stem":"면담은 갑자기 찾아가 그때그때 묻는 일이 아니라 미리 준비하는 일이에요.","answer":"O","reason_options":[{"t":"대상자를 정하고 자료를 모아 질문을 만드는 준비가 필요하기 때문에","correct":true},{"t":"궁금한 것이 생기면 바로 찾아가 묻는 것이 면담이기 때문에","mis":"K6-2-u2-X07"}],"mis":"K6-2-u2-X07","explanation":["시후와 가람은 무엇을 여쭐지 먼저 정하기로 했어요.","시간이 되시는지도 여쭈어보기로 했어요.","면담은 준비에서 시작해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L02_basic#3','kor',6,2,'u2','L02','g6_2_kor_u2_L02_basic','lesson_basic','K6-2-u2-C1',1,'sa','auto','정보를 얻으려고 면담 대상자와 주고받는 대화를 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"K6-2-u2-C1","difficulty":1,"kind":"sa","stem":"정보를 얻으려고 면담 대상자와 주고받는 대화를 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["면담"],"explanation":["궁금한 것을 책에서만 찾는 것은 아니에요.","그 일을 하는 사람을 만나 묻고 답을 들을 수 있어요.","이 대화를 면담이라고 해요."],"mis":"K6-2-u2-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L02_basic#4','kor',6,2,'u2','L02','g6_2_kor_u2_L02_basic','lesson_basic','K6-2-u2-C2',1,'mc','auto','면담을 부탁드리는 방법에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u2-X03']::text[],false,'{"seq":4,"concept":"K6-2-u2-C2","difficulty":1,"kind":"mc","stem":"면담을 부탁드리는 방법에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"직접 찾아가거나 전화·전자 우편·누리집 글로 할 수 있고, 어느 방법이든 먼저 허락을 구한다","correct":true},{"t":"반드시 직접 찾아가서만 부탁드려야 한다","mis":"K6-2-u2-X03"},{"t":"전화로 부탁드릴 때는 허락을 구하지 않아도 된다","mis":"K6-2-u2-X03"},{"t":"날짜를 정해 알려 드리면 허락을 구한 것이다","mis":"K6-2-u2-X03"}],"explanation":["면담을 부탁드리는 방법은 하나가 아니에요.","찾아가기·전화·전자 우편·누리집 글이 모두 돼요.","어떤 방법이든 먼저 허락을 구하는 것은 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L02_basic#5','kor',6,2,'u2','L02','g6_2_kor_u2_L02_basic','lesson_basic','K6-2-u2-C1',2,'mc','auto','문화재를 고치는 주희란 선생님께 여쭐 물음 가운데 면담이라야 답을 들을 수 있는 것은 어느 것인가요?',ARRAY['K6-2-u2-X02']::text[],false,'{"seq":5,"concept":"K6-2-u2-C1","difficulty":2,"kind":"mc","stem":"문화재를 고치는 주희란 선생님께 여쭐 물음 가운데 면담이라야 답을 들을 수 있는 것은 어느 것인가요?","options":[{"t":"처음 이 일을 배우실 때 가장 어려웠던 점은 무엇인가요?","correct":true},{"t":"문화재라는 낱말의 사전 뜻은 무엇인가요?","mis":"K6-2-u2-X02"},{"t":"우리나라에 지정된 문화재는 모두 몇 건인가요?","mis":"K6-2-u2-X02"},{"t":"가장 오래된 문화재는 언제 만들어졌나요?","mis":"K6-2-u2-X02"}],"explanation":["사전 뜻·수·만든 때는 찾아보면 나와요.","그분이 겪은 일과 느낀 것은 그분에게서만 들을 수 있어요.","면담이라야 얻는 것이 생생한 정보예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L02_basic#6','kor',6,2,'u2','L02','g6_2_kor_u2_L02_basic','lesson_basic','K6-2-u2-C2',2,'mc','auto','소식지 모둠의 면담 요청에 들어 있는 것을 바르게 모은 것은 어느 것인가요?',ARRAY['K6-2-u2-X04','K6-2-u2-X03']::text[],false,'{"seq":6,"concept":"K6-2-u2-C2","difficulty":2,"kind":"mc","stem":"소식지 모둠의 면담 요청에 들어 있는 것을 바르게 모은 것은 어느 것인가요?","options":[{"t":"우리가 누구인지 · 면담 목적 · 바라는 날짜 · 걸리는 시간","correct":true},{"t":"우리가 누구인지 · 선생님의 나이 · 선생님이 사시는 곳","mis":"K6-2-u2-X04"},{"t":"면담 목적 하나만","mis":"K6-2-u2-X03"},{"t":"바라는 날짜만 알리고 목적은 만나서 말씀드림","mis":"K6-2-u2-X03"}],"explanation":["하온은 「학급 소식지를 만드는 모둠」이라고 누구인지 밝혔어요.","단우는 목적과 「다음 주 수요일 오후」·「삼십 분 정도」를 말했어요.","이만큼 밝혀야 상대가 응할지 정할 수 있어요."],"asset":{"type":"speech","turns":[{"who":"하온","text":"안녕하세요? 저희는 학급 소식지를 만드는 모둠입니다. 소식지에 오래된 물건을 고쳐 쓰는 일에 대한 글을 싣고 싶습니다."},{"who":"주희란","text":"반갑습니다. 어떤 이야기가 필요한가요?"},{"who":"단우","text":"문화재를 고치는 일이 어떤 일인지 여쭙고 싶습니다. 다음 주 수요일 오후에 삼십 분 정도 시간을 내어 주실 수 있을까요?"},{"who":"주희란","text":"좋습니다. 그날 작업실에서 만나기로 하지요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L02_basic#7','kor',6,2,'u2','L02','g6_2_kor_u2_L02_basic','lesson_basic','K6-2-u2-C1',2,'match','auto','면담의 세 가지 특성과 그 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K6-2-u2-C1","difficulty":2,"kind":"match","stem":"면담의 세 가지 특성과 그 뜻을 알맞게 이으세요.","pairs":[{"l":"정보","r":"묻고 답하는 가운데 그분만 아는 생생한 것을 얻는다"},{"l":"준비","r":"대상자를 정하고 자료를 모아 질문을 만들어 둔다"},{"l":"예의","r":"약속을 정하고 인사와 감사를 갖추어 말한다"}],"mis":"K6-2-u2-X01","explanation":["정보는 만나서 얻는 것이에요.","준비는 만나기 전에, 예의는 만나는 동안 지켜요.","셋 가운데 하나만 빠져도 면담이 잘 되지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L02_basic#8','kor',6,2,'u2','L02','g6_2_kor_u2_L02_basic','lesson_basic','K6-2-u2-C2',2,'ox','auto','면담 대상자가 사는 곳이나 버는 돈도 궁금하면 물어볼 수 있어요.',ARRAY['K6-2-u2-X04']::text[],false,'{"seq":8,"concept":"K6-2-u2-C2","difficulty":2,"kind":"ox","stem":"면담 대상자가 사는 곳이나 버는 돈도 궁금하면 물어볼 수 있어요.","answer":"X","reason_options":[{"t":"알리고 싶지 않을 수 있는 개인 정보이고 면담 목적과 이어지지 않기 때문에","correct":true},{"t":"궁금한 것은 무엇이든 묻는 것이 면담이기 때문에","mis":"K6-2-u2-X04"}],"mis":"K6-2-u2-X04","explanation":["사는 곳·나이·가족·버는 돈은 개인 정보예요.","물어도 되는 것은 하시는 일·어려운 점·보람처럼 목적과 이어진 것이에요.","궁금하다고 다 물어도 되는 것은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L02_basic#9','kor',6,2,'u2','L02','g6_2_kor_u2_L02_basic','lesson_basic','K6-2-u2-C1',2,'mc','auto','일상 대화와 견준 면담의 모습으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u2-X01','K6-2-u2-X07','K6-2-u2-X06']::text[],false,'{"seq":9,"concept":"K6-2-u2-C1","difficulty":2,"kind":"mc","stem":"일상 대화와 견준 면담의 모습으로 알맞은 것은 어느 것인가요?","options":[{"t":"답하는 쪽이 훨씬 많이 말하고, 면담자는 잘 묻고 잘 듣는다","correct":true},{"t":"두 사람이 주고받는 말의 양이 늘 비슷하다","mis":"K6-2-u2-X01"},{"t":"정해진 차례 없이 떠오르는 대로 묻는다","mis":"K6-2-u2-X07"},{"t":"면담자가 가장 많이 말해야 잘한 면담이다","mis":"K6-2-u2-X06"}],"explanation":["일상 대화는 친해지려고 나누고 차례가 없어요.","면담은 목적이 있고 준비·진행·정리의 차례가 있어요.","면담자는 많이 말하는 사람이 아니라 잘 듣는 사람이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L02_basic#10','kor',6,2,'u2','L02','g6_2_kor_u2_L02_basic','lesson_basic','K6-2-u2-C2',3,'error','auto','면담을 부탁드리는 첫마디를 친구들이 말해 보았어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u2-X03']::text[],false,'{"seq":10,"concept":"K6-2-u2-C2","difficulty":3,"kind":"error","stem":"면담을 부탁드리는 첫마디를 친구들이 말해 보았어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"은결 — 「지금 바로 시간 되시죠? 금방 끝나니까 몇 개만 물어볼게요.」","correct":true,"mis_target":"K6-2-u2-X03"},{"t":"다솜 — 「저희는 6학년 학생입니다. 하시는 일이 궁금해 몇 가지 여쭙고 싶은데 언제가 괜찮으실까요?」","mis":"K6-2-u2-X03"},{"t":"로운 — 「학급 신문에 실을 글을 쓰려고 하는데, 삼십 분쯤 시간을 내어 주실 수 있을까요?」","mis":"K6-2-u2-X03"}],"explanation":["다솜은 누구인지·왜·언제가 괜찮은지 여쭈었어요.","로운은 목적과 걸리는 시간을 밝혔어요.","은결은 상대의 사정을 묻지 않고 지금 하자고 정해 버렸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L02_challenge#1','kor',6,2,'u2','L02','g6_2_kor_u2_L02_challenge','lesson_challenge','K6-2-u2-C1',2,'sa','auto','면담의 세 가지 특성은 「정보 · 준비 · ○○」예요. ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K6-2-u2-C1","difficulty":2,"kind":"sa","stem":"면담의 세 가지 특성은 「정보 · 준비 · ○○」예요. ○○에 알맞은 두 글자를 쓰세요.","answer":["예의"],"explanation":["정보는 면담으로 얻는 것이에요.","준비는 만나기 전에 하는 일이에요.","시간을 내어 주신 분께는 예의를 지켜요."],"mis":"K6-2-u2-X10"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L02_challenge#2','kor',6,2,'u2','L02','g6_2_kor_u2_L02_challenge','lesson_challenge','K6-2-u2-C2',2,'mc','auto','면담 질문을 만든 뒤 개인 정보나 곤란한 질문이 없는지 되짚을 때 쓰면 좋은 물음은 어느 것인가요?',ARRAY['K6-2-u2-X04']::text[],false,'{"seq":2,"concept":"K6-2-u2-C2","difficulty":2,"kind":"mc","stem":"면담 질문을 만든 뒤 개인 정보나 곤란한 질문이 없는지 되짚을 때 쓰면 좋은 물음은 어느 것인가요?","options":[{"t":"「이 질문을 내가 받으면 어떨까?」","correct":true},{"t":"「이 질문이 가장 길까?」","mis":"K6-2-u2-X04"},{"t":"「이 질문을 하면 면담이 빨리 끝날까?」","mis":"K6-2-u2-X04"},{"t":"「이 질문을 들으면 친구들이 웃을까?」","mis":"K6-2-u2-X04"}],"explanation":["질문을 받는 사람 쪽에서 생각해 보아요.","내가 받아서 불편한 질문은 그분도 불편해요.","그런 질문은 덜어 내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L02_challenge#3','kor',6,2,'u2','L02','g6_2_kor_u2_L02_challenge','lesson_challenge','K6-2-u2-C1',3,'mc','auto','주희란 선생님의 답 「어디가 어떻게 상했는지 오래 들여다봅니다. 그 시간이 가장 깁니다.」가 면담이라야 얻을 수 있는 정보인 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u2-X02','K6-2-u2-X01']::text[],false,'{"seq":3,"concept":"K6-2-u2-C1","difficulty":3,"kind":"mc","stem":"주희란 선생님의 답 「어디가 어떻게 상했는지 오래 들여다봅니다. 그 시간이 가장 깁니다.」가 면담이라야 얻을 수 있는 정보인 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"그 일을 직접 해 온 사람이 겪은 일과 느낀 것이 담겨 있어서","correct":true},{"t":"사전에 그대로 적혀 있는 풀이여서","mis":"K6-2-u2-X02"},{"t":"누구나 아는 사실을 다시 말해서","mis":"K6-2-u2-X02"},{"t":"짧게 답해서 받아 적기 쉬워서","mis":"K6-2-u2-X01"}],"explanation":["「그 시간이 가장 깁니다」는 해 본 사람만 알아요.","책에는 일의 이름은 나와도 하루의 모습은 잘 나오지 않아요.","면담은 그런 생생한 정보를 얻어요."],"asset":{"type":"speech","turns":[{"who":"하온","text":"면담에 응해 주셔서 감사합니다. 미리 찾아본 자료를 바탕으로 질문을 준비했습니다."},{"who":"단우","text":"문화재를 고칠 때 가장 먼저 하시는 일은 무엇인가요?"},{"who":"주희란","text":"고치기 전에 먼저 어디가 어떻게 상했는지 오래 들여다봅니다. 그 시간이 가장 깁니다."},{"who":"하온","text":"오늘 귀한 말씀 감사합니다. 소식지가 나오면 가져다 드리겠습니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L02_challenge#4','kor',6,2,'u2','L02','g6_2_kor_u2_L02_challenge','lesson_challenge','K6-2-u2-C1',3,'ox','auto','면담은 누리집에서 찾을 수 있는 것을 사람에게 대신 물어보는 일이에요.',ARRAY['K6-2-u2-X02']::text[],false,'{"seq":4,"concept":"K6-2-u2-C1","difficulty":3,"kind":"ox","stem":"면담은 누리집에서 찾을 수 있는 것을 사람에게 대신 물어보는 일이에요.","answer":"X","reason_options":[{"t":"찾으면 나오는 것은 찾아 두고, 그것을 바탕으로 그분이 아니면 들을 수 없는 것을 묻기 때문에","correct":true},{"t":"사람에게 물으면 검색보다 빨리 답을 얻을 수 있기 때문에","mis":"K6-2-u2-X02"}],"mis":"K6-2-u2-X02","explanation":["찾으면 나오는 것만 물으면 들어도 새로운 것이 없어요.","면담은 한 사람의 겪은 일과 그 뜻을 함께 들어요.","찾아 둔 것을 바탕으로 더 깊이 물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L02_challenge#5','kor',6,2,'u2','L02','g6_2_kor_u2_L02_challenge','lesson_challenge','K6-2-u2-C2',3,'mc','auto','면담 날짜와 장소를 정하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u2-X03','K6-2-u2-X07']::text[],false,'{"seq":5,"concept":"K6-2-u2-C2","difficulty":3,"kind":"mc","stem":"면담 날짜와 장소를 정하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"바라는 때를 말씀드리고 면담 대상자의 사정에 맞추어 함께 정한다","correct":true},{"t":"우리가 정한 날짜를 알려 드리고 그대로 찾아간다","mis":"K6-2-u2-X03"},{"t":"날짜는 정하지 않고 아무 때나 찾아간다","mis":"K6-2-u2-X07"},{"t":"장소는 언제나 우리 교실로 오시게 한다","mis":"K6-2-u2-X03"}],"explanation":["면담 대상자는 시간을 내어 주시는 분이에요.","날짜·시간·장소는 우리가 통보하지 않아요.","그분과 맞추어 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L02_challenge#6','kor',6,2,'u2','L02','g6_2_kor_u2_L02_challenge','lesson_challenge','K6-2-u2-C1',3,'error','auto','면담에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u2-X06','K6-2-u2-X02','K6-2-u2-X01']::text[],false,'{"seq":6,"concept":"K6-2-u2-C1","difficulty":3,"kind":"error","stem":"면담에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"시아 — 「질문을 열 개 만들어 갔으니 차례대로 읽고 오면 면담이 끝나.」","correct":true,"mis_target":"K6-2-u2-X06"},{"t":"도윤 — 「찾아보면 나오는 것은 미리 찾아 두고 가야 해.」","mis":"K6-2-u2-X02"},{"t":"하린 — 「답하시는 분이 더 많이 말씀하시도록 잘 들어야 해.」","mis":"K6-2-u2-X01"}],"explanation":["질문지는 길을 잃지 않게 하는 지도예요.","답을 끝까지 듣고 궁금하면 이어서 물어요.","읽기만 하면 면담이 아니라 낭독이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L02_challenge#7','kor',6,2,'u2','L02','g6_2_kor_u2_L02_challenge','lesson_challenge','K6-2-u2-C2',3,'match','auto','면담 질문과 그 질문을 다루는 방법을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K6-2-u2-C2","difficulty":3,"kind":"match","stem":"면담 질문과 그 질문을 다루는 방법을 알맞게 이으세요.","pairs":[{"l":"이 일을 하게 된 까닭은 무엇인가요?","r":"목적과 이어져 물어도 된다"},{"l":"댁은 어느 동네에 있나요?","r":"개인 정보라 덜어 낸다"},{"l":"말씀하기 싫으셔도 꼭 대답해 주셔야 해요.","r":"억지로 답하게 해 덜어 낸다"}],"mis":"K6-2-u2-X04","explanation":["하는 일·까닭·보람은 목적과 이어진 질문이에요.","사는 곳은 알리고 싶지 않을 수 있는 개인 정보예요.","답하기 어려운데 억지로 답하게 하는 질문도 덜어 내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L02_challenge#8','kor',6,2,'u2','L02','g6_2_kor_u2_L02_challenge','lesson_challenge','K6-2-u2-C1',4,'mc','auto','「면담」과 「일상 대화」를 가르는 기준을 바르게 모두 든 것은 어느 것인가요?',ARRAY['K6-2-u2-X01']::text[],false,'{"seq":8,"concept":"K6-2-u2-C1","difficulty":4,"kind":"mc","stem":"「면담」과 「일상 대화」를 가르는 기준을 바르게 모두 든 것은 어느 것인가요?","options":[{"t":"정보를 얻으려는 목적이 있는가 · 준비·진행·정리의 차례가 있는가 · 답하는 쪽이 더 많이 말하는가","correct":true},{"t":"누구와 이야기하는가 · 몇 분 동안 이야기하는가","mis":"K6-2-u2-X01"},{"t":"이야기가 재미있는가 · 웃음이 많았는가","mis":"K6-2-u2-X01"},{"t":"어디에서 만났는가 · 무엇을 입었는가","mis":"K6-2-u2-X01"}],"explanation":["면담은 목적이 있는 대화예요.","차례가 있고, 답하는 쪽이 훨씬 많이 말해요.","누구와·얼마나·어디서는 가르는 기준이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L02_challenge#9','kor',6,2,'u2','L02','g6_2_kor_u2_L02_challenge','lesson_challenge','K6-2-u2-C2',4,'essay','teacher','내가 만나고 싶은 분께 면담을 부탁드리는 말을 써 보세요. 우리가 누구인지, 면담 목적, 걸리는 시간, 바라는 날짜를 넣고, 날짜를 정해서 알려 드리는 말이 되지 않게 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u2-C2","difficulty":4,"kind":"essay","stem":"내가 만나고 싶은 분께 면담을 부탁드리는 말을 써 보세요. 우리가 누구인지, 면담 목적, 걸리는 시간, 바라는 날짜를 넣고, 날짜를 정해서 알려 드리는 말이 되지 않게 쓰세요.","answer_guide":{"answer":"예: 안녕하세요? 저희는 금성초등학교 6학년 학생들입니다. 학급 신문에 도서관에서 하시는 일을 알리는 글을 싣고 싶어 몇 가지 여쭙고 싶습니다. 삼십 분 정도 걸릴 것 같은데, 다음 주 목요일 오후나 금요일 오후 가운데 괜찮으신 때가 있으실까요? 어려우시면 편하신 때를 말씀해 주시면 맞추겠습니다.","scoring_points":["우리가 누구인지와 면담 목적을 밝혔는가","걸리는 시간과 바라는 날짜를 넣었는가","상대의 사정을 여쭈어 함께 정하는 말로 썼는가"]},"explanation":["누구 · 왜 · 얼마나 · 언제가 들어가요.","「괜찮으실까요?」처럼 여쭈어요.","정해서 알리면 허락을 구한 것이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L02_challenge#10','kor',6,2,'u2','L02','g6_2_kor_u2_L02_challenge','lesson_challenge','K6-2-u2-C1',4,'essay','teacher','「면담은 검색을 사람으로 바꾼 일이다.」라는 말이 왜 알맞지 않은지 쓰고, 문화재를 고치는 주희란 선생님께 면담이라야 답을 들을 수 있는 질문을 두 가지 만들어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u2-C1","difficulty":4,"kind":"essay","stem":"「면담은 검색을 사람으로 바꾼 일이다.」라는 말이 왜 알맞지 않은지 쓰고, 문화재를 고치는 주희란 선생님께 면담이라야 답을 들을 수 있는 질문을 두 가지 만들어 쓰세요.","answer_guide":{"answer":"예: 면담은 찾으면 나오는 것을 대신 묻는 일이 아니라, 그분이 겪은 일과 그 일을 하며 느낀 것처럼 그분이 아니면 들을 수 없는 것을 듣는 일이기 때문이다. 질문 1 — 고치기 어려웠던 물건을 앞에 두고 어떤 생각을 하셨나요? 질문 2 — 이 일을 하시면서 가장 보람 있었던 때는 언제인가요?","scoring_points":["검색과 다른 까닭(그분만 아는 겪은 일·생각)을 썼는가","면담이라야 답할 수 있는 질문을 두 가지 만들었는가","찾으면 나오는 질문(사전 뜻·수)을 넣지 않았는가"]},"explanation":["찾으면 나오는 것은 미리 찾아 두어요.","그분의 경험·마음을 물어요.","그래야 면담이 생생해져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L03_basic#1','kor',6,2,'u2','L03','g6_2_kor_u2_L03_basic','lesson_basic','K6-2-u2-C3',1,'mc','auto','면담의 세 절차를 차례대로 바르게 늘어놓은 것은 어느 것인가요?',ARRAY['K6-2-u2-X05']::text[],false,'{"seq":1,"concept":"K6-2-u2-C3","difficulty":1,"kind":"mc","stem":"면담의 세 절차를 차례대로 바르게 늘어놓은 것은 어느 것인가요?","options":[{"t":"면담 준비하기 → 면담 진행하기 → 면담 정리하기","correct":true},{"t":"면담 진행하기 → 면담 준비하기 → 면담 정리하기","mis":"K6-2-u2-X05"},{"t":"면담 정리하기 → 면담 준비하기 → 면담 진행하기","mis":"K6-2-u2-X05"},{"t":"면담 준비하기 → 면담 정리하기 → 면담 진행하기","mis":"K6-2-u2-X05"}],"explanation":["만나기 전에 준비해요.","만나서 진행해요.","만난 뒤에 정리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L03_basic#2','kor',6,2,'u2','L03','g6_2_kor_u2_L03_basic','lesson_basic','K6-2-u2-C3',1,'mc','auto','시후네 모둠이 면담을 준비하며 맨 먼저 분명히 해야 할 것은 어느 것인가요?',ARRAY['K6-2-u2-X05']::text[],false,'{"seq":2,"concept":"K6-2-u2-C3","difficulty":1,"kind":"mc","stem":"시후네 모둠이 면담을 준비하며 맨 먼저 분명히 해야 할 것은 어느 것인가요?","options":[{"t":"면담으로 무엇을 알고 싶은지 하는 목적","correct":true},{"t":"녹음을 맡을 사람","mis":"K6-2-u2-X05"},{"t":"면담할 날짜","mis":"K6-2-u2-X05"},{"t":"보고서의 제목","mis":"K6-2-u2-X05"}],"explanation":["목적이 정해져야 누구를 만날지 정해져요.","목적이 있어야 질문도 만들 수 있어요.","역할과 날짜는 그다음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L03_basic#3','kor',6,2,'u2','L03','g6_2_kor_u2_L03_basic','lesson_basic','K6-2-u2-C4',1,'mc','auto','「하루에 관측을 몇 번 하시나요?」는 어느 갈래의 질문인가요?',ARRAY['K6-2-u2-X08','K6-2-u2-X05']::text[],false,'{"seq":3,"concept":"K6-2-u2-C4","difficulty":1,"kind":"mc","stem":"「하루에 관측을 몇 번 하시나요?」는 어느 갈래의 질문인가요?","options":[{"t":"구체적인 사실에 대한 질문","correct":true},{"t":"생각이나 느낌에 대한 질문","mis":"K6-2-u2-X08"},{"t":"앞으로의 계획이나 당부에 대한 질문","mis":"K6-2-u2-X08"},{"t":"면담을 마무리하는 인사","mis":"K6-2-u2-X05"}],"explanation":["몇 번 하는지는 있는 그대로의 일이에요.","그래서 구체적인 사실에 대한 질문이에요.","마음을 묻거나 앞일을 묻는 질문이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L03_basic#4','kor',6,2,'u2','L03','g6_2_kor_u2_L03_basic','lesson_basic','K6-2-u2-C3',1,'ox','auto','면담은 면담 대상자와 헤어지는 순간에 끝나요.',ARRAY['K6-2-u2-X05']::text[],false,'{"seq":4,"concept":"K6-2-u2-C3","difficulty":1,"kind":"ox","stem":"면담은 면담 대상자와 헤어지는 순간에 끝나요.","answer":"X","reason_options":[{"t":"들은 것을 간추리고 되돌아보아 쓸 수 있는 형태로 남겨야 끝나기 때문에","correct":true},{"t":"만나서 묻고 답하는 것이 면담의 전부이기 때문에","mis":"K6-2-u2-X05"}],"mis":"K6-2-u2-X05","explanation":["헤어진 뒤에도 면담 정리하기가 남아 있어요.","내용 정리 · 과정 성찰 · 보고서 쓰기를 해요.","들은 것을 남길 때 면담이 끝나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L03_basic#5','kor',6,2,'u2','L03','g6_2_kor_u2_L03_basic','lesson_basic','K6-2-u2-C4',2,'match','auto','시후네 모둠의 질문과 그 갈래를 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K6-2-u2-C4","difficulty":2,"kind":"match","stem":"시후네 모둠의 질문과 그 갈래를 알맞게 이으세요.","pairs":[{"l":"비가 많이 오는 날에는 관측을 어떻게 하시나요?","r":"구체적인 사실에 대한 질문"},{"l":"예보가 맞았을 때 어떤 마음이 드시나요?","r":"생각이나 느낌에 대한 질문"},{"l":"기상 관측사가 되고 싶은 학생에게 해 주실 말씀이 있나요?","r":"앞으로의 계획이나 당부에 대한 질문"}],"mis":"K6-2-u2-X08","explanation":["있었던 일·하는 일을 묻는지 보아요.","마음을 묻는지 보아요.","뒷사람에게 줄 말이나 앞일을 묻는지 보아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L03_basic#6','kor',6,2,'u2','L03','g6_2_kor_u2_L03_basic','lesson_basic','K6-2-u2-C4',2,'mc','auto','시후네 모둠의 면담 목적은 날씨를 살피는 일을 알리는 것이에요. 목적과 이어진 질문은 어느 것인가요?',ARRAY['K6-2-u2-X07']::text[],false,'{"seq":6,"concept":"K6-2-u2-C4","difficulty":2,"kind":"mc","stem":"시후네 모둠의 면담 목적은 날씨를 살피는 일을 알리는 것이에요. 목적과 이어진 질문은 어느 것인가요?","options":[{"t":"관측한 값이 예보로 바뀌기까지 어떤 과정을 거치나요?","correct":true},{"t":"가장 좋아하시는 계절은 무엇인가요?","mis":"K6-2-u2-X07"},{"t":"요즘 즐겨 보시는 영화는 무엇인가요?","mis":"K6-2-u2-X07"},{"t":"어렸을 때 별명은 무엇이었나요?","mis":"K6-2-u2-X07"}],"explanation":["목적은 날씨를 살피는 일을 알리는 것이에요.","관측 값이 예보로 바뀌는 과정이 알리려는 내용이에요.","나머지는 재미있어도 하시는 일을 알 수 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L03_basic#7','kor',6,2,'u2','L03','g6_2_kor_u2_L03_basic','lesson_basic','K6-2-u2-C3',2,'mc','auto','면담 진행하기의 세 단계를 차례대로 바르게 늘어놓은 것은 어느 것인가요?',ARRAY['K6-2-u2-X05']::text[],false,'{"seq":7,"concept":"K6-2-u2-C3","difficulty":2,"kind":"mc","stem":"면담 진행하기의 세 단계를 차례대로 바르게 늘어놓은 것은 어느 것인가요?","options":[{"t":"면담 열기 → 질문하기 → 면담 마무리하기","correct":true},{"t":"질문하기 → 면담 열기 → 면담 마무리하기","mis":"K6-2-u2-X05"},{"t":"면담 열기 → 면담 마무리하기 → 질문하기","mis":"K6-2-u2-X05"},{"t":"면담 마무리하기 → 질문하기 → 면담 열기","mis":"K6-2-u2-X05"}],"explanation":["막 만났을 때 면담을 열어요.","한창 이야기할 때 질문해요.","헤어지기 전에 마무리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L03_basic#8','kor',6,2,'u2','L03','g6_2_kor_u2_L03_basic','lesson_basic','K6-2-u2-C3',2,'mc','auto','면담 열기에서 할 일로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u2-X05','K6-2-u2-X07']::text[],false,'{"seq":8,"concept":"K6-2-u2-C3","difficulty":2,"kind":"mc","stem":"면담 열기에서 할 일로 알맞은 것은 어느 것인가요?","options":[{"t":"인사하고 목적을 설명하고 담아도 될지 여쭙는다","correct":true},{"t":"알게 된 것을 확인하고 감사 인사를 드린다","mis":"K6-2-u2-X05"},{"t":"면담 보고서를 쓴다","mis":"K6-2-u2-X05"},{"t":"그때 처음으로 질문을 만들기 시작한다","mis":"K6-2-u2-X07"}],"explanation":["면담 열기는 진행의 첫 단계예요.","인사 · 목적 설명 · 동의 구하기를 해요.","확인과 감사는 마무리에서 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L03_basic#9','kor',6,2,'u2','L03','g6_2_kor_u2_L03_basic','lesson_basic','K6-2-u2-C4',2,'ox','auto','사실을 묻는 질문만 골라 만들면 면담이 가장 알차요.',ARRAY['K6-2-u2-X08']::text[],false,'{"seq":9,"concept":"K6-2-u2-C4","difficulty":2,"kind":"ox","stem":"사실을 묻는 질문만 골라 만들면 면담이 가장 알차요.","answer":"X","reason_options":[{"t":"사실만 물으면 자료를 읽는 것과 다르지 않아 세 갈래를 골고루 만들어야 하기 때문에","correct":true},{"t":"생각이나 느낌은 면담에서 물으면 안 되기 때문에","mis":"K6-2-u2-X08"}],"mis":"K6-2-u2-X08","explanation":["사실은 찾아봐도 나오는 것이 많아요.","생각이나 느낌, 앞일과 당부도 함께 물어요.","세 갈래를 골고루 만들면 치우치지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L03_basic#10','kor',6,2,'u2','L03','g6_2_kor_u2_L03_basic','lesson_basic','K6-2-u2-C3',3,'error','auto','시후네 모둠이 면담 준비를 하며 말했어요. 차례에 맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u2-X05','K6-2-u2-X09']::text[],false,'{"seq":10,"concept":"K6-2-u2-C3","difficulty":3,"kind":"error","stem":"시후네 모둠이 면담 준비를 하며 말했어요. 차례에 맞지 않게 말한 친구는 누구인가요?","options":[{"t":"가람 — 「목적은 나중에 정하고, 일단 녹음 맡을 사람부터 정하자.」","correct":true,"mis_target":"K6-2-u2-X05"},{"t":"단우 — 「목적이 정해졌으니 그 일을 하시는 분을 대상자로 정하자.」","mis":"K6-2-u2-X05"},{"t":"하온 — 「만나기 전에 관측에 대한 자료를 먼저 찾아보자.」","mis":"K6-2-u2-X09"}],"explanation":["준비하기는 목적을 정하는 데서 시작해요.","목적 → 대상자 → 방식 → 자료 → 질문 → 역할 → 요청이에요.","가람은 목적보다 역할을 먼저 정하려 했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L03_challenge#1','kor',6,2,'u2','L03','g6_2_kor_u2_L03_challenge','lesson_challenge','K6-2-u2-C3',2,'sa','auto','면담 진행하기의 세 단계 가운데 가장 긴 단계는 무엇인가요? 네 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K6-2-u2-C3","difficulty":2,"kind":"sa","stem":"면담 진행하기의 세 단계 가운데 가장 긴 단계는 무엇인가요? 네 글자로 쓰세요.","answer":["질문하기"],"explanation":["면담 열기 · 질문하기 · 면담 마무리하기가 있어요.","질문에 따라 대화의 방향과 얻는 정보가 달라져요.","그래서 질문하기가 가장 길어요."],"mis":"K6-2-u2-X05"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L03_challenge#2','kor',6,2,'u2','L03','g6_2_kor_u2_L03_challenge','lesson_challenge','K6-2-u2-C4',2,'mc','auto','「예보가 빗나갔을 때 어떤 마음이 드시나요?」는 어느 갈래의 질문인가요?',ARRAY['K6-2-u2-X08','K6-2-u2-X05']::text[],false,'{"seq":2,"concept":"K6-2-u2-C4","difficulty":2,"kind":"mc","stem":"「예보가 빗나갔을 때 어떤 마음이 드시나요?」는 어느 갈래의 질문인가요?","options":[{"t":"생각이나 느낌에 대한 질문","correct":true},{"t":"구체적인 사실에 대한 질문","mis":"K6-2-u2-X08"},{"t":"앞으로의 계획이나 당부에 대한 질문","mis":"K6-2-u2-X08"},{"t":"면담 목적을 밝히는 말","mis":"K6-2-u2-X05"}],"explanation":["「어떤 마음」을 묻고 있어요.","그래서 생각이나 느낌에 대한 질문이에요.","이런 질문으로 그분의 마음까지 들을 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L03_challenge#3','kor',6,2,'u2','L03','g6_2_kor_u2_L03_challenge','lesson_challenge','K6-2-u2-C3',3,'mc','auto','면담 준비하기에서 하는 일이 아닌 것은 어느 것인가요?',ARRAY['K6-2-u2-X05']::text[],false,'{"seq":3,"concept":"K6-2-u2-C3","difficulty":3,"kind":"mc","stem":"면담 준비하기에서 하는 일이 아닌 것은 어느 것인가요?","options":[{"t":"들은 내용을 간추리고 잘한 점을 되돌아보기","correct":true},{"t":"면담 방식 정하기","mis":"K6-2-u2-X05"},{"t":"면담 역할 정하기","mis":"K6-2-u2-X05"},{"t":"면담을 요청하고 허락 구하기","mis":"K6-2-u2-X05"}],"explanation":["준비하기에는 여덟 가지 일이 있어요.","방식·역할·요청과 허락도 만나기 전에 해요.","간추리고 되돌아보는 것은 면담 정리하기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L03_challenge#4','kor',6,2,'u2','L03','g6_2_kor_u2_L03_challenge','lesson_challenge','K6-2-u2-C4',3,'mc','auto','자료를 찾아 둔 시후가 「무슨 일 하세요?」 대신 여쭙기로 한 질문은 어느 것인가요?',ARRAY['K6-2-u2-X02']::text[],false,'{"seq":4,"concept":"K6-2-u2-C4","difficulty":3,"kind":"mc","stem":"자료를 찾아 둔 시후가 「무슨 일 하세요?」 대신 여쭙기로 한 질문은 어느 것인가요?","options":[{"t":"「재신 값이 예보에 어떻게 쓰이나요?」","correct":true},{"t":"「기상 관측사는 무엇을 하는 사람인가요?」","mis":"K6-2-u2-X02"},{"t":"「날씨는 왜 바뀌나요?」","mis":"K6-2-u2-X02"},{"t":"「기온은 무엇으로 재나요?」","mis":"K6-2-u2-X02"}],"explanation":["가람은 기상 관측이 기온·바람·비의 양을 재는 일임을 찾아 두었어요.","찾아 둔 것을 바탕으로 한 걸음 더 깊이 물었어요.","다른 보기는 찾아보면 나오는 물음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L03_challenge#5','kor',6,2,'u2','L03','g6_2_kor_u2_L03_challenge','lesson_challenge','K6-2-u2-C2',3,'ox','auto','하온은 면담 날짜와 장소를 모둠이 정해서 오세중 선생님께 알려 드렸어요.',ARRAY['K6-2-u2-X03']::text[],false,'{"seq":5,"concept":"K6-2-u2-C2","difficulty":3,"kind":"ox","stem":"하온은 면담 날짜와 장소를 모둠이 정해서 오세중 선생님께 알려 드렸어요.","answer":"X","reason_options":[{"t":"선생님이 날짜를 말씀하시고 하온이 장소를 여쭈어 함께 맞추어 정했기 때문에","correct":true},{"t":"하온이 「관측소로 찾아뵈어도」라고 장소를 먼저 말했기 때문에","mis":"K6-2-u2-X03"}],"mis":"K6-2-u2-X03","explanation":["「다음 주 화요일 오후는 어떤가요?」는 선생님 말씀이에요.","하온은 「찾아뵈어도 괜찮을까요?」라고 여쭈었어요.","날짜와 장소는 대상자와 맞추어 정해요."],"asset":{"type":"speech","turns":[{"who":"하온","text":"안녕하세요? 저희는 학급 신문을 만드는 6학년 학생들입니다. 날씨를 살피는 일을 알리는 글을 쓰고 싶어 몇 가지 여쭙고 싶습니다."},{"who":"오세중","text":"좋은 주제네요. 다음 주 화요일 오후는 어떤가요?"},{"who":"하온","text":"네, 감사합니다. 삼십 분 정도면 될 것 같습니다. 관측소로 찾아뵈어도 괜찮을까요?"},{"who":"오세중","text":"그러지요. 그때 뵙겠습니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L03_challenge#6','kor',6,2,'u2','L03','g6_2_kor_u2_L03_challenge','lesson_challenge','K6-2-u2-C4',3,'error','auto','시후네 모둠이 만든 질문을 고르며 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u2-X07','K6-2-u2-X08']::text[],false,'{"seq":6,"concept":"K6-2-u2-C4","difficulty":3,"kind":"error","stem":"시후네 모둠이 만든 질문을 고르며 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"시후 — 「재미있으니까 ‘좋아하시는 노래’ 질문도 꼭 넣자.」","correct":true,"mis_target":"K6-2-u2-X07"},{"t":"가람 — 「기온을 잴 때 조심하시는 점은 날씨 일과 이어지니 넣자.」","mis":"K6-2-u2-X07"},{"t":"단우 — 「사실 질문만 있으니 느낌을 묻는 질문도 하나 넣자.」","mis":"K6-2-u2-X08"}],"explanation":["질문은 면담 목적과 견주어 골라요.","좋아하는 노래는 날씨를 살피는 일과 이어지지 않아요.","가람과 단우는 목적과 갈래를 살폈어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L03_challenge#7','kor',6,2,'u2','L03','g6_2_kor_u2_L03_challenge','lesson_challenge','K6-2-u2-C3',3,'match','auto','면담 정리하기에서 하는 일과 그 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K6-2-u2-C3","difficulty":3,"kind":"match","stem":"면담 정리하기에서 하는 일과 그 뜻을 알맞게 이으세요.","pairs":[{"l":"면담 내용 정리하기","r":"담아 둔 것과 메모를 보며 간추린다"},{"l":"면담 과정 성찰하기","r":"잘한 점과 보완할 점을 되돌아본다"},{"l":"면담 보고서 쓰기","r":"알게 된 것을 글로 정리해 나눈다"}],"mis":"K6-2-u2-X05","explanation":["면담은 헤어지는 순간에 끝나지 않아요.","간추리고 · 되돌아보고 · 써서 나눠요.","그래야 들은 것을 쓸 수 있게 남겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L03_challenge#8','kor',6,2,'u2','L03','g6_2_kor_u2_L03_challenge','lesson_challenge','K6-2-u2-C4',4,'mc','auto','면담 질문을 세 갈래로 골고루 만들어야 하는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u2-X08']::text[],false,'{"seq":8,"concept":"K6-2-u2-C4","difficulty":4,"kind":"mc","stem":"면담 질문을 세 갈래로 골고루 만들어야 하는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"사실·마음·앞일을 함께 물어야 그분의 일과 생각을 고루 듣고 면담이 한쪽으로 치우치지 않기 때문에","correct":true},{"t":"질문 수를 꼭 셋으로 맞추어야 하기 때문에","mis":"K6-2-u2-X08"},{"t":"사실을 묻는 질문은 면담에서 하면 안 되기 때문에","mis":"K6-2-u2-X08"},{"t":"갈래가 많을수록 면담 시간이 짧아지기 때문에","mis":"K6-2-u2-X08"}],"explanation":["갈래가 다르면 얻는 것도 달라요.","사실만 물으면 자료를 읽는 것과 같아요.","세 갈래를 고루 물으면 일과 마음이 함께 드러나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L03_challenge#9','kor',6,2,'u2','L03','g6_2_kor_u2_L03_challenge','lesson_challenge','K6-2-u2-C4',4,'essay','teacher','내가 만나고 싶은 분을 정해 면담 목적을 한 문장으로 쓰고, 그 목적에 맞는 질문을 세 갈래로 하나씩 만드세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u2-C4","difficulty":4,"kind":"essay","stem":"내가 만나고 싶은 분을 정해 면담 목적을 한 문장으로 쓰고, 그 목적에 맞는 질문을 세 갈래로 하나씩 만드세요.","answer_guide":{"answer":"예: 만날 분 — 우리 동네 소방관. 목적 — 소방관이 하루에 하는 일과 이 일을 하려면 무엇이 필요한지 알아보려고. 사실 — 출동이 없을 때는 주로 어떤 일을 하시나요? 생각이나 느낌 — 처음 불을 끄러 나가셨을 때 어떤 마음이 드셨나요? 계획이나 당부 — 소방관이 되고 싶은 학생에게 해 주실 말씀이 있나요?","scoring_points":["면담 목적을 분명하게 한 문장으로 썼는가","사실·생각이나 느낌·계획이나 당부의 세 갈래로 질문을 만들었는가","세 질문이 모두 목적과 이어지는가"]},"explanation":["목적이 분명하면 질문이 저절로 나와요.","세 갈래를 하나씩 만들어요.","목적과 이어지는지 다시 견주어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L03_challenge#10','kor',6,2,'u2','L03','g6_2_kor_u2_L03_challenge','lesson_challenge','K6-2-u2-C3',4,'essay','teacher','면담의 세 절차를 차례대로 쓰고, 절차마다 하는 일을 두 가지씩 쓰세요. 면담이 언제 끝나는지도 한 문장으로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u2-C3","difficulty":4,"kind":"essay","stem":"면담의 세 절차를 차례대로 쓰고, 절차마다 하는 일을 두 가지씩 쓰세요. 면담이 언제 끝나는지도 한 문장으로 쓰세요.","answer_guide":{"answer":"예: 면담 준비하기 — 목적과 대상자를 정하고, 자료를 찾아 질문을 만든다. 면담 진행하기 — 인사하고 목적을 밝힌 뒤 세 갈래로 묻고, 알게 된 것을 확인하고 감사 인사를 드린다. 면담 정리하기 — 담아 둔 것과 메모로 내용을 간추리고, 과정을 되돌아보아 보고서를 쓴다. 면담은 헤어질 때가 아니라 들은 것을 보고서처럼 쓸 수 있는 형태로 남길 때 끝난다.","scoring_points":["세 절차를 차례대로 썼는가","절차마다 하는 일을 두 가지씩 바르게 썼는가","면담이 끝나는 때를 바르게 썼는가"]},"explanation":["준비 → 진행 → 정리예요.","절차마다 할 일이 달라요.","남길 때 끝나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L05_basic#1','kor',6,2,'u2','L05','g6_2_kor_u2_L05_basic','lesson_basic','K6-2-u2-C5',1,'mc','auto','진로 정보를 얻는 방법을 함께 쓸 때 가장 좋은 차례는 어느 것인가요?',ARRAY['K6-2-u2-X07','K6-2-u2-X02','K6-2-u2-X11']::text[],false,'{"seq":1,"concept":"K6-2-u2-C5","difficulty":1,"kind":"mc","stem":"진로 정보를 얻는 방법을 함께 쓸 때 가장 좋은 차례는 어느 것인가요?","options":[{"t":"누리집과 책으로 바탕을 쌓고, 거기서 생긴 궁금함을 면담으로 푼다","correct":true},{"t":"아무것도 찾지 않고 바로 면담부터 한다","mis":"K6-2-u2-X07"},{"t":"누리집만 보고 면담은 하지 않는다","mis":"K6-2-u2-X02"},{"t":"면담에서 들은 것을 누리집에 그대로 올린다","mis":"K6-2-u2-X11"}],"explanation":["검색과 책은 바탕을 쌓는 데 좋아요.","그 일을 하는 분께 들으면 하루의 모습과 마음까지 알 수 있어요.","찾아 둔 것 위에서 면담하면 더 깊어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L05_basic#2','kor',6,2,'u2','L05','g6_2_kor_u2_L05_basic','lesson_basic','K6-2-u2-C5',1,'mc','auto','은새와 솔찬이 노윤재 선생님과 면담한 목적은 어느 것인가요?',ARRAY['K6-2-u2-X01','K6-2-u2-X04']::text[],false,'{"seq":2,"concept":"K6-2-u2-C5","difficulty":1,"kind":"mc","stem":"은새와 솔찬이 노윤재 선생님과 면담한 목적은 어느 것인가요?","options":[{"t":"수어 통역사가 하는 일과 이 일을 하려면 무엇이 필요한지 알아보려고","correct":true},{"t":"수어를 배워 바로 써 보려고","mis":"K6-2-u2-X01"},{"t":"어느 직업이 더 좋은지 가려내려고","mis":"K6-2-u2-X01"},{"t":"선생님의 가족 이야기를 들으려고","mis":"K6-2-u2-X04"}],"explanation":["솔찬이 면담 열기에서 목적을 분명히 밝혔어요.","「하시는 일과 … 무엇이 필요한지 여쭙고자 합니다.」","목적은 열기에서 학생이 직접 말해요."],"asset":{"type":"speech","turns":[{"who":"은새","text":"안녕하세요? 만나 뵙게 되어 반갑습니다. 바쁘신데 시간 내어 주셔서 감사합니다."},{"who":"솔찬","text":"요청드릴 때 말씀드린 것처럼, 오늘은 수어 통역사가 하시는 일과 이 일을 하려면 무엇이 필요한지 여쭙고자 합니다."},{"who":"은새","text":"답변을 정확히 정리하려고 녹음을 하고 싶은데 괜찮으실까요?"},{"who":"노윤재","text":"네, 괜찮습니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L05_basic#3','kor',6,2,'u2','L05','g6_2_kor_u2_L05_basic','lesson_basic','K6-2-u2-C5',1,'sa','auto','면담 대상자의 답을 듣고 더 자세히 알려고 이어서 하는 질문을 무엇이라고 하나요? 「○○ 질문」에서 ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"K6-2-u2-C5","difficulty":1,"kind":"sa","stem":"면담 대상자의 답을 듣고 더 자세히 알려고 이어서 하는 질문을 무엇이라고 하나요? 「○○ 질문」에서 ○○에 알맞은 두 글자를 쓰세요.","answer":["후속"],"explanation":["답을 듣다가 생긴 물음이에요.","미리 만들어 갈 수 없고 듣고 있어야만 나와요.","이것을 후속 질문이라고 해요."],"mis":"K6-2-u2-X06"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L05_basic#4','kor',6,2,'u2','L05','g6_2_kor_u2_L05_basic','lesson_basic','K6-2-u2-C6',1,'ox','auto','면담 대상자가 말씀하시는 도중에 떠오른 물음은 바로 끼어들어 여쭈어야 해요.',ARRAY['K6-2-u2-X10']::text[],false,'{"seq":4,"concept":"K6-2-u2-C6","difficulty":1,"kind":"ox","stem":"면담 대상자가 말씀하시는 도중에 떠오른 물음은 바로 끼어들어 여쭈어야 해요.","answer":"X","reason_options":[{"t":"말씀을 끊지 않고 메모해 두었다가 뒤에 여쭈는 것이 예의이기 때문에","correct":true},{"t":"잊어버리기 전에 묻는 것이 더 중요하기 때문에","mis":"K6-2-u2-X10"}],"mis":"K6-2-u2-X10","explanation":["말씀 도중에 끊지 않아요.","떠오른 물음은 메모해 두어요.","말씀이 끝나면 그때 여쭈어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L05_basic#5','kor',6,2,'u2','L05','g6_2_kor_u2_L05_basic','lesson_basic','K6-2-u2-C5',2,'mc','auto','은새의 「방금 ‘다시 짜야 한다’고 하셨는데, 그럴 때는 어떻게 하시나요?」가 후속 질문인 까닭은 어느 것인가요?',ARRAY['K6-2-u2-X06','K6-2-u2-X05','K6-2-u2-X07']::text[],false,'{"seq":5,"concept":"K6-2-u2-C5","difficulty":2,"kind":"mc","stem":"은새의 「방금 ‘다시 짜야 한다’고 하셨는데, 그럴 때는 어떻게 하시나요?」가 후속 질문인 까닭은 어느 것인가요?","options":[{"t":"앞선 답에 나온 말을 붙들고 더 자세히 알려고 이어서 물었기 때문에","correct":true},{"t":"질문지에 미리 적어 간 첫 질문이기 때문에","mis":"K6-2-u2-X06"},{"t":"면담을 마무리하는 인사이기 때문에","mis":"K6-2-u2-X05"},{"t":"면담 목적과 상관없는 질문이기 때문에","mis":"K6-2-u2-X07"}],"explanation":["「다시 짜야 한다」는 바로 앞 답에 나온 말이에요.","은새는 그 말을 붙들고 이어서 물었어요.","그 덕분에 「함께 만드는 일」이라는 가장 중요한 답이 나왔어요."],"asset":{"type":"speech","turns":[{"who":"솔찬","text":"수어 통역사는 하루에 주로 어떤 일을 하시나요?"},{"who":"노윤재","text":"회의나 진료, 수업처럼 말이 오가는 자리에 함께 갑니다. 들은 말을 손으로 옮기고, 손으로 하신 말을 소리로 옮깁니다."},{"who":"은새","text":"말을 옮기실 때 가장 어려운 점은 무엇인가요?"},{"who":"노윤재","text":"낱말을 그대로 옮기는 것으로는 뜻이 전해지지 않을 때가 있습니다. 그럴 때는 뜻이 살아나도록 다시 짜야 합니다."},{"who":"은새","text":"방금 「다시 짜야 한다」고 하셨는데, 그럴 때는 어떻게 하시나요?"},{"who":"노윤재","text":"말한 분께 무엇을 전하고 싶으신지 한 번 더 여쭙습니다. 통역은 혼자 하는 일이 아니라 함께 만드는 일입니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L05_basic#6','kor',6,2,'u2','L05','g6_2_kor_u2_L05_basic','lesson_basic','K6-2-u2-C5',2,'match','auto','면담 자료 속 말과 그 말이 나오는 진행 단계를 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u2-C5","difficulty":2,"kind":"match","stem":"면담 자료 속 말과 그 말이 나오는 진행 단계를 알맞게 이으세요.","pairs":[{"l":"녹음을 하고 싶은데 괜찮으실까요?","r":"면담 열기"},{"l":"말을 옮기실 때 가장 어려운 점은 무엇인가요?","r":"질문하기"},{"l":"말씀이 인상 깊었습니다. 오늘 감사합니다.","r":"면담 마무리하기"}],"mis":"K6-2-u2-X05","explanation":["동의를 구하는 말은 면담 열기에 나와요.","세 갈래 질문은 질문하기에 나와요.","알게 된 것 확인과 감사는 마무리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L05_basic#7','kor',6,2,'u2','L05','g6_2_kor_u2_L05_basic','lesson_basic','K6-2-u2-C6',2,'mc','auto','면담에서 지켜야 할 예절로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u2-X10','K6-2-u2-X11']::text[],false,'{"seq":7,"concept":"K6-2-u2-C6","difficulty":2,"kind":"mc","stem":"면담에서 지켜야 할 예절로 알맞은 것은 어느 것인가요?","options":[{"t":"답을 끝까지 귀 기울여 듣고, 끝난 뒤 감사 인사를 드린다","correct":true},{"t":"답이 길면 도중에 끊고 다음 질문으로 간다","mis":"K6-2-u2-X10"},{"t":"답이 마음에 안 들면 다시 답하게 한다","mis":"K6-2-u2-X10"},{"t":"녹음은 말씀드리지 않고 몰래 한다","mis":"K6-2-u2-X11"}],"explanation":["예의가 있어야 답이 깊어져요.","끝까지 듣고, 담기 전에 동의를 구하고, 감사 인사를 드려요.","끊기·다시 답하게 하기는 예절이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L05_basic#8','kor',6,2,'u2','L05','g6_2_kor_u2_L05_basic','lesson_basic','K6-2-u2-C6',2,'mc','auto','면담에서 질문을 짧게 해야 하는 까닭은 어느 것인가요?',ARRAY['K6-2-u2-X10','K6-2-u2-X08','K6-2-u2-X13']::text[],false,'{"seq":8,"concept":"K6-2-u2-C6","difficulty":2,"kind":"mc","stem":"면담에서 질문을 짧게 해야 하는 까닭은 어느 것인가요?","options":[{"t":"설명이 길면 무엇을 묻는지 흐려지기 때문에","correct":true},{"t":"면담 시간을 일부러 줄이려고","mis":"K6-2-u2-X10"},{"t":"짧은 질문은 사실만 묻기 때문에","mis":"K6-2-u2-X08"},{"t":"답도 짧게 받아 적기 쉽게 하려고","mis":"K6-2-u2-X13"}],"explanation":["질문이 길면 듣는 분이 무엇을 묻는지 헷갈려요.","짧고 분명하게 물어요.","그래야 답하시는 분이 편하게 말씀하실 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L05_basic#9','kor',6,2,'u2','L05','g6_2_kor_u2_L05_basic','lesson_basic','K6-2-u2-C6',2,'mc','auto','진로 자료를 찾을 때 믿을 만한 출처는 어느 것인가요?',ARRAY['K6-2-u2-X09']::text[],false,'{"seq":9,"concept":"K6-2-u2-C6","difficulty":2,"kind":"mc","stem":"진로 자료를 찾을 때 믿을 만한 출처는 어느 것인가요?","options":[{"t":"누가 만든 자료인지 밝혀져 있고 언제 만든 것인지 적혀 있는 자료","correct":true},{"t":"검색하면 맨 위에 나오는 자료","mis":"K6-2-u2-X09"},{"t":"사진이 많아 보기 좋은 자료","mis":"K6-2-u2-X09"},{"t":"누가 썼는지 알 수 없지만 재미있는 자료","mis":"K6-2-u2-X09"}],"explanation":["자료를 찾을 때는 출처를 꼭 확인해요.","누가·언제 만들었는지가 밝혀져야 믿을 수 있어요.","순서·사진·재미는 기준이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L05_basic#10','kor',6,2,'u2','L05','g6_2_kor_u2_L05_basic','lesson_basic','K6-2-u2-C5',3,'error','auto','노윤재 선생님 면담을 읽고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u2-X06']::text[],false,'{"seq":10,"concept":"K6-2-u2-C5","difficulty":3,"kind":"error","stem":"노윤재 선생님 면담을 읽고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서진 — 「후속 질문도 미리 질문지에 다 적어 가야 해.」","correct":true,"mis_target":"K6-2-u2-X06"},{"t":"유나 — 「후속 질문은 답을 잘 듣고 있어야만 나와.」","mis":"K6-2-u2-X06"},{"t":"태오 — 「그 한 번의 물음 덕분에 가장 중요한 답이 나왔어.」","mis":"K6-2-u2-X06"}],"explanation":["후속 질문은 답을 듣고 나서 생기는 물음이에요.","그래서 미리 적어 갈 수 없어요.","유나와 태오는 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L05_challenge#1','kor',6,2,'u2','L05','g6_2_kor_u2_L05_challenge','lesson_challenge','K6-2-u2-C6',2,'sa','auto','만든 질문을 점검하는 세 가지 물음은 「목적에 맞는가 · 예의를 갖추었는가 · 이해할 수 있게 ○○한가」예요. ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K6-2-u2-C6","difficulty":2,"kind":"sa","stem":"만든 질문을 점검하는 세 가지 물음은 「목적에 맞는가 · 예의를 갖추었는가 · 이해할 수 있게 ○○한가」예요. ○○에 알맞은 두 글자를 쓰세요.","answer":["명료"],"explanation":["질문은 만든 뒤 스스로 점검해요.","목적·예의·명료함을 살펴요.","명료하다는 것은 뜻이 분명하다는 말이에요."],"mis":"K6-2-u2-X07"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L05_challenge#2','kor',6,2,'u2','L05','g6_2_kor_u2_L05_challenge','lesson_challenge','K6-2-u2-C5',2,'mc','auto','노윤재 선생님의 답 「손 모양을 외우는 것보다 사람의 말을 끝까지 듣는 연습이 먼저입니다.」를 듣고 할 수 있는 후속 질문은 어느 것인가요?',ARRAY['K6-2-u2-X06','K6-2-u2-X07','K6-2-u2-X02']::text[],false,'{"seq":2,"concept":"K6-2-u2-C5","difficulty":2,"kind":"mc","stem":"노윤재 선생님의 답 「손 모양을 외우는 것보다 사람의 말을 끝까지 듣는 연습이 먼저입니다.」를 듣고 할 수 있는 후속 질문은 어느 것인가요?","options":[{"t":"「끝까지 듣는 연습은 어떻게 하면 좋을까요?」","correct":true},{"t":"「다음 질문입니다. 이 일은 언제부터 하셨나요?」","mis":"K6-2-u2-X06"},{"t":"「점심은 보통 몇 시에 드시나요?」","mis":"K6-2-u2-X07"},{"t":"「수어의 손 모양은 모두 몇 가지인가요?」","mis":"K6-2-u2-X02"}],"explanation":["후속 질문은 앞선 답에 나온 말을 붙들어요.","「끝까지 듣는 연습」을 붙들고 더 자세히 물었어요.","다른 보기는 앞의 답을 듣지 않아도 할 수 있는 물음이에요."],"asset":{"type":"speech","turns":[{"who":"솔찬","text":"이 일을 하고 싶은 학생에게 해 주고 싶으신 말씀이 있나요?"},{"who":"노윤재","text":"손 모양을 외우는 것보다 사람의 말을 끝까지 듣는 연습이 먼저입니다. 끝까지 들어야 무엇을 옮길지 알 수 있습니다."},{"who":"은새","text":"통역이 낱말을 바꾸는 일이 아니라 뜻을 함께 만드는 일이라는 말씀이 인상 깊었습니다. 오늘 감사합니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L05_challenge#3','kor',6,2,'u2','L05','g6_2_kor_u2_L05_challenge','lesson_challenge','K6-2-u2-C6',3,'mc','auto','「선생님 하시는 일 그거 힘든 거 맞죠? 그리고 그때 그거는 어떻게 된 거고 또 다른 건요?」를 점검할 때 가장 먼저 고칠 점은 어느 것인가요?',ARRAY['K6-2-u2-X10','K6-2-u2-X04','K6-2-u2-X08']::text[],false,'{"seq":3,"concept":"K6-2-u2-C6","difficulty":3,"kind":"mc","stem":"「선생님 하시는 일 그거 힘든 거 맞죠? 그리고 그때 그거는 어떻게 된 거고 또 다른 건요?」를 점검할 때 가장 먼저 고칠 점은 어느 것인가요?","options":[{"t":"여러 가지를 한꺼번에 흐리게 물어 뜻이 분명하지 않다","correct":true},{"t":"질문이 너무 짧다","mis":"K6-2-u2-X10"},{"t":"개인 정보를 물었다","mis":"K6-2-u2-X04"},{"t":"사실을 묻는 질문이라 쓸 수 없다","mis":"K6-2-u2-X08"}],"explanation":["「그거」, 「그때」가 무엇을 가리키는지 알 수 없어요.","한 번에 여러 가지를 묻고 있어요.","하나씩 짧고 분명하게 고쳐 물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L05_challenge#4','kor',6,2,'u2','L05','g6_2_kor_u2_L05_challenge','lesson_challenge','K6-2-u2-C5',3,'ox','auto','좋은 면담은 준비한 질문 없이 그 자리에서 떠오르는 대로 묻는 면담이에요.',ARRAY['K6-2-u2-X07']::text[],false,'{"seq":4,"concept":"K6-2-u2-C5","difficulty":3,"kind":"ox","stem":"좋은 면담은 준비한 질문 없이 그 자리에서 떠오르는 대로 묻는 면담이에요.","answer":"X","reason_options":[{"t":"준비한 질문으로 길을 잡고, 듣다가 생긴 물음으로 깊이 들어가야 하기 때문에","correct":true},{"t":"미리 준비하면 후속 질문을 할 수 없기 때문에","mis":"K6-2-u2-X07"}],"mis":"K6-2-u2-X07","explanation":["준비 없이 가면 목적에서 벗어난 이야기로 흘러가요.","준비한 질문만 읽으면 후속 질문이 없어요.","둘 다 해야 좋은 면담이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L05_challenge#5','kor',6,2,'u2','L05','g6_2_kor_u2_L05_challenge','lesson_challenge','K6-2-u2-C5',3,'mc','auto','준비한 질문 열 개를 차례대로 읽기만 하고 나온 면담에서 생기는 일로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u2-X07','K6-2-u2-X06']::text[],false,'{"seq":5,"concept":"K6-2-u2-C5","difficulty":3,"kind":"mc","stem":"준비한 질문 열 개를 차례대로 읽기만 하고 나온 면담에서 생기는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"답을 듣지 않아 후속 질문이 없고 자료에 이미 있는 것만 남는다","correct":true},{"t":"목적에서 벗어난 이야기로만 흘러간다","mis":"K6-2-u2-X07"},{"t":"면담 대상자가 더 깊은 이야기를 해 준다","mis":"K6-2-u2-X06"},{"t":"가장 알찬 면담이 된다","mis":"K6-2-u2-X06"}],"explanation":["읽기만 하면 답을 듣지 않게 돼요.","그러면 이어서 물을 것이 생기지 않아요.","한쪽으로 치우친 면담이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L05_challenge#6','kor',6,2,'u2','L05','g6_2_kor_u2_L05_challenge','lesson_challenge','K6-2-u2-C6',3,'error','auto','면담하며 듣는 태도를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u2-X10']::text[],false,'{"seq":6,"concept":"K6-2-u2-C6","difficulty":3,"kind":"error","stem":"면담하며 듣는 태도를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지민 — 「말씀이 길어지면 끊고 내가 궁금한 걸 먼저 여쭤.」","correct":true,"mis_target":"K6-2-u2-X10"},{"t":"수빈 — 「떠오른 물음은 메모해 두었다가 말씀이 끝나면 여쭈어.」","mis":"K6-2-u2-X10"},{"t":"건우 — 「고개를 끄덕이며 듣고 있다는 걸 보여 드려.」","mis":"K6-2-u2-X10"}],"explanation":["답의 깊이를 정하는 것은 듣는 태도예요.","말씀 도중에 끊지 않아요.","수빈과 건우는 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L05_challenge#7','kor',6,2,'u2','L05','g6_2_kor_u2_L05_challenge','lesson_challenge','K6-2-u2-C6',3,'match','auto','면담 열기에서 한 말과 그 말에 담긴 예의를 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K6-2-u2-C6","difficulty":3,"kind":"match","stem":"면담 열기에서 한 말과 그 말에 담긴 예의를 알맞게 이으세요.","pairs":[{"l":"만나 뵙게 되어 반갑습니다.","r":"반갑게 인사하기"},{"l":"바쁘신데 시간 내어 주셔서 감사합니다.","r":"시간을 내어 주신 데 감사하기"},{"l":"오늘은 하시는 일을 여쭙고자 합니다.","r":"면담 목적 밝히기"},{"l":"녹음을 해도 괜찮으실까요?","r":"담기 전에 동의 구하기"}],"mis":"K6-2-u2-X10","explanation":["면담 열기의 말에는 예의가 담겨 있어요.","인사 · 감사 · 목적 · 동의를 갖추어요.","그래야 그분이 편안하게 말씀하실 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L05_challenge#8','kor',6,2,'u2','L05','g6_2_kor_u2_L05_challenge','lesson_challenge','K6-2-u2-C5',4,'mc','auto','노윤재 선생님의 말씀과 은새의 마무리 말로 보아, 이 면담에서 얻은 가장 중요한 정보는 어느 것인가요?',ARRAY['K6-2-u2-X13']::text[],false,'{"seq":8,"concept":"K6-2-u2-C5","difficulty":4,"kind":"mc","stem":"노윤재 선생님의 말씀과 은새의 마무리 말로 보아, 이 면담에서 얻은 가장 중요한 정보는 어느 것인가요?","options":[{"t":"통역은 낱말을 바꾸는 일이 아니라 사람의 말을 끝까지 듣고 뜻을 함께 만드는 일이다","correct":true},{"t":"통역사는 무엇보다 손 모양을 많이 외워야 한다","mis":"K6-2-u2-X13"},{"t":"통역은 혼자 빨리 해내야 하는 일이다","mis":"K6-2-u2-X13"},{"t":"수어 통역사가 되기는 너무 어려우니 하지 않는 것이 좋다","mis":"K6-2-u2-X13"}],"explanation":["선생님은 끝까지 듣는 연습이 먼저라고 하셨어요.","앞에서 통역은 함께 만드는 일이라고도 하셨어요.","은새도 그 말씀을 확인하며 마무리했어요."],"asset":{"type":"speech","turns":[{"who":"솔찬","text":"이 일을 하고 싶은 학생에게 해 주고 싶으신 말씀이 있나요?"},{"who":"노윤재","text":"손 모양을 외우는 것보다 사람의 말을 끝까지 듣는 연습이 먼저입니다. 끝까지 들어야 무엇을 옮길지 알 수 있습니다."},{"who":"은새","text":"통역이 낱말을 바꾸는 일이 아니라 뜻을 함께 만드는 일이라는 말씀이 인상 깊었습니다. 오늘 감사합니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L05_challenge#9','kor',6,2,'u2','L05','g6_2_kor_u2_L05_challenge','lesson_challenge','K6-2-u2-C5',4,'essay','teacher','노윤재 선생님의 답 「회의나 진료, 수업처럼 말이 오가는 자리에 함께 갑니다.」를 들었다고 할 때, 할 수 있는 후속 질문을 두 가지 만들고 그 질문이 후속 질문이라고 할 수 있는 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u2-C5","difficulty":4,"kind":"essay","stem":"노윤재 선생님의 답 「회의나 진료, 수업처럼 말이 오가는 자리에 함께 갑니다.」를 들었다고 할 때, 할 수 있는 후속 질문을 두 가지 만들고 그 질문이 후속 질문이라고 할 수 있는 까닭을 쓰세요.","answer_guide":{"answer":"예: 후속 질문 1 — 진료하는 자리에서 통역하실 때는 무엇을 가장 조심하시나요? 후속 질문 2 — 말이 오가는 자리마다 통역하는 방법이 달라지나요? 두 질문 모두 앞선 답에 나온 「진료」, 「말이 오가는 자리」를 붙들고 더 자세히 알려고 이어서 물은 것이어서, 답을 듣지 않았다면 만들 수 없는 후속 질문이다.","scoring_points":["앞선 답에 나온 말을 붙든 질문을 두 가지 만들었는가","더 자세히 알려는 질문인가","답을 들어야만 나오는 질문이라는 까닭을 썼는가"]},"explanation":["후속 질문은 앞선 답의 말에서 나와요.","그 말을 붙들어 더 자세히 물어요.","미리 만들어 갈 수 없어요."],"asset":{"type":"speech","turns":[{"who":"솔찬","text":"수어 통역사는 하루에 주로 어떤 일을 하시나요?"},{"who":"노윤재","text":"회의나 진료, 수업처럼 말이 오가는 자리에 함께 갑니다. 들은 말을 손으로 옮기고, 손으로 하신 말을 소리로 옮깁니다."},{"who":"은새","text":"말을 옮기실 때 가장 어려운 점은 무엇인가요?"},{"who":"노윤재","text":"낱말을 그대로 옮기는 것으로는 뜻이 전해지지 않을 때가 있습니다. 그럴 때는 뜻이 살아나도록 다시 짜야 합니다."},{"who":"은새","text":"방금 「다시 짜야 한다」고 하셨는데, 그럴 때는 어떻게 하시나요?"},{"who":"노윤재","text":"말한 분께 무엇을 전하고 싶으신지 한 번 더 여쭙습니다. 통역은 혼자 하는 일이 아니라 함께 만드는 일입니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L05_challenge#10','kor',6,2,'u2','L05','g6_2_kor_u2_L05_challenge','lesson_challenge','K6-2-u2-C6',4,'essay','teacher','면담 목적이 「수어 통역사가 하는 일 알아보기」일 때, 다음 두 질문을 「목적에 맞는가 · 예의를 갖추었는가 · 뜻이 분명한가」로 점검하고 고쳐 쓰세요. ① 「돈은 얼마나 버세요?」 ② 「그 일 힘들어요 안 힘들어요 그리고 언제 쉬어요?」','{}'::text[],false,'{"seq":10,"concept":"K6-2-u2-C6","difficulty":4,"kind":"essay","stem":"면담 목적이 「수어 통역사가 하는 일 알아보기」일 때, 다음 두 질문을 「목적에 맞는가 · 예의를 갖추었는가 · 뜻이 분명한가」로 점검하고 고쳐 쓰세요. ① 「돈은 얼마나 버세요?」 ② 「그 일 힘들어요 안 힘들어요 그리고 언제 쉬어요?」","answer_guide":{"answer":"예: ①은 버는 돈이라는 개인 정보를 묻고 목적과도 이어지지 않으므로 「이 일을 하며 가장 보람 있었던 때는 언제인가요?」로 고친다. ②는 여러 가지를 한꺼번에 묻고 높임도 갖추지 않아 뜻이 흐리므로 「통역하실 때 가장 힘든 점은 무엇인가요?」처럼 하나만 예의 바르게 묻는다.","scoring_points":["①의 문제(개인 정보·목적과 무관)를 찾았는가","②의 문제(여러 가지를 한꺼번에·예의 부족·뜻이 흐림)를 찾았는가","두 질문을 목적에 맞고 예의 바르고 분명하게 고쳐 썼는가"]},"explanation":["목적에 맞는지 먼저 봐요.","높임과 예의를 갖추었는지 봐요.","하나씩 분명하게 물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L07_basic#1','kor',6,2,'u2','L07','g6_2_kor_u2_L07_basic','lesson_basic','K6-2-u2-C7',1,'mc','auto','대면 면담의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u2-X12']::text[],false,'{"seq":1,"concept":"K6-2-u2-C7","difficulty":1,"kind":"mc","stem":"대면 면담의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"면담 대상자를 직접 만나 얼굴을 마주 보고 하는 면담","correct":true},{"t":"영상 통화나 전자 우편으로 주고받는 면담","mis":"K6-2-u2-X12"},{"t":"질문지를 보내 두고 답만 받아 오는 면담","mis":"K6-2-u2-X12"},{"t":"친구끼리 짝을 지어 연습하는 면담","mis":"K6-2-u2-X12"}],"explanation":["대면은 얼굴을 마주한다는 뜻이에요.","표정과 몸짓까지 볼 수 있어요.","영상 통화·전자 우편은 비대면 면담이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L07_basic#2','kor',6,2,'u2','L07','g6_2_kor_u2_L07_basic','lesson_basic','K6-2-u2-C7',1,'mc','auto','매체의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u2-X12','K6-2-u2-X08','K6-2-u2-X15']::text[],false,'{"seq":2,"concept":"K6-2-u2-C7","difficulty":1,"kind":"mc","stem":"매체의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"소통을 이어 주는 도구와 환경","correct":true},{"t":"면담 대상자에게 드리는 선물","mis":"K6-2-u2-X12"},{"t":"면담에서 묻는 질문의 갈래","mis":"K6-2-u2-X08"},{"t":"면담이 끝나고 쓰는 글","mis":"K6-2-u2-X15"}],"explanation":["책·텔레비전·스마트폰·컴퓨터·누리집이 모두 매체예요.","사람과 사람의 소통을 이어 줘요.","면담에서는 절차마다 쓸모 있는 매체가 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L07_basic#3','kor',6,2,'u2','L07','g6_2_kor_u2_L07_basic','lesson_basic','K6-2-u2-C7',1,'ox','auto','말씀을 놓칠까 봐 걱정되면 허락을 받지 않고 녹음해도 괜찮아요.',ARRAY['K6-2-u2-X11']::text[],false,'{"seq":3,"concept":"K6-2-u2-C7","difficulty":1,"kind":"ox","stem":"말씀을 놓칠까 봐 걱정되면 허락을 받지 않고 녹음해도 괜찮아요.","answer":"X","reason_options":[{"t":"담기 전에 먼저 여쭈어보고 허락을 받아야 하기 때문에","correct":true},{"t":"정확히 남기는 것이 무엇보다 중요하기 때문에","mis":"K6-2-u2-X11"}],"mis":"K6-2-u2-X11","explanation":["담는 일에는 먼저 허락이 필요해요.","말없이 녹음하면 안 돼요.","그분의 허락 안에서만 담을 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L07_basic#4','kor',6,2,'u2','L07','g6_2_kor_u2_L07_basic','lesson_basic','K6-2-u2-C8',1,'mc','auto','모둠 역할 가운데 기기를 준비하고 허락을 받아 담아 모둠과 나누는 사람은 누구인가요?',ARRAY['K6-2-u2-X19']::text[],false,'{"seq":4,"concept":"K6-2-u2-C8","difficulty":1,"kind":"mc","stem":"모둠 역할 가운데 기기를 준비하고 허락을 받아 담아 모둠과 나누는 사람은 누구인가요?","options":[{"t":"매체 담당","correct":true},{"t":"진행 담당","mis":"K6-2-u2-X19"},{"t":"약속 담당","mis":"K6-2-u2-X19"},{"t":"정리 담당","mis":"K6-2-u2-X19"}],"explanation":["기기를 다루는 사람은 매체 담당이에요.","진행 담당은 시간을, 약속 담당은 날짜를 맡아요.","정리 담당은 메모와 보고서 자료를 맡아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L07_basic#5','kor',6,2,'u2','L07','g6_2_kor_u2_L07_basic','lesson_basic','K6-2-u2-C7',2,'match','auto','면담 절차와 그때 쓰는 매체의 쓰임을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K6-2-u2-C7","difficulty":2,"kind":"match","stem":"면담 절차와 그때 쓰는 매체의 쓰임을 알맞게 이으세요.","pairs":[{"l":"면담 준비하기","r":"누리집과 책으로 필요한 자료를 찾는다"},{"l":"면담 진행하기","r":"녹음기로 담거나 영상 통화로 만난다"},{"l":"면담 정리하기","r":"담아 둔 것을 다시 들으며 중요한 것을 간추린다"}],"mis":"K6-2-u2-X12","explanation":["만나기 전에는 찾는 데 써요.","만나는 동안에는 담거나 이어 주는 데 써요.","만난 뒤에는 다시 들으며 간추리는 데 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L07_basic#6','kor',6,2,'u2','L07','g6_2_kor_u2_L07_basic','lesson_basic','K6-2-u2-C7',2,'mc','auto','비대면 면담을 할 때 알맞은 태도는 어느 것인가요?',ARRAY['K6-2-u2-X12','K6-2-u2-X10']::text[],false,'{"seq":6,"concept":"K6-2-u2-C7","difficulty":2,"kind":"mc","stem":"비대면 면담을 할 때 알맞은 태도는 어느 것인가요?","options":[{"t":"기기 연결을 미리 확인하고, 말할 때는 렌즈를 보며, 말하지 않을 때는 마이크를 꺼 둔다","correct":true},{"t":"화면 속 내 얼굴만 보며 말한다","mis":"K6-2-u2-X12"},{"t":"마이크를 늘 켜 두고 다른 일을 한다","mis":"K6-2-u2-X10"},{"t":"연결은 면담이 시작된 뒤에 확인한다","mis":"K6-2-u2-X12"}],"explanation":["비대면은 기기를 거쳐 만나요.","연결을 미리 확인하고 렌즈를 보며 말해요.","말하지 않을 때는 마이크를 꺼 두어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L07_basic#7','kor',6,2,'u2','L07','g6_2_kor_u2_L07_basic','lesson_basic','K6-2-u2-C3',2,'mc','auto','시후네 모둠이 정한 면담 목적 가운데 분명한 목적은 어느 것인가요?',ARRAY['K6-2-u2-X07','K6-2-u2-X01']::text[],false,'{"seq":7,"concept":"K6-2-u2-C3","difficulty":2,"kind":"mc","stem":"시후네 모둠이 정한 면담 목적 가운데 분명한 목적은 어느 것인가요?","options":[{"t":"우리 학교 식단이 정해지는 과정과 영양 교사가 하는 일을 알아보자","correct":true},{"t":"급식에 대해 이것저것 알아보자","mis":"K6-2-u2-X07"},{"t":"급식실에 한번 가 보자","mis":"K6-2-u2-X07"},{"t":"맛있는 반찬을 늘려 달라고 부탁하자","mis":"K6-2-u2-X01"}],"explanation":["목적이 흐리면 무엇을 물을지 정해지지 않아요.","「과정」과 「하는 일」처럼 알고 싶은 것을 콕 집어요.","분명한 목적이면 질문이 저절로 만들어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L07_basic#8','kor',6,2,'u2','L07','g6_2_kor_u2_L07_basic','lesson_basic','K6-2-u2-C7',2,'mc','auto','배소윤 선생님이 「학교 과제에만 써 주면 좋겠어요」라고 하셨어요. 모둠이 지켜야 할 것은 어느 것인가요?',ARRAY['K6-2-u2-X11']::text[],false,'{"seq":8,"concept":"K6-2-u2-C7","difficulty":2,"kind":"mc","stem":"배소윤 선생님이 「학교 과제에만 써 주면 좋겠어요」라고 하셨어요. 모둠이 지켜야 할 것은 어느 것인가요?","options":[{"t":"담아 둔 것은 면담 보고서를 쓸 때만 쓰고 모둠 안에서만 나눈다","correct":true},{"t":"재미있는 부분을 잘라 친구에게 보낸다","mis":"K6-2-u2-X11"},{"t":"학교 누리집에 올려 모두 듣게 한다","mis":"K6-2-u2-X11"},{"t":"다른 과제에도 가져다 쓴다","mis":"K6-2-u2-X11"}],"explanation":["선생님은 담는 것을 허락하시며 쓰임을 정해 주셨어요.","담아 둔 것은 그 허락 안에서만 써요.","밖으로 내보내거나 다른 일에 쓰지 않아요."],"asset":{"type":"speech","turns":[{"who":"시후","text":"안녕하세요? 면담을 허락해 주셔서 감사합니다. 식단이 정해지는 과정과 하시는 일을 여쭙고자 합니다. 답변을 정확히 남기려고 녹음을 해도 괜찮으실까요?"},{"who":"배소윤","text":"네, 괜찮습니다. 다만 학교 과제에만 써 주면 좋겠어요."},{"who":"가람","text":"식단을 짜실 때 가장 먼저 생각하시는 것은 무엇인가요?"},{"who":"배소윤","text":"자라는 나이에 필요한 영양을 먼저 놓고, 그다음에 그날 들어오는 재료를 봅니다. 남기는 아이가 많은 반찬도 살펴 둡니다."},{"who":"하온","text":"남기는 반찬도 살피신다고 하셨는데, 그럴 때는 식단을 어떻게 바꾸시나요?"},{"who":"배소윤","text":"같은 재료라도 조리 방법을 바꿉니다. 남기는 까닭이 재료가 아니라 방법일 때가 많거든요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L07_basic#9','kor',6,2,'u2','L07','g6_2_kor_u2_L07_basic','lesson_basic','K6-2-u2-C8',2,'mc','auto','배소윤 선생님 면담을 정리 담당이 간추렸어요. 가장 잘 간추린 것은 어느 것인가요?',ARRAY['K6-2-u2-X13']::text[],false,'{"seq":9,"concept":"K6-2-u2-C8","difficulty":2,"kind":"mc","stem":"배소윤 선생님 면담을 정리 담당이 간추렸어요. 가장 잘 간추린 것은 어느 것인가요?","options":[{"t":"영양을 먼저 놓고 그날 재료를 보아 식단을 짜며, 많이 남는 반찬은 재료보다 조리 방법을 바꾼다","correct":true},{"t":"들은 말을 처음부터 끝까지 한 마디도 빼지 않고 그대로 옮겨 적었다","mis":"K6-2-u2-X13"},{"t":"좋은 말씀을 많이 해 주셨다. 여러 가지를 생각하신다고 한다","mis":"K6-2-u2-X13"},{"t":"식단은 그날 들어오는 재료로만 정한다","mis":"K6-2-u2-X13"}],"explanation":["중요한 것이 남고 뜻이 이어져야 해요.","통째 옮기기나 뭉뚱그리기는 간추린 것이 아니에요.","「재료로만」은 답변의 뜻을 바꾼 것이에요."],"asset":{"type":"speech","turns":[{"who":"시후","text":"안녕하세요? 면담을 허락해 주셔서 감사합니다. 식단이 정해지는 과정과 하시는 일을 여쭙고자 합니다. 답변을 정확히 남기려고 녹음을 해도 괜찮으실까요?"},{"who":"배소윤","text":"네, 괜찮습니다. 다만 학교 과제에만 써 주면 좋겠어요."},{"who":"가람","text":"식단을 짜실 때 가장 먼저 생각하시는 것은 무엇인가요?"},{"who":"배소윤","text":"자라는 나이에 필요한 영양을 먼저 놓고, 그다음에 그날 들어오는 재료를 봅니다. 남기는 아이가 많은 반찬도 살펴 둡니다."},{"who":"하온","text":"남기는 반찬도 살피신다고 하셨는데, 그럴 때는 식단을 어떻게 바꾸시나요?"},{"who":"배소윤","text":"같은 재료라도 조리 방법을 바꿉니다. 남기는 까닭이 재료가 아니라 방법일 때가 많거든요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L07_basic#10','kor',6,2,'u2','L07','g6_2_kor_u2_L07_basic','lesson_basic','K6-2-u2-C7',3,'error','auto','매체를 쓰는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u2-X11']::text[],false,'{"seq":10,"concept":"K6-2-u2-C7","difficulty":3,"kind":"error","stem":"매체를 쓰는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"라희 — 「허락은 녹음을 다 하고 나서 받아도 돼.」","correct":true,"mis_target":"K6-2-u2-X11"},{"t":"준서 — 「담기 전에 먼저 여쭈어보고 허락을 받아.」","mis":"K6-2-u2-X11"},{"t":"예린 — 「보고서를 다 쓴 뒤에는 밖으로 내보내지 않아.」","mis":"K6-2-u2-X11"}],"explanation":["허락은 담기 전에 받아요.","담아 둔 것은 보고서를 쓸 때만 써요.","준서와 예린은 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L07_challenge#1','kor',6,2,'u2','L07','g6_2_kor_u2_L07_challenge','lesson_challenge','K6-2-u2-C8',2,'sa','auto','면담 내용을 간추리는 방법 가운데, 많은 내용에서 중요한 것을 고르는 방법을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K6-2-u2-C8","difficulty":2,"kind":"sa","stem":"면담 내용을 간추리는 방법 가운데, 많은 내용에서 중요한 것을 고르는 방법을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["선택"],"explanation":["간추리기에는 삭제·대체·선택·구성이 있어요.","중요한 것을 고르는 것이 선택이에요.","덜어 내는 것은 삭제예요."],"mis":"K6-2-u2-X13"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L07_challenge#2','kor',6,2,'u2','L07','g6_2_kor_u2_L07_challenge','lesson_challenge','K6-2-u2-C7',2,'mc','auto','대면 면담과 비대면 면담 가운데 무엇으로 할지 정하는 기준으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u2-X12','K6-2-u2-X19']::text[],false,'{"seq":2,"concept":"K6-2-u2-C7","difficulty":2,"kind":"mc","stem":"대면 면담과 비대면 면담 가운데 무엇으로 할지 정하는 기준으로 알맞은 것은 어느 것인가요?","options":[{"t":"면담 대상자의 사정에 맞추어 정한다","correct":true},{"t":"대면이 언제나 더 좋으니 대면으로만 한다","mis":"K6-2-u2-X12"},{"t":"비대면이 편하니 언제나 비대면으로 한다","mis":"K6-2-u2-X12"},{"t":"모둠에서 목소리가 가장 큰 사람이 정한다","mis":"K6-2-u2-X19"}],"explanation":["둘 가운데 무엇이 더 좋다고 정해져 있지 않아요.","직접 뵐 수 있으면 대면, 어려우면 비대면이에요.","그분의 사정이 기준이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L07_challenge#3','kor',6,2,'u2','L07','g6_2_kor_u2_L07_challenge','lesson_challenge','K6-2-u2-C8',3,'match','auto','면담 내용을 간추리는 방법과 그 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":3,"concept":"K6-2-u2-C8","difficulty":3,"kind":"match","stem":"면담 내용을 간추리는 방법과 그 뜻을 알맞게 이으세요.","pairs":[{"l":"삭제","r":"중요하지 않은 것을 덜어 낸다"},{"l":"대체","r":"잘게 나뉜 내용을 하나로 묶는 말로 바꾼다"},{"l":"선택","r":"많은 내용 가운데 중요한 것을 고른다"},{"l":"구성","r":"흐릿한 것을 알아볼 수 있는 문장으로 새로 쓴다"}],"mis":"K6-2-u2-X13","explanation":["정리는 들은 말을 다 옮기는 것이 아니에요.","내가 이해한 것을 내 말로 다시 세워요.","네 방법을 함께 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L07_challenge#4','kor',6,2,'u2','L07','g6_2_kor_u2_L07_challenge','lesson_challenge','K6-2-u2-C5',3,'mc','auto','하온의 「남기는 반찬도 살피신다고 하셨는데, 그럴 때는 식단을 어떻게 바꾸시나요?」에서 알 수 있는 하온의 면담 태도는 어느 것인가요?',ARRAY['K6-2-u2-X06','K6-2-u2-X07','K6-2-u2-X10']::text[],false,'{"seq":4,"concept":"K6-2-u2-C5","difficulty":3,"kind":"mc","stem":"하온의 「남기는 반찬도 살피신다고 하셨는데, 그럴 때는 식단을 어떻게 바꾸시나요?」에서 알 수 있는 하온의 면담 태도는 어느 것인가요?","options":[{"t":"답을 끝까지 듣고 그 안의 말을 붙들어 이어서 물었다","correct":true},{"t":"질문지에 적힌 차례대로 읽기만 했다","mis":"K6-2-u2-X06"},{"t":"면담 목적에서 벗어난 것을 물었다","mis":"K6-2-u2-X07"},{"t":"말씀 도중에 끼어들어 물었다","mis":"K6-2-u2-X10"}],"explanation":["「남기는 반찬」은 바로 앞 답에 나온 말이에요.","하온은 끝까지 듣고 그 말을 붙들었어요.","그래서 「조리 방법」이라는 중요한 답이 나왔어요."],"asset":{"type":"speech","turns":[{"who":"시후","text":"안녕하세요? 면담을 허락해 주셔서 감사합니다. 식단이 정해지는 과정과 하시는 일을 여쭙고자 합니다. 답변을 정확히 남기려고 녹음을 해도 괜찮으실까요?"},{"who":"배소윤","text":"네, 괜찮습니다. 다만 학교 과제에만 써 주면 좋겠어요."},{"who":"가람","text":"식단을 짜실 때 가장 먼저 생각하시는 것은 무엇인가요?"},{"who":"배소윤","text":"자라는 나이에 필요한 영양을 먼저 놓고, 그다음에 그날 들어오는 재료를 봅니다. 남기는 아이가 많은 반찬도 살펴 둡니다."},{"who":"하온","text":"남기는 반찬도 살피신다고 하셨는데, 그럴 때는 식단을 어떻게 바꾸시나요?"},{"who":"배소윤","text":"같은 재료라도 조리 방법을 바꿉니다. 남기는 까닭이 재료가 아니라 방법일 때가 많거든요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L07_challenge#5','kor',6,2,'u2','L07','g6_2_kor_u2_L07_challenge','lesson_challenge','K6-2-u2-C7',3,'mc','auto','면담을 진행할 때 매체 담당이 할 일을 차례대로 바르게 늘어놓은 것은 어느 것인가요?',ARRAY['K6-2-u2-X11']::text[],false,'{"seq":5,"concept":"K6-2-u2-C7","difficulty":3,"kind":"mc","stem":"면담을 진행할 때 매체 담당이 할 일을 차례대로 바르게 늘어놓은 것은 어느 것인가요?","options":[{"t":"기기를 준비한다 → 담아도 될지 여쭈어 허락을 받는다 → 담아 둔 것을 모둠과 나눈다","correct":true},{"t":"담는다 → 모둠과 나눈다 → 허락을 받는다","mis":"K6-2-u2-X11"},{"t":"허락을 받는다 → 누리집에 올린다 → 기기를 준비한다","mis":"K6-2-u2-X11"},{"t":"기기를 준비한다 → 담는다 → 친구들에게 퍼뜨린다","mis":"K6-2-u2-X11"}],"explanation":["기기는 미리 준비해요.","담기 전에 허락을 받아요.","담아 둔 것은 모둠 안에서만 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L07_challenge#6','kor',6,2,'u2','L07','g6_2_kor_u2_L07_challenge','lesson_challenge','K6-2-u2-C8',3,'error','auto','모둠 역할을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u2-X19']::text[],false,'{"seq":6,"concept":"K6-2-u2-C8","difficulty":3,"kind":"error","stem":"모둠 역할을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도하 — 「정리 담당은 면담 날짜와 장소를 정해 모둠에 알려.」","correct":true,"mis_target":"K6-2-u2-X19"},{"t":"소이 — 「진행 담당은 전 과정을 살피고 시간을 조절해.」","mis":"K6-2-u2-X19"},{"t":"이안 — 「질문 담당은 질문을 모아 다듬고 함께 물어.」","mis":"K6-2-u2-X19"}],"explanation":["날짜·시간·장소를 정하는 것은 약속 담당이에요.","정리 담당은 핵심을 메모하고 보고서 자료를 정리해요.","소이와 이안은 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L07_challenge#7','kor',6,2,'u2','L07','g6_2_kor_u2_L07_challenge','lesson_challenge','K6-2-u2-C8',3,'ox','auto','면담이 두려운 친구는 면담 모둠에서 빠지는 것이 좋아요.',ARRAY['K6-2-u2-X19']::text[],false,'{"seq":7,"concept":"K6-2-u2-C8","difficulty":3,"kind":"ox","stem":"면담이 두려운 친구는 면담 모둠에서 빠지는 것이 좋아요.","answer":"X","reason_options":[{"t":"지켜보기, 질문지 보며 읽기, 메모나 정리 맡기처럼 할 수 있는 만큼부터 함께하면 되기 때문에","correct":true},{"t":"모르는 어른께 말을 걸기 어려워하는 것은 잘못이기 때문에","mis":"K6-2-u2-X19"}],"mis":"K6-2-u2-X19","explanation":["말 걸기를 어려워하는 것은 잘못이 아니에요.","할 수 있는 만큼부터 시작하면 돼요.","다음번에는 질문 하나만 직접 해 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L07_challenge#8','kor',6,2,'u2','L07','g6_2_kor_u2_L07_challenge','lesson_challenge','K6-2-u2-C7',4,'mc','auto','담아 둔 자료를 「내 것이 아니라 빌려 온 것」이라고 하는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u2-X11']::text[],false,'{"seq":8,"concept":"K6-2-u2-C7","difficulty":4,"kind":"mc","stem":"담아 둔 자료를 「내 것이 아니라 빌려 온 것」이라고 하는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"그분의 목소리와 말씀이 들어 있어 그분이 허락한 범위 안에서만 쓸 수 있기 때문에","correct":true},{"t":"녹음기를 다른 사람에게 빌렸기 때문에","mis":"K6-2-u2-X11"},{"t":"담아 둔 것은 곧 저절로 지워지기 때문에","mis":"K6-2-u2-X11"},{"t":"누리집에 올리면 모두의 것이 되기 때문에","mis":"K6-2-u2-X11"}],"explanation":["담아 둔 자료에는 그분의 목소리와 말씀이 있어요.","그래서 허락한 쓰임 안에서만 써요.","보고서를 쓸 때만 쓰고 밖으로 내보내지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L07_challenge#9','kor',6,2,'u2','L07','g6_2_kor_u2_L07_challenge','lesson_challenge','K6-2-u2-C7',4,'essay','teacher','우리 동네 도서관 사서 선생님과 면담한다고 할 때, 준비·진행·정리 절차마다 매체를 어떻게 쓸지 한 가지씩 쓰고, 녹음할 때 지켜야 할 것을 두 가지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u2-C7","difficulty":4,"kind":"essay","stem":"우리 동네 도서관 사서 선생님과 면담한다고 할 때, 준비·진행·정리 절차마다 매체를 어떻게 쓸지 한 가지씩 쓰고, 녹음할 때 지켜야 할 것을 두 가지 쓰세요.","answer_guide":{"answer":"예: 준비 — 도서관 누리집과 책에서 사서가 하는 일을 찾아 질문을 만든다. 진행 — 허락을 받아 녹음기로 담고, 직접 뵙기 어려우면 영상 통화로 면담한다. 정리 — 담아 둔 것을 다시 들으며 중요한 내용을 간추린다. 녹음할 때는 담기 전에 먼저 여쭈어 허락을 받고, 담아 둔 것은 보고서를 쓸 때만 쓰며 누리집이나 친구에게 내보내지 않는다.","scoring_points":["절차마다 알맞은 매체 쓰임을 한 가지씩 썼는가","담기 전에 허락을 받는다는 것을 썼는가","보고서에만 쓰고 밖으로 내보내지 않는다는 것을 썼는가"]},"explanation":["절차마다 매체 쓰임이 달라요.","허락이 먼저예요.","담아 둔 것은 빌려 온 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L07_challenge#10','kor',6,2,'u2','L07','g6_2_kor_u2_L07_challenge','lesson_challenge','K6-2-u2-C8',4,'essay','teacher','배소윤 선생님 면담 장면을 읽고, 정리 담당이 되어 들은 내용을 두 문장으로 간추리세요. 간추릴 때 쓴 방법을 삭제·대체·선택·구성 가운데 두 가지 들어 밝히세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u2-C8","difficulty":4,"kind":"essay","stem":"배소윤 선생님 면담 장면을 읽고, 정리 담당이 되어 들은 내용을 두 문장으로 간추리세요. 간추릴 때 쓴 방법을 삭제·대체·선택·구성 가운데 두 가지 들어 밝히세요.","answer_guide":{"answer":"예: 영양 교사는 자라는 나이에 필요한 영양을 먼저 놓고 그날 들어오는 재료를 보아 식단을 짠다. 많이 남는 반찬은 재료를 바꾸기보다 조리 방법을 바꾸는데, 남기는 까닭이 방법일 때가 많기 때문이다. 녹음 허락처럼 면담 내용과 상관없는 부분은 삭제하고, 여러 답 가운데 식단 짜는 차례와 남는 반찬 다루는 법을 선택했다.","scoring_points":["두 문장으로 중요한 내용을 간추렸는가","답변의 뜻을 바꾸지 않았는가","간추리기 방법 두 가지를 바르게 밝혔는가"]},"explanation":["중요한 것을 고르고 덜어 내요.","내 말로 다시 세워요.","뜻은 바꾸지 않아요."],"asset":{"type":"speech","turns":[{"who":"시후","text":"안녕하세요? 면담을 허락해 주셔서 감사합니다. 식단이 정해지는 과정과 하시는 일을 여쭙고자 합니다. 답변을 정확히 남기려고 녹음을 해도 괜찮으실까요?"},{"who":"배소윤","text":"네, 괜찮습니다. 다만 학교 과제에만 써 주면 좋겠어요."},{"who":"가람","text":"식단을 짜실 때 가장 먼저 생각하시는 것은 무엇인가요?"},{"who":"배소윤","text":"자라는 나이에 필요한 영양을 먼저 놓고, 그다음에 그날 들어오는 재료를 봅니다. 남기는 아이가 많은 반찬도 살펴 둡니다."},{"who":"하온","text":"남기는 반찬도 살피신다고 하셨는데, 그럴 때는 식단을 어떻게 바꾸시나요?"},{"who":"배소윤","text":"같은 재료라도 조리 방법을 바꿉니다. 남기는 까닭이 재료가 아니라 방법일 때가 많거든요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L09_basic#1','kor',6,2,'u2','L09','g6_2_kor_u2_L09_basic','lesson_basic','K6-2-u2-C9',1,'mc','auto','면담 과정을 되돌아볼 때 나누어 적는 세 가지로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u2-X14','K6-2-u2-X15']::text[],false,'{"seq":1,"concept":"K6-2-u2-C9","difficulty":1,"kind":"mc","stem":"면담 과정을 되돌아볼 때 나누어 적는 세 가지로 알맞은 것은 어느 것인가요?","options":[{"t":"잘한 점 · 보완할 점 · 더 알고 싶은 점","correct":true},{"t":"잘한 사람 · 못한 사람 · 늦은 사람","mis":"K6-2-u2-X14"},{"t":"재미있던 점 · 지루했던 점 · 배고팠던 점","mis":"K6-2-u2-X14"},{"t":"면담 날짜 · 시간 · 장소","mis":"K6-2-u2-X15"}],"explanation":["성찰은 세 가지로 나누어 적어요.","잘한 점, 보완할 점, 더 알고 싶은 점이에요.","사람을 가리거나 기분만 적지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L09_basic#2','kor',6,2,'u2','L09','g6_2_kor_u2_L09_basic','lesson_basic','K6-2-u2-C9',1,'mc','auto','면담 보고서 앞부분에 담는 내용으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u2-X15','K6-2-u2-X11']::text[],false,'{"seq":2,"concept":"K6-2-u2-C9","difficulty":1,"kind":"mc","stem":"면담 보고서 앞부분에 담는 내용으로 알맞은 것은 어느 것인가요?","options":[{"t":"면담 목적과 대상자를 밝히고 준비 과정을 돌아본다","correct":true},{"t":"면담으로 새롭게 안 사실을 답변 중심으로 소개한다","mis":"K6-2-u2-X15"},{"t":"면담을 마친 뒤 깨달은 점을 밝힌다","mis":"K6-2-u2-X15"},{"t":"담아 둔 목소리 파일을 붙인다","mis":"K6-2-u2-X11"}],"explanation":["앞부분은 면담 전 이야기예요.","왜·누구를·어떻게 준비했는지 써요.","새로 안 사실은 가운데, 깨달은 점은 뒷부분이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L09_basic#3','kor',6,2,'u2','L09','g6_2_kor_u2_L09_basic','lesson_basic','K6-2-u2-C9',1,'ox','auto','면담 과정을 되돌아보는 일은 누가 잘못했는지 가리는 일이에요.',ARRAY['K6-2-u2-X14']::text[],false,'{"seq":3,"concept":"K6-2-u2-C9","difficulty":1,"kind":"ox","stem":"면담 과정을 되돌아보는 일은 누가 잘못했는지 가리는 일이에요.","answer":"X","reason_options":[{"t":"보완할 점을 다음 면담에서 실천할 약속으로 바꾸는 일이기 때문에","correct":true},{"t":"잘못한 사람을 알아야 다음에 그 사람을 빼고 할 수 있기 때문에","mis":"K6-2-u2-X14"}],"mis":"K6-2-u2-X14","explanation":["사람을 가리키면 다음에 할 일이 남지 않아요.","「놓친 말이 있었다 → 둘이 나누어 메모하자」처럼 바꿔요.","끝은 「다음에 우리가 무엇을 할까」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L09_basic#4','kor',6,2,'u2','L09','g6_2_kor_u2_L09_basic','lesson_basic','K6-2-u2-C9',1,'sa','auto','면담 보고서에서 면담으로 새롭게 알게 된 것을 소개하는 부분은 앞부분·가운데 부분·뒷부분 가운데 어디인가요?','{}'::text[],false,'{"seq":4,"concept":"K6-2-u2-C9","difficulty":1,"kind":"sa","stem":"면담 보고서에서 면담으로 새롭게 알게 된 것을 소개하는 부분은 앞부분·가운데 부분·뒷부분 가운데 어디인가요?","answer":["가운데 부분","가운데","가운데부분"],"explanation":["앞부분은 목적과 준비예요.","가운데 부분은 새롭게 안 사실이에요.","뒷부분은 깨달은 점과 달라진 생각이에요."],"mis":"K6-2-u2-X15"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L09_basic#5','kor',6,2,'u2','L09','g6_2_kor_u2_L09_basic','lesson_basic','K6-2-u2-C9',2,'match','auto','면담 보고서의 부분과 담는 내용을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K6-2-u2-C9","difficulty":2,"kind":"match","stem":"면담 보고서의 부분과 담는 내용을 알맞게 이으세요.","pairs":[{"l":"앞부분","r":"왜 면담했는지, 누구를 만났는지, 어떻게 준비했는지"},{"l":"가운데 부분","r":"첫째·둘째·셋째로 나눈 새롭게 안 사실"},{"l":"뒷부분","r":"깨달은 점과 달라진 생각, 다음 약속"}],"mis":"K6-2-u2-X15","explanation":["세 부분이 하는 일이 달라요.","면담 전 이야기 → 들은 내용 → 면담 뒤 마음이에요.","차례대로 읽으면 면담이 한눈에 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L09_basic#6','kor',6,2,'u2','L09','g6_2_kor_u2_L09_basic','lesson_basic','K6-2-u2-C9',2,'mc','auto','「따뜻한 밥상을 짓는 사람」 뒷부분의 「다음에는 급식을 남기기 전에 왜 남기는지 한 번 생각해 보려 합니다」가 하는 일은 어느 것인가요?',ARRAY['K6-2-u2-X15','K6-2-u2-X04']::text[],false,'{"seq":6,"concept":"K6-2-u2-C9","difficulty":2,"kind":"mc","stem":"「따뜻한 밥상을 짓는 사람」 뒷부분의 「다음에는 급식을 남기기 전에 왜 남기는지 한 번 생각해 보려 합니다」가 하는 일은 어느 것인가요?","options":[{"t":"면담으로 달라진 내 생각과 실천을 밝힌다","correct":true},{"t":"모둠원이 맡은 역할을 알린다","mis":"K6-2-u2-X15"},{"t":"면담한 날짜와 시각을 기록한다","mis":"K6-2-u2-X15"},{"t":"면담 대상자의 개인 정보를 알린다","mis":"K6-2-u2-X04"}],"explanation":["뒷부분은 면담 뒤의 마음을 써요.","무엇 때문에 무엇이 달라졌는지 밝혀요.","조리 방법 말씀 → 남기기 전에 생각하기예요."],"asset":{"type":"passage","lines":["급식이 그날 아침에 정해지는 것이 아니라","오래 앞서 준비되는 일이라는 것을 알았습니다.","남기는 반찬의 조리 방법을 다시 살피신다는 말씀이 가장 기억에 남습니다.","다음에는 급식을 남기기 전에 왜 남기는지 한 번 생각해 보려 합니다.","우리 모둠은 다음 면담에서 감사 인사를 끝까지 드리고 나오기로 약속했습니다."],"title":"「따뜻한 밥상을 짓는 사람」 뒷부분 — 새벽 모둠"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L09_basic#7','kor',6,2,'u2','L09','g6_2_kor_u2_L09_basic','lesson_basic','K6-2-u2-C9',2,'mc','auto','면담 과정을 되돌아볼 때 기준이 되는 것은 어느 것인가요?',ARRAY['K6-2-u2-X14']::text[],false,'{"seq":7,"concept":"K6-2-u2-C9","difficulty":2,"kind":"mc","stem":"면담 과정을 되돌아볼 때 기준이 되는 것은 어느 것인가요?","options":[{"t":"예의를 지키며 답변을 끝까지 들었는가","correct":true},{"t":"누가 말을 더 많이 했는가","mis":"K6-2-u2-X14"},{"t":"목소리가 누가 더 컸는가","mis":"K6-2-u2-X14"},{"t":"옷차림이 단정했는가","mis":"K6-2-u2-X14"}],"explanation":["되돌아볼 때는 절차마다 무엇을 했는지 짚어요.","역할 실천 · 예의와 듣기 · 매체와 정리가 기준이에요.","겉모습은 기준이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L09_basic#8','kor',6,2,'u2','L09','g6_2_kor_u2_L09_basic','lesson_basic','K6-2-u2-C8',2,'mc','auto','보고서는 들은 말을 옮겨 적는 글이 아니에요. 그렇다고 해서 하면 안 되는 것은 어느 것인가요?',ARRAY['K6-2-u2-X13','K6-2-u2-X15']::text[],false,'{"seq":8,"concept":"K6-2-u2-C8","difficulty":2,"kind":"mc","stem":"보고서는 들은 말을 옮겨 적는 글이 아니에요. 그렇다고 해서 하면 안 되는 것은 어느 것인가요?","options":[{"t":"답변의 뜻을 바꾸어 적는 것","correct":true},{"t":"덜 중요한 것을 덜어 내는 것","mis":"K6-2-u2-X13"},{"t":"중요한 것을 골라 내 말로 다시 세우는 것","mis":"K6-2-u2-X13"},{"t":"새로 안 사실을 첫째·둘째·셋째로 나누는 것","mis":"K6-2-u2-X15"}],"explanation":["줄이는 것과 바꾸는 것은 달라요.","덜어 내고 골라 내 말로 써도 돼요.","하지만 그분 말씀의 뜻을 바꾸면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L09_basic#9','kor',6,2,'u2','L09','g6_2_kor_u2_L09_basic','lesson_basic','K6-2-u2-C9',2,'mc','auto','면담 보고서에 넣어도 되는 것은 어느 것인가요?',ARRAY['K6-2-u2-X04','K6-2-u2-X11']::text[],false,'{"seq":9,"concept":"K6-2-u2-C9","difficulty":2,"kind":"mc","stem":"면담 보고서에 넣어도 되는 것은 어느 것인가요?","options":[{"t":"면담을 마친 뒤 느낀 점","correct":true},{"t":"면담 대상자의 집 주소","mis":"K6-2-u2-X04"},{"t":"동의 없이 담아 둔 목소리 파일","mis":"K6-2-u2-X11"},{"t":"면담 대상자의 전화번호","mis":"K6-2-u2-X04"}],"explanation":["보고서에는 목적과 이어지고 알려도 되는 것만 넣어요.","목적·준비·새로 안 사실·느낀 점이 들어가요.","개인 정보와 동의 없는 자료는 넣지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L09_basic#10','kor',6,2,'u2','L09','g6_2_kor_u2_L09_basic','lesson_basic','K6-2-u2-C9',3,'error','auto','모둠이 면담 과정을 되돌아보며 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u2-X14']::text[],false,'{"seq":10,"concept":"K6-2-u2-C9","difficulty":3,"kind":"error","stem":"모둠이 면담 과정을 되돌아보며 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"은재 — 「단우가 메모를 못 해서 면담을 망쳤어.」","correct":true,"mis_target":"K6-2-u2-X14"},{"t":"시온 — 「메모가 늦어 놓친 말이 있었으니 다음에는 둘이 나누어 메모하자.」","mis":"K6-2-u2-X14"},{"t":"다율 — 「담기 전에 허락을 받은 건 잘한 점이야.」","mis":"K6-2-u2-X14"}],"explanation":["성찰은 잘잘못을 가리는 일이 아니에요.","시온은 보완할 점을 다음 약속으로 바꾸었어요.","은재는 사람을 탓했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L09_challenge#1','kor',6,2,'u2','L09','g6_2_kor_u2_L09_challenge','lesson_challenge','K6-2-u2-C9',2,'sa','auto','모둠 성찰에서는 세 가지에 하나를 더해 「다음 면담에서 ○○할 점」을 정해요. ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K6-2-u2-C9","difficulty":2,"kind":"sa","stem":"모둠 성찰에서는 세 가지에 하나를 더해 「다음 면담에서 ○○할 점」을 정해요. ○○에 알맞은 두 글자를 쓰세요.","answer":["실천"],"explanation":["잘한 점·보완할 점·더 알고 싶은 점에 하나를 더해요.","다음 면담에서 실천할 점이에요.","우리 모둠의 약속이 돼요."],"mis":"K6-2-u2-X14"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L09_challenge#2','kor',6,2,'u2','L09','g6_2_kor_u2_L09_challenge','lesson_challenge','K6-2-u2-C9',2,'mc','auto','면담 보고서를 나누는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u2-X11','K6-2-u2-X15']::text[],false,'{"seq":2,"concept":"K6-2-u2-C9","difficulty":2,"kind":"mc","stem":"면담 보고서를 나누는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"간추린 보고서를 알림판에 붙이고 면담 대상자께도 보여 드린다","correct":true},{"t":"담아 둔 목소리를 반 누리집에 함께 올린다","mis":"K6-2-u2-X11"},{"t":"우리 모둠만 보고 아무에게도 보여 주지 않는다","mis":"K6-2-u2-X15"},{"t":"다른 모둠 보고서는 읽지 않는다","mis":"K6-2-u2-X15"}],"explanation":["알게 된 것을 나누면 면담하지 않은 친구도 알게 돼요.","면담 대상자께 완성된 보고서를 보여 드려요.","담아 둔 목소리와 영상은 올리지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L09_challenge#3','kor',6,2,'u2','L09','g6_2_kor_u2_L09_challenge','lesson_challenge','K6-2-u2-C9',3,'mc','auto','「따뜻한 밥상을 짓는 사람」 가운데 부분에서 새롭게 안 사실을 「첫째·둘째·셋째」로 나누어 쓴 까닭은 어느 것인가요?',ARRAY['K6-2-u2-X13','K6-2-u2-X08','K6-2-u2-X15']::text[],false,'{"seq":3,"concept":"K6-2-u2-C9","difficulty":3,"kind":"mc","stem":"「따뜻한 밥상을 짓는 사람」 가운데 부분에서 새롭게 안 사실을 「첫째·둘째·셋째」로 나누어 쓴 까닭은 어느 것인가요?","options":[{"t":"들은 것이 많아도 한눈에 들어오게 하려고","correct":true},{"t":"글을 길어 보이게 하려고","mis":"K6-2-u2-X13"},{"t":"면담에서 질문을 세 개만 했기 때문에","mis":"K6-2-u2-X08"},{"t":"보고서는 언제나 세 문단이어야 하기 때문에","mis":"K6-2-u2-X15"}],"explanation":["들은 것을 그대로 늘어놓으면 읽기 어려워요.","갈래로 나누어 적으면 한눈에 들어와요.","하는 일 · 어려운 점 · 보람처럼 나눌 수 있어요."],"asset":{"type":"passage","lines":["면담으로 새롭게 알게 된 것은 세 가지입니다.","첫째, 필요한 영양을 먼저 놓고 그다음에 그날 재료를 본다고 하셨습니다.","둘째, 많이 남는 반찬은 재료보다 조리 방법을 바꾼다고 하셨습니다.","남기는 까닭이 방법일 때가 많기 때문이라고 하셨습니다.","셋째, 모두의 입맛이 달라 한 끼로 모두를 맞출 수는 없고,","한 주 전체를 놓고 고르게 맞춘다고 하셨습니다."],"title":"「따뜻한 밥상을 짓는 사람」 가운데 부분 — 새벽 모둠"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L09_challenge#4','kor',6,2,'u2','L09','g6_2_kor_u2_L09_challenge','lesson_challenge','K6-2-u2-C9',3,'mc','auto','「따뜻한 밥상을 짓는 사람」 가운데 부분의 셋째 사실로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u2-X13']::text[],false,'{"seq":4,"concept":"K6-2-u2-C9","difficulty":3,"kind":"mc","stem":"「따뜻한 밥상을 짓는 사람」 가운데 부분의 셋째 사실로 알맞은 것은 어느 것인가요?","options":[{"t":"모두의 입맛이 달라 한 주 전체를 놓고 고르게 맞춘다","correct":true},{"t":"많이 남는 반찬은 재료를 바꾼다","mis":"K6-2-u2-X13"},{"t":"식단은 그날 아침에 정한다","mis":"K6-2-u2-X13"},{"t":"한 끼로 모두의 입맛을 맞춘다","mis":"K6-2-u2-X13"}],"explanation":["셋째는 이 일에서 가장 어려운 점이에요.","한 끼로는 모두를 맞출 수 없어요.","그래서 한 주 전체를 놓고 맞춰요."],"asset":{"type":"passage","lines":["면담으로 새롭게 알게 된 것은 세 가지입니다.","첫째, 필요한 영양을 먼저 놓고 그다음에 그날 재료를 본다고 하셨습니다.","둘째, 많이 남는 반찬은 재료보다 조리 방법을 바꾼다고 하셨습니다.","남기는 까닭이 방법일 때가 많기 때문이라고 하셨습니다.","셋째, 모두의 입맛이 달라 한 끼로 모두를 맞출 수는 없고,","한 주 전체를 놓고 고르게 맞춘다고 하셨습니다."],"title":"「따뜻한 밥상을 짓는 사람」 가운데 부분 — 새벽 모둠"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L09_challenge#5','kor',6,2,'u2','L09','g6_2_kor_u2_L09_challenge','lesson_challenge','K6-2-u2-C8',3,'error','auto','면담 보고서를 쓰는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u2-X13','K6-2-u2-X15']::text[],false,'{"seq":5,"concept":"K6-2-u2-C8","difficulty":3,"kind":"error","stem":"면담 보고서를 쓰는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하람 — 「담아 둔 걸 처음부터 끝까지 그대로 옮겨 쓰면 가장 좋은 보고서야.」","correct":true,"mis_target":"K6-2-u2-X13"},{"t":"예솔 — 「중요한 것을 골라 내 말로 다시 세우되 뜻은 바꾸지 않아.」","mis":"K6-2-u2-X13"},{"t":"주원 — 「새롭게 안 사실은 갈래로 나누어 써.」","mis":"K6-2-u2-X15"}],"explanation":["통째로 옮기면 길기만 하고 무엇이 중요한지 몰라요.","골라서 덜어 내 말로 다시 세워요.","예솔과 주원은 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L09_challenge#6','kor',6,2,'u2','L09','g6_2_kor_u2_L09_challenge','lesson_challenge','K6-2-u2-C9',3,'ox','auto','「아주 재미있었다. 다음에도 또 하고 싶다.」만 쓰면 보고서 뒷부분으로 충분해요.',ARRAY['K6-2-u2-X15']::text[],false,'{"seq":6,"concept":"K6-2-u2-C9","difficulty":3,"kind":"ox","stem":"「아주 재미있었다. 다음에도 또 하고 싶다.」만 쓰면 보고서 뒷부분으로 충분해요.","answer":"X","reason_options":[{"t":"무엇 때문에 무엇이 달라졌는지 적어야 읽는 사람에게 남는 것이 있기 때문에","correct":true},{"t":"뒷부분은 느낌만 짧게 적는 곳이기 때문에","mis":"K6-2-u2-X15"}],"mis":"K6-2-u2-X15","explanation":["느낌만 적은 글은 남는 것이 적어요.","어떤 말씀 때문에 생각이 어떻게 달라졌는지 써요.","다음에 실천할 것도 밝혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L09_challenge#7','kor',6,2,'u2','L09','g6_2_kor_u2_L09_challenge','lesson_challenge','K6-2-u2-C9',3,'match','auto','새벽 모둠 친구들의 성찰 말과 성찰 항목을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K6-2-u2-C9","difficulty":3,"kind":"match","stem":"새벽 모둠 친구들의 성찰 말과 성찰 항목을 알맞게 이으세요.","pairs":[{"l":"책과 누리집을 함께 찾아 질문을 만들었다","r":"잘한 점"},{"l":"감사 인사를 제대로 못 드리고 나왔다","r":"보완할 점"},{"l":"한 주 식단은 언제 짜시는지 궁금해졌다","r":"더 알고 싶은 점"}],"mis":"K6-2-u2-X14","explanation":["절차대로 해낸 것은 잘한 점이에요.","놓친 것은 보완할 점이에요.","답을 듣고 새로 생긴 궁금함은 더 알고 싶은 점이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L09_challenge#8','kor',6,2,'u2','L09','g6_2_kor_u2_L09_challenge','lesson_challenge','K6-2-u2-C9',4,'mc','auto','성찰의 「보완할 점」을 「다음 면담에서 실천할 점」으로 바르게 바꾼 것은 어느 것인가요?',ARRAY['K6-2-u2-X14']::text[],false,'{"seq":8,"concept":"K6-2-u2-C9","difficulty":4,"kind":"mc","stem":"성찰의 「보완할 점」을 「다음 면담에서 실천할 점」으로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"보완할 점: 질문지만 보고 읽었다 → 실천할 점: 답을 끝까지 듣고 궁금하면 이어서 묻자","correct":true},{"t":"보완할 점: 질문지만 보고 읽었다 → 실천할 점: 질문지를 읽은 사람은 다음에 빠지자","mis":"K6-2-u2-X14"},{"t":"보완할 점: 시간이 모자랐다 → 실천할 점: 다음에는 열심히 하자","mis":"K6-2-u2-X14"},{"t":"보완할 점: 감사 인사를 못 했다 → 실천할 점: 아쉬웠다","mis":"K6-2-u2-X14"}],"explanation":["실천할 점은 다음에 할 행동으로 써요.","사람을 빼거나 「열심히」처럼 막연하면 남지 않아요.","기분은 실천할 점이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L09_challenge#9','kor',6,2,'u2','L09','g6_2_kor_u2_L09_challenge','lesson_challenge','K6-2-u2-C9',4,'essay','teacher','내가 면담하고 싶은 분을 떠올려 면담 보고서 앞부분을 한 문단 쓰세요. 왜 면담하려는지, 누구를 만나려는지, 어떻게 준비할 것인지가 드러나게 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u2-C9","difficulty":4,"kind":"essay","stem":"내가 면담하고 싶은 분을 떠올려 면담 보고서 앞부분을 한 문단 쓰세요. 왜 면담하려는지, 누구를 만나려는지, 어떻게 준비할 것인지가 드러나게 쓰세요.","answer_guide":{"answer":"예: 우리 모둠은 동네 도서관이 어떤 책을 들여오는지 알고 싶어, 도서관에서 일하시는 사서 선생님과 면담하기로 했습니다. 도서관에 자주 가는 제가 약속 담당을 맡아 먼저 찾아뵙고 허락을 구하려 합니다. 면담 전에 도서관 누리집과 책에서 사서가 하는 일을 찾아 두고, 그것을 바탕으로 질문을 세 갈래로 만들 것입니다.","scoring_points":["면담 목적을 밝혔는가","면담 대상자를 밝혔는가","준비 과정(허락·자료·질문·역할)을 썼는가"]},"explanation":["앞부분은 면담 전 이야기예요.","왜 · 누구 · 어떻게 준비가 드러나야 해요.","새로 안 사실은 가운데에 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L09_challenge#10','kor',6,2,'u2','L09','g6_2_kor_u2_L09_challenge','lesson_challenge','K6-2-u2-C9',4,'essay','teacher','면담 보고서의 앞부분·가운데 부분·뒷부분이 각각 무엇을 담는지 쓰고, 보고서를 친구들과 나눌 때 나누어도 되는 것과 나누면 안 되는 것을 한 가지씩 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u2-C9","difficulty":4,"kind":"essay","stem":"면담 보고서의 앞부분·가운데 부분·뒷부분이 각각 무엇을 담는지 쓰고, 보고서를 친구들과 나눌 때 나누어도 되는 것과 나누면 안 되는 것을 한 가지씩 쓰세요.","answer_guide":{"answer":"예: 앞부분은 면담 목적과 대상자, 준비 과정을 담고, 가운데 부분은 면담으로 새롭게 안 사실을 갈래로 나누어 답변 중심으로 담고, 뒷부분은 면담을 마친 뒤 깨달은 점과 달라진 생각을 담는다. 내가 간추려 쓴 보고서는 나누어도 되지만, 동의 없이 담아 둔 목소리나 면담 대상자의 개인 정보는 나누면 안 된다.","scoring_points":["세 부분이 담는 내용을 바르게 썼는가","나누어도 되는 것을 바르게 들었는가","나누면 안 되는 것을 바르게 들었는가"]},"explanation":["앞 · 가운데 · 뒤가 하는 일이 달라요.","간추려 쓴 보고서는 함께 읽어요.","목소리 파일과 개인 정보는 나누지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L11_basic#1','kor',6,2,'u2','L11','g6_2_kor_u2_L11_basic','lesson_basic','K6-2-u2-C10',1,'mc','auto','작품 속 인물이 되어 답할 때 근거로 삼아야 할 것은 어느 것인가요?',ARRAY['K6-2-u2-X16']::text[],false,'{"seq":1,"concept":"K6-2-u2-C10","difficulty":1,"kind":"mc","stem":"작품 속 인물이 되어 답할 때 근거로 삼아야 할 것은 어느 것인가요?","options":[{"t":"작품 속 사건과 인물의 말과 행동","correct":true},{"t":"작품에 없어도 재미있을 것 같은 상상","mis":"K6-2-u2-X16"},{"t":"인물이 아닌 내 이야기","mis":"K6-2-u2-X16"},{"t":"친구가 듣고 싶어 하는 말","mis":"K6-2-u2-X16"}],"explanation":["답은 작품 안에서 나와야 해요.","사건·말·행동이 그대로 근거가 돼요.","마음대로 지어낸 답은 인물의 답이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L11_basic#2','kor',6,2,'u2','L11','g6_2_kor_u2_L11_basic','lesson_basic','K6-2-u2-C4',1,'mc','auto','늘봄에게 하는 질문 「사람들이 처음 웃었을 때 그만두고 싶지는 않았나요?」는 어느 갈래의 질문인가요?',ARRAY['K6-2-u2-X08','K6-2-u2-X05']::text[],false,'{"seq":2,"concept":"K6-2-u2-C4","difficulty":1,"kind":"mc","stem":"늘봄에게 하는 질문 「사람들이 처음 웃었을 때 그만두고 싶지는 않았나요?」는 어느 갈래의 질문인가요?","options":[{"t":"생각이나 느낌에 대한 질문","correct":true},{"t":"구체적인 사실에 대한 질문","mis":"K6-2-u2-X08"},{"t":"앞으로의 계획이나 당부에 대한 질문","mis":"K6-2-u2-X08"},{"t":"면담을 여는 인사","mis":"K6-2-u2-X05"}],"explanation":["그만두고 싶은 마음이 있었는지 묻고 있어요.","마음을 묻는 질문이에요.","인물에게도 세 갈래로 물을 수 있어요."],"asset":{"type":"passage","lines":["마을 한가운데 오래된 종이 있었다.","아침마다 그 소리에 맞추어 사람들이 하루를 시작했다.","어느 겨울, 종이 깨져 소리가 나지 않게 되자","마을 사람들의 시간이 조금씩 어긋나기 시작했다.","늘봄은 아무에게도 말하지 않고 나무판을 두드려 아침 소리를 대신 냈다.","사람들은 처음에는 웃었지만,","사흘이 지나자 그 소리에 맞추어 다시 하루를 열었다."],"title":"「종을 잃은 마을」 — 인물과 면담하기 활동"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L11_basic#3','kor',6,2,'u2','L11','g6_2_kor_u2_L11_basic','lesson_basic','K6-2-u2-C10',1,'ox','auto','늘봄이 되어 「사실 저는 종을 고치는 기술자였습니다.」라고 답해도 돼요.',ARRAY['K6-2-u2-X16']::text[],false,'{"seq":3,"concept":"K6-2-u2-C10","difficulty":1,"kind":"ox","stem":"늘봄이 되어 「사실 저는 종을 고치는 기술자였습니다.」라고 답해도 돼요.","answer":"X","reason_options":[{"t":"이야기 어디에도 그런 말이 없어 인물의 답이 될 수 없기 때문에","correct":true},{"t":"재미있으면 인물의 답이 될 수 있기 때문에","mis":"K6-2-u2-X16"}],"mis":"K6-2-u2-X16","explanation":["인물이 되어 답할 때는 이야기 안에서만 말해요.","이야기에 없는 것은 지어내지 않아요.","「그건 이야기에 나오지 않습니다」라고 해도 돼요."],"asset":{"type":"passage","lines":["마을 한가운데 오래된 종이 있었다.","아침마다 그 소리에 맞추어 사람들이 하루를 시작했다.","어느 겨울, 종이 깨져 소리가 나지 않게 되자","마을 사람들의 시간이 조금씩 어긋나기 시작했다.","늘봄은 아무에게도 말하지 않고 나무판을 두드려 아침 소리를 대신 냈다.","사람들은 처음에는 웃었지만,","사흘이 지나자 그 소리에 맞추어 다시 하루를 열었다."],"title":"「종을 잃은 마을」 — 인물과 면담하기 활동"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L11_basic#4','kor',6,2,'u2','L11','g6_2_kor_u2_L11_basic','lesson_basic','K6-2-u2-C11',1,'mc','auto','받침에 자음이 두 개 있는 것을 무엇이라고 하나요?',ARRAY['K6-2-u2-X18']::text[],false,'{"seq":4,"concept":"K6-2-u2-C11","difficulty":1,"kind":"mc","stem":"받침에 자음이 두 개 있는 것을 무엇이라고 하나요?","options":[{"t":"겹받침","correct":true},{"t":"된소리","mis":"K6-2-u2-X18"},{"t":"모음","mis":"K6-2-u2-X18"},{"t":"높임말","mis":"K6-2-u2-X18"}],"explanation":["「맑다」의 ㄺ, 「넓다」의 ㄼ처럼 받침에 자음이 둘 있어요.","이것을 겹받침이라고 해요.","낱말 하나로 있을 때는 하나만 소리 나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L11_basic#5','kor',6,2,'u2','L11','g6_2_kor_u2_L11_basic','lesson_basic','K6-2-u2-C10',2,'mc','auto','불쾌한 질문을 바람직한 질문으로 바르게 고친 것은 어느 것인가요?',ARRAY['K6-2-u2-X17']::text[],false,'{"seq":5,"concept":"K6-2-u2-C10","difficulty":2,"kind":"mc","stem":"불쾌한 질문을 바람직한 질문으로 바르게 고친 것은 어느 것인가요?","options":[{"t":"「아무도 안 알아줘서 창피하지 않았어요?」 → 「사람들이 알아주지 않을 때 어떤 마음이 드셨나요?」","correct":true},{"t":"「그런 것도 몰랐던 거예요?」 → 「그런 것도 모르셨어요?」","mis":"K6-2-u2-X17"},{"t":"「왜 그렇게 바보 같은 짓을 했나요?」 → 「왜 그렇게 어리석은 짓을 하셨나요?」","mis":"K6-2-u2-X17"},{"t":"「창피했죠?」 → 「창피했다고 말해 주세요.」","mis":"K6-2-u2-X17"}],"explanation":["바람직한 질문은 궁금함과 배려를 함께 담아요.","깎아내리는 뜻을 빼고 마음을 헤아려 물어요.","높임만 바꾸거나 억지로 답하게 하면 고친 것이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L11_basic#6','kor',6,2,'u2','L11','g6_2_kor_u2_L11_basic','lesson_basic','K6-2-u2-C10',2,'mc','auto','늘봄에게 「소리를 대신 내기로 마음먹은 까닭이 있었나요?」라고 물었을 때 작품에 근거한 답은 어느 것인가요?',ARRAY['K6-2-u2-X16']::text[],false,'{"seq":6,"concept":"K6-2-u2-C10","difficulty":2,"kind":"mc","stem":"늘봄에게 「소리를 대신 내기로 마음먹은 까닭이 있었나요?」라고 물었을 때 작품에 근거한 답은 어느 것인가요?","options":[{"t":"종소리가 없어 마을 사람들의 시간이 어긋나는 것이 마음에 걸렸습니다","correct":true},{"t":"마을에서 상을 준다고 해서 시작했습니다","mis":"K6-2-u2-X16"},{"t":"종을 제가 깨뜨려서 혼날까 봐 그랬습니다","mis":"K6-2-u2-X16"},{"t":"나무판 두드리는 소리가 그냥 좋아서였습니다","mis":"K6-2-u2-X16"}],"explanation":["이야기에 종이 깨져 시간이 어긋났다고 나와요.","그 사건이 늘봄의 답을 받쳐 줘요.","상·깨뜨림은 이야기에 없는 내용이에요."],"asset":{"type":"passage","lines":["마을 한가운데 오래된 종이 있었다.","아침마다 그 소리에 맞추어 사람들이 하루를 시작했다.","어느 겨울, 종이 깨져 소리가 나지 않게 되자","마을 사람들의 시간이 조금씩 어긋나기 시작했다.","늘봄은 아무에게도 말하지 않고 나무판을 두드려 아침 소리를 대신 냈다.","사람들은 처음에는 웃었지만,","사흘이 지나자 그 소리에 맞추어 다시 하루를 열었다."],"title":"「종을 잃은 마을」 — 인물과 면담하기 활동"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L11_basic#7','kor',6,2,'u2','L11','g6_2_kor_u2_L11_basic','lesson_basic','K6-2-u2-C10',2,'match','auto','늘봄에게 할 질문과 그 갈래를 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K6-2-u2-C10","difficulty":2,"kind":"match","stem":"늘봄에게 할 질문과 그 갈래를 알맞게 이으세요.","pairs":[{"l":"나무판은 며칠 동안 두드리셨나요?","r":"구체적인 사실에 대한 질문"},{"l":"사람들이 다시 그 소리에 맞추어 하루를 열었을 때 어떠셨나요?","r":"생각이나 느낌에 대한 질문"},{"l":"남이 알아주지 않아도 무언가를 하려는 친구에게 해 줄 말이 있나요?","r":"앞으로의 계획이나 당부에 대한 질문"}],"mis":"K6-2-u2-X08","explanation":["한 일을 묻는지 보아요.","마음을 묻는지 보아요.","남에게 줄 말을 묻는지 보아요."],"asset":{"type":"passage","lines":["마을 한가운데 오래된 종이 있었다.","아침마다 그 소리에 맞추어 사람들이 하루를 시작했다.","어느 겨울, 종이 깨져 소리가 나지 않게 되자","마을 사람들의 시간이 조금씩 어긋나기 시작했다.","늘봄은 아무에게도 말하지 않고 나무판을 두드려 아침 소리를 대신 냈다.","사람들은 처음에는 웃었지만,","사흘이 지나자 그 소리에 맞추어 다시 하루를 열었다."],"title":"「종을 잃은 마을」 — 인물과 면담하기 활동"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L11_basic#8','kor',6,2,'u2','L11','g6_2_kor_u2_L11_basic','lesson_basic','K6-2-u2-C11',2,'mc','auto','「비가 그치니 하늘이 맑아 보인다」에서 「맑아」는 어떻게 소리 나나요?',ARRAY['K6-2-u2-X18']::text[],false,'{"seq":8,"concept":"K6-2-u2-C11","difficulty":2,"kind":"mc","stem":"「비가 그치니 하늘이 맑아 보인다」에서 「맑아」는 어떻게 소리 나나요?","options":[{"t":"[말가]","correct":true},{"t":"[마가]","mis":"K6-2-u2-X18"},{"t":"[막따]","mis":"K6-2-u2-X18"},{"t":"[말까]","mis":"K6-2-u2-X18"}],"explanation":["뒤에 모음 「아」가 붙었어요.","앞의 ㄹ은 받침으로 남고 뒤의 ㄱ이 넘어가 소리 나요.","그래서 [말가]예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L11_basic#9','kor',6,2,'u2','L11','g6_2_kor_u2_L11_basic','lesson_basic','K6-2-u2-C10',2,'mc','auto','바람직한 질문의 모습으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u2-X17']::text[],false,'{"seq":9,"concept":"K6-2-u2-C10","difficulty":2,"kind":"mc","stem":"바람직한 질문의 모습으로 알맞은 것은 어느 것인가요?","options":[{"t":"궁금한 것을 묻되 상대의 마음을 헤아리고 답할 사람이 고를 여지를 남긴다","correct":true},{"t":"모자란 곳을 파고들어 묻는다","mis":"K6-2-u2-X17"},{"t":"말하고 싶지 않은 것도 꼭 답하게 한다","mis":"K6-2-u2-X17"},{"t":"깎아내리는 말로 재미있게 묻는다","mis":"K6-2-u2-X17"}],"explanation":["불쾌한 질문은 모자란 곳을 파고들거나 깎아내려요.","억지로 답하게 하는 것도 불쾌한 질문이에요.","바람직한 질문은 마음을 헤아리고 여지를 남겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L11_basic#10','kor',6,2,'u2','L11','g6_2_kor_u2_L11_basic','lesson_basic','K6-2-u2-C10',3,'error','auto','짝과 늘봄 면담 놀이를 했어요. 늘봄이 되어 작품에 근거하지 않고 답한 친구는 누구인가요?',ARRAY['K6-2-u2-X16']::text[],false,'{"seq":10,"concept":"K6-2-u2-C10","difficulty":3,"kind":"error","stem":"짝과 늘봄 면담 놀이를 했어요. 늘봄이 되어 작품에 근거하지 않고 답한 친구는 누구인가요?","options":[{"t":"하준 — 「(늘봄이 되어) 마을 사람들이 저에게 큰 상을 주었어요.」","correct":true,"mis_target":"K6-2-u2-X16"},{"t":"보미 — 「(늘봄이 되어) 처음에는 사람들이 웃었지만 사흘을 이어 갔어요.」","mis":"K6-2-u2-X16"},{"t":"지우 — 「(늘봄이 되어) 그건 이야기에 나오지 않습니다.」","mis":"K6-2-u2-X16"}],"explanation":["이야기에 상을 받았다는 말은 없어요.","보미는 이야기 속 행동으로 답했어요.","지우처럼 없는 것은 없다고 말해도 돼요."],"asset":{"type":"passage","lines":["마을 한가운데 오래된 종이 있었다.","아침마다 그 소리에 맞추어 사람들이 하루를 시작했다.","어느 겨울, 종이 깨져 소리가 나지 않게 되자","마을 사람들의 시간이 조금씩 어긋나기 시작했다.","늘봄은 아무에게도 말하지 않고 나무판을 두드려 아침 소리를 대신 냈다.","사람들은 처음에는 웃었지만,","사흘이 지나자 그 소리에 맞추어 다시 하루를 열었다."],"title":"「종을 잃은 마을」 — 인물과 면담하기 활동"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L11_challenge#1','kor',6,2,'u2','L11','g6_2_kor_u2_L11_challenge','lesson_challenge','K6-2-u2-C11',2,'sa','auto','「달이 밝은 밤」에서 「밝은」을 소리 나는 대로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K6-2-u2-C11","difficulty":2,"kind":"sa","stem":"「달이 밝은 밤」에서 「밝은」을 소리 나는 대로 쓰세요.","answer":["발근","[발근]"],"explanation":["「밝」 뒤에 모음 「은」이 붙었어요.","ㄹ은 받침으로 남고 ㄱ이 넘어가요.","그래서 [발근]으로 소리 나요."],"mis":"K6-2-u2-X18"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L11_challenge#2','kor',6,2,'u2','L11','g6_2_kor_u2_L11_challenge','lesson_challenge','K6-2-u2-C10',2,'mc','auto','사람들 앞에서 묻고 답하는 것이 어려운 친구가 할 수 있는 일로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u2-X19','K6-2-u2-X16']::text[],false,'{"seq":2,"concept":"K6-2-u2-C10","difficulty":2,"kind":"mc","stem":"사람들 앞에서 묻고 답하는 것이 어려운 친구가 할 수 있는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"먼저 지켜보거나, 질문지를 보며 읽거나, 질문을 만들어 주는 일을 맡는다","correct":true},{"t":"활동에서 빠지고 아무것도 하지 않는다","mis":"K6-2-u2-X19"},{"t":"부끄러운 일이니 억지로 크게 말한다","mis":"K6-2-u2-X19"},{"t":"인물 역할을 맡아 마음대로 답을 지어낸다","mis":"K6-2-u2-X16"}],"explanation":["어렵게 느끼는 것은 부끄러운 일이 아니에요.","할 수 있는 만큼부터 함께해요.","다음번에는 질문 하나만 직접 해 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L11_challenge#3','kor',6,2,'u2','L11','g6_2_kor_u2_L11_challenge','lesson_challenge','K6-2-u2-C11',3,'mc','auto','밑줄 친 말의 발음이 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u2-X18']::text[],false,'{"seq":3,"concept":"K6-2-u2-C11","difficulty":3,"kind":"mc","stem":"밑줄 친 말의 발음이 알맞은 것은 어느 것인가요?","options":[{"t":"「밑동이 굵은 편이다」의 「굵은」 → [굴근]","correct":true},{"t":"「해가 짧아 금방 어둡다」의 「짧아」 → [짜바]","mis":"K6-2-u2-X18"},{"t":"「운동장이 넓은 것 같다」의 「넓은」 → [너븐]","mis":"K6-2-u2-X18"},{"t":"「하늘이 맑아 보인다」의 「맑아」 → [마가]","mis":"K6-2-u2-X18"}],"explanation":["모음이 붙으면 앞 자음은 받침으로 남아요.","뒤 자음만 넘어가 소리 나요.","짧아[짤바] · 넓은[널븐] · 맑아[말가]예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L11_challenge#4','kor',6,2,'u2','L11','g6_2_kor_u2_L11_challenge','lesson_challenge','K6-2-u2-C10',3,'mc','auto','인물이 되어 답해 보면 좋은 점으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u2-X16']::text[],false,'{"seq":4,"concept":"K6-2-u2-C10","difficulty":3,"kind":"mc","stem":"인물이 되어 답해 보면 좋은 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"답할 근거를 찾으려 이야기를 다시 읽게 되어 지나쳤던 작은 행동이 보인다","correct":true},{"t":"이야기를 다시 읽지 않아도 된다","mis":"K6-2-u2-X16"},{"t":"이야기에 없는 내용을 마음껏 지을 수 있다","mis":"K6-2-u2-X16"},{"t":"인물의 마음은 몰라도 된다","mis":"K6-2-u2-X16"}],"explanation":["은새는 「아무에게도 말하지 않고」가 눈에 들어왔다고 했어요.","그 한 마디로 늘봄의 마음을 짐작했어요.","인물이 되어 답하려면 작품을 다시 읽게 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L11_challenge#5','kor',6,2,'u2','L11','g6_2_kor_u2_L11_challenge','lesson_challenge','K6-2-u2-C10',3,'error','auto','바람직한 질문을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u2-X17']::text[],false,'{"seq":5,"concept":"K6-2-u2-C10","difficulty":3,"kind":"error","stem":"바람직한 질문을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"누리 — 「궁금하면 아무리 곤란한 것도 꼭 답하게 해야 해.」","correct":true,"mis_target":"K6-2-u2-X17"},{"t":"찬희 — 「답할 사람이 고를 여지를 남겨야 해.」","mis":"K6-2-u2-X17"},{"t":"하늘 — 「모자란 곳을 파고드는 질문은 고쳐 써야 해.」","mis":"K6-2-u2-X17"}],"explanation":["억지로 답하게 하는 질문은 불쾌한 질문이에요.","찬희와 하늘은 바르게 말했어요.","궁금함과 배려를 함께 담아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L11_challenge#6','kor',6,2,'u2','L11','g6_2_kor_u2_L11_challenge','lesson_challenge','K6-2-u2-C10',3,'ox','auto','은새는 「아무에게도 말하지 않고」라는 말에서 늘봄의 마음을 짐작했어요. 이처럼 작은 표현도 인물이 되어 답하는 근거가 돼요.',ARRAY['K6-2-u2-X16']::text[],false,'{"seq":6,"concept":"K6-2-u2-C10","difficulty":3,"kind":"ox","stem":"은새는 「아무에게도 말하지 않고」라는 말에서 늘봄의 마음을 짐작했어요. 이처럼 작은 표현도 인물이 되어 답하는 근거가 돼요.","answer":"O","reason_options":[{"t":"이야기 속 말과 행동이 인물의 답을 받쳐 주는 근거이기 때문에","correct":true},{"t":"인물의 답은 작품과 상관없이 정하기 때문에","mis":"K6-2-u2-X16"}],"mis":"K6-2-u2-X16","explanation":["그냥 읽을 때는 작은 행동을 지나치기 쉬워요.","답하려고 보면 그 말이 근거로 살아나요.","근거는 언제나 작품 안에 있어요."],"asset":{"type":"passage","lines":["마을 한가운데 오래된 종이 있었다.","아침마다 그 소리에 맞추어 사람들이 하루를 시작했다.","어느 겨울, 종이 깨져 소리가 나지 않게 되자","마을 사람들의 시간이 조금씩 어긋나기 시작했다.","늘봄은 아무에게도 말하지 않고 나무판을 두드려 아침 소리를 대신 냈다.","사람들은 처음에는 웃었지만,","사흘이 지나자 그 소리에 맞추어 다시 하루를 열었다."],"title":"「종을 잃은 마을」 — 인물과 면담하기 활동"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L11_challenge#7','kor',6,2,'u2','L11','g6_2_kor_u2_L11_challenge','lesson_challenge','K6-2-u2-C11',3,'match','auto','낱말과 그 발음을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K6-2-u2-C11","difficulty":3,"kind":"match","stem":"낱말과 그 발음을 알맞게 이으세요.","pairs":[{"l":"맑다","r":"[막따]"},{"l":"맑아","r":"[말가]"},{"l":"넓다","r":"[널따]"},{"l":"넓은","r":"[널븐]"}],"mis":"K6-2-u2-X18","explanation":["낱말 하나로 있을 때는 하나만 소리 나요.","모음이 붙으면 뒤 자음이 넘어가요.","같은 겹받침도 뒤에 무엇이 오느냐에 따라 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L11_challenge#8','kor',6,2,'u2','L11','g6_2_kor_u2_L11_challenge','lesson_challenge','K6-2-u2-C10',4,'mc','auto','「아무도 안 알아줘서 창피하지 않았어요?」를 바람직한 질문으로 고치고 늘봄이 되어 작품을 근거로 답한 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u2-X17','K6-2-u2-X16']::text[],false,'{"seq":8,"concept":"K6-2-u2-C10","difficulty":4,"kind":"mc","stem":"「아무도 안 알아줘서 창피하지 않았어요?」를 바람직한 질문으로 고치고 늘봄이 되어 작품을 근거로 답한 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"질문 「처음에 사람들이 웃었을 때 어떤 마음이 드셨나요?」 — 답 「서운했지만 아침이 어긋나는 게 더 마음에 걸려 사흘을 이어 갔어요.」","correct":true},{"t":"질문 「창피했다고 솔직히 말해 주세요.」 — 답 「네, 창피했어요.」","mis":"K6-2-u2-X17"},{"t":"질문 「처음에 사람들이 웃었을 때 어떤 마음이 드셨나요?」 — 답 「저는 종을 고치는 기술자라 괜찮았어요.」","mis":"K6-2-u2-X16"},{"t":"질문 「왜 그렇게 바보 같은 짓을 했나요?」 — 답 「상을 받고 싶었어요.」","mis":"K6-2-u2-X17"}],"explanation":["질문은 마음을 헤아려 고쳐요.","답은 「처음에는 웃었지만」, 「사흘이 지나자」 같은 이야기 속 사건에서 나와요.","둘 다 갖추어야 좋은 인물 면담이에요."],"asset":{"type":"passage","lines":["마을 한가운데 오래된 종이 있었다.","아침마다 그 소리에 맞추어 사람들이 하루를 시작했다.","어느 겨울, 종이 깨져 소리가 나지 않게 되자","마을 사람들의 시간이 조금씩 어긋나기 시작했다.","늘봄은 아무에게도 말하지 않고 나무판을 두드려 아침 소리를 대신 냈다.","사람들은 처음에는 웃었지만,","사흘이 지나자 그 소리에 맞추어 다시 하루를 열었다."],"title":"「종을 잃은 마을」 — 인물과 면담하기 활동"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L11_challenge#9','kor',6,2,'u2','L11','g6_2_kor_u2_L11_challenge','lesson_challenge','K6-2-u2-C10',4,'essay','teacher','「종을 잃은 마을」의 늘봄에게 할 질문을 세 갈래로 하나씩 만들고, 그 가운데 하나를 골라 늘봄이 되어 작품을 근거로 답해 보세요.','{}'::text[],false,'{"seq":9,"concept":"K6-2-u2-C10","difficulty":4,"kind":"essay","stem":"「종을 잃은 마을」의 늘봄에게 할 질문을 세 갈래로 하나씩 만들고, 그 가운데 하나를 골라 늘봄이 되어 작품을 근거로 답해 보세요.","answer_guide":{"answer":"예: 사실 — 아침 소리를 내려고 무엇을 하셨나요? 생각이나 느낌 — 사람들이 처음에 웃었을 때 어떤 마음이 드셨나요? 계획이나 당부 — 혼자 무언가를 시작하려는 친구에게 해 줄 말이 있나요? 답(생각이나 느낌) — 처음에는 서운했어요. 그래도 종이 깨진 뒤 마을 사람들의 시간이 어긋나는 게 더 마음에 걸려서 아무에게도 말하지 않고 나무판을 계속 두드렸어요.","scoring_points":["세 갈래로 질문을 하나씩 만들었는가","질문이 불쾌하지 않고 바람직한가","작품 속 사건·행동을 근거로 답했는가"]},"explanation":["인물에게도 세 갈래로 물어요.","마음을 헤아리는 질문으로 써요.","답은 이야기 안에서만 찾아요."],"asset":{"type":"passage","lines":["마을 한가운데 오래된 종이 있었다.","아침마다 그 소리에 맞추어 사람들이 하루를 시작했다.","어느 겨울, 종이 깨져 소리가 나지 않게 되자","마을 사람들의 시간이 조금씩 어긋나기 시작했다.","늘봄은 아무에게도 말하지 않고 나무판을 두드려 아침 소리를 대신 냈다.","사람들은 처음에는 웃었지만,","사흘이 지나자 그 소리에 맞추어 다시 하루를 열었다."],"title":"「종을 잃은 마을」 — 인물과 면담하기 활동"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_L11_challenge#10','kor',6,2,'u2','L11','g6_2_kor_u2_L11_challenge','lesson_challenge','K6-2-u2-C11',4,'essay','teacher','「맑다」와 「넓다」를 낱말 하나로 읽을 때와 뒤에 모음으로 시작하는 말이 붙을 때 발음이 어떻게 달라지는지 예를 들어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u2-C11","difficulty":4,"kind":"essay","stem":"「맑다」와 「넓다」를 낱말 하나로 읽을 때와 뒤에 모음으로 시작하는 말이 붙을 때 발음이 어떻게 달라지는지 예를 들어 쓰세요.","answer_guide":{"answer":"예: 낱말 하나로 읽을 때는 겹받침 가운데 하나만 소리 나서 「맑다」는 [막따], 「넓다」는 [널따]로 읽는다. 뒤에 모음으로 시작하는 말이 붙으면 앞 자음은 받침으로 남고 뒤 자음이 넘어가 소리 나서 「맑아」는 [말가], 「넓은」은 [널븐]으로 읽는다.","scoring_points":["낱말 하나로 읽을 때 하나만 소리 남을 예와 함께 썼는가","모음이 붙을 때 뒤 자음이 넘어감을 예와 함께 썼는가","두 낱말의 발음을 바르게 적었는가"]},"explanation":["홀로 있을 때는 하나만 소리 나요.","모음이 오면 뒤 자음이 넘어가요.","맑아[말가] · 넓은[널븐]이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_a#1','kor',6,2,'u2','','g6_2_kor_u2_review_a','unit_review','K6-2-u2-C1',1,'mc','auto','면담에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u2-X01','K6-2-u2-X02']::text[],false,'{"seq":1,"concept":"K6-2-u2-C1","difficulty":1,"kind":"mc","stem":"면담에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"정보를 얻으려는 목적이 있고 준비·진행·정리의 차례가 있는 대화이다","correct":true},{"t":"차례 없이 떠오르는 대로 나누는 이야기이다","mis":"K6-2-u2-X01"},{"t":"누가 더 많이 아는지 겨루는 대화이다","mis":"K6-2-u2-X01"},{"t":"누리집 글을 소리 내어 읽는 일이다","mis":"K6-2-u2-X02"}],"explanation":["면담은 목적이 있는 대화예요.","준비·진행·정리의 차례가 있어요.","겨루기나 낭독이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_a#2','kor',6,2,'u2','','g6_2_kor_u2_review_a','unit_review','K6-2-u2-C2',1,'mc','auto','면담을 요청할 때 밝혀야 할 것으로 알맞지 않은 것은 어느 것인가요?',ARRAY['K6-2-u2-X03']::text[],false,'{"seq":2,"concept":"K6-2-u2-C2","difficulty":1,"kind":"mc","stem":"면담을 요청할 때 밝혀야 할 것으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"상대가 한 달에 버는 돈","correct":true},{"t":"우리가 누구인지","mis":"K6-2-u2-X03"},{"t":"면담을 하려는 목적","mis":"K6-2-u2-X03"},{"t":"걸리는 시간","mis":"K6-2-u2-X03"}],"explanation":["누구·목적·시간·날짜와 장소를 밝혀요.","그래야 상대가 응할지 정할 수 있어요.","버는 돈은 개인 정보라 묻지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_a#3','kor',6,2,'u2','','g6_2_kor_u2_review_a','unit_review','K6-2-u2-C3',1,'mc','auto','면담 진행하기의 마지막 단계는 어느 것인가요?',ARRAY['K6-2-u2-X05']::text[],false,'{"seq":3,"concept":"K6-2-u2-C3","difficulty":1,"kind":"mc","stem":"면담 진행하기의 마지막 단계는 어느 것인가요?","options":[{"t":"면담 마무리하기","correct":true},{"t":"면담 열기","mis":"K6-2-u2-X05"},{"t":"질문하기","mis":"K6-2-u2-X05"},{"t":"면담 보고서 쓰기","mis":"K6-2-u2-X05"}],"explanation":["진행하기는 열기 → 질문하기 → 마무리하기예요.","마무리에서 알게 된 것을 확인하고 감사 인사를 드려요.","보고서 쓰기는 정리하기에 들어가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_a#4','kor',6,2,'u2','','g6_2_kor_u2_review_a','unit_review','K6-2-u2-C4',1,'mc','auto','소미의 질문 「책방에서 하루에 가장 많이 하시는 일은 무엇인가요?」는 어느 갈래인가요?',ARRAY['K6-2-u2-X08','K6-2-u2-X05']::text[],false,'{"seq":4,"concept":"K6-2-u2-C4","difficulty":1,"kind":"mc","stem":"소미의 질문 「책방에서 하루에 가장 많이 하시는 일은 무엇인가요?」는 어느 갈래인가요?","options":[{"t":"구체적인 사실에 대한 질문","correct":true},{"t":"생각이나 느낌에 대한 질문","mis":"K6-2-u2-X08"},{"t":"앞으로의 계획이나 당부에 대한 질문","mis":"K6-2-u2-X08"},{"t":"면담을 마무리하는 말","mis":"K6-2-u2-X05"}],"explanation":["하루에 하는 일은 있는 그대로의 일이에요.","구체적인 사실에 대한 질문이에요.","마음이나 당부를 묻지 않았어요."],"asset":{"type":"speech","turns":[{"who":"소미","text":"책방에서 하루에 가장 많이 하시는 일은 무엇인가요?"},{"who":"진다해","text":"책을 고르는 일이에요. 들어오는 책을 다 놓을 수는 없어서, 우리 동네 사람들이 읽을 만한 책을 골라 놓아요."},{"who":"예준","text":"방금 「우리 동네 사람들이 읽을 만한 책」이라고 하셨는데, 그건 어떻게 아시나요?"},{"who":"진다해","text":"손님이 책을 고르다 내려놓는 모습을 봐요. 무엇을 찾다가 못 찾았는지 여쭈어 공책에 적어 두지요."},{"who":"소미","text":"책방을 하시며 가장 보람 있었던 때는 언제인가요?"},{"who":"진다해","text":"어릴 때 오던 손님이 커서 자기 아이 손을 잡고 왔을 때요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_a#5','kor',6,2,'u2','','g6_2_kor_u2_review_a','unit_review','K6-2-u2-C6',1,'ox','auto','면담 대상자의 답이 마음에 들지 않으면 다시 답하게 해도 돼요.',ARRAY['K6-2-u2-X10']::text[],false,'{"seq":5,"concept":"K6-2-u2-C6","difficulty":1,"kind":"ox","stem":"면담 대상자의 답이 마음에 들지 않으면 다시 답하게 해도 돼요.","answer":"X","reason_options":[{"t":"시간을 내어 주신 분께 예의를 지키고 말씀을 존중해야 하기 때문에","correct":true},{"t":"원하는 답을 들어야 보고서를 쓸 수 있기 때문에","mis":"K6-2-u2-X10"}],"mis":"K6-2-u2-X10","explanation":["답은 그분의 생각이에요.","다시 답하게 하는 것은 예의가 아니에요.","궁금하면 후속 질문으로 더 여쭈어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_a#6','kor',6,2,'u2','','g6_2_kor_u2_review_a','unit_review','K6-2-u2-C7',1,'mc','auto','비대면 면담의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u2-X12']::text[],false,'{"seq":6,"concept":"K6-2-u2-C7","difficulty":1,"kind":"mc","stem":"비대면 면담의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"직접 만나지 않고 영상 통화나 전자 우편으로 하는 면담","correct":true},{"t":"얼굴을 마주 보고 하는 면담","mis":"K6-2-u2-X12"},{"t":"면담 대상자 없이 혼자 질문만 써 보는 일","mis":"K6-2-u2-X12"},{"t":"녹음 없이 하는 면담","mis":"K6-2-u2-X12"}],"explanation":["비대면은 마주하지 않는다는 뜻이에요.","영상 통화·전자 우편으로 해요.","멀리 계신 분과도 면담할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_a#7','kor',6,2,'u2','','g6_2_kor_u2_review_a','unit_review','K6-2-u2-C9',1,'mc','auto','면담 보고서 뒷부분에 담는 내용으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u2-X15','K6-2-u2-X04']::text[],false,'{"seq":7,"concept":"K6-2-u2-C9","difficulty":1,"kind":"mc","stem":"면담 보고서 뒷부분에 담는 내용으로 알맞은 것은 어느 것인가요?","options":[{"t":"면담을 마친 뒤 깨달은 점과 달라진 생각","correct":true},{"t":"면담 목적과 대상자","mis":"K6-2-u2-X15"},{"t":"면담으로 새롭게 안 사실","mis":"K6-2-u2-X15"},{"t":"면담 대상자의 연락처","mis":"K6-2-u2-X04"}],"explanation":["뒷부분은 면담 뒤의 마음이에요.","목적·대상자는 앞부분, 새로 안 사실은 가운데예요.","연락처는 넣지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_a#8','kor',6,2,'u2','','g6_2_kor_u2_review_a','unit_review','K6-2-u2-C11',1,'mc','auto','「맑다」는 어떻게 소리 나나요?',ARRAY['K6-2-u2-X18']::text[],false,'{"seq":8,"concept":"K6-2-u2-C11","difficulty":1,"kind":"mc","stem":"「맑다」는 어떻게 소리 나나요?","options":[{"t":"[막따]","correct":true},{"t":"[말따]","mis":"K6-2-u2-X18"},{"t":"[말가]","mis":"K6-2-u2-X18"},{"t":"[맑따]","mis":"K6-2-u2-X18"}],"explanation":["낱말 하나로 있을 때 겹받침은 하나만 소리 나요.","「맑다」는 ㄱ이 소리 나요.","그래서 [막따]예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_a#9','kor',6,2,'u2','','g6_2_kor_u2_review_a','unit_review','K6-2-u2-C5',2,'mc','auto','「책방을 꾸리는 사람」 면담에서 후속 질문은 어느 것인가요?',ARRAY['K6-2-u2-X06','K6-2-u2-X05']::text[],false,'{"seq":9,"concept":"K6-2-u2-C5","difficulty":2,"kind":"mc","stem":"「책방을 꾸리는 사람」 면담에서 후속 질문은 어느 것인가요?","options":[{"t":"「방금 ‘우리 동네 사람들이 읽을 만한 책’이라고 하셨는데, 그건 어떻게 아시나요?」","correct":true},{"t":"「책방에서 하루에 가장 많이 하시는 일은 무엇인가요?」","mis":"K6-2-u2-X06"},{"t":"「책방을 하시며 가장 보람 있었던 때는 언제인가요?」","mis":"K6-2-u2-X06"},{"t":"「말씀을 정확히 남기려고 녹음하고 싶은데 괜찮으실까요?」","mis":"K6-2-u2-X05"}],"explanation":["후속 질문은 앞선 답에 나온 말을 붙들어요.","예준은 「읽을 만한 책」을 붙들고 이어서 물었어요.","다른 질문은 미리 준비해 갈 수 있는 것이에요."],"asset":{"type":"speech","turns":[{"who":"소미","text":"책방에서 하루에 가장 많이 하시는 일은 무엇인가요?"},{"who":"진다해","text":"책을 고르는 일이에요. 들어오는 책을 다 놓을 수는 없어서, 우리 동네 사람들이 읽을 만한 책을 골라 놓아요."},{"who":"예준","text":"방금 「우리 동네 사람들이 읽을 만한 책」이라고 하셨는데, 그건 어떻게 아시나요?"},{"who":"진다해","text":"손님이 책을 고르다 내려놓는 모습을 봐요. 무엇을 찾다가 못 찾았는지 여쭈어 공책에 적어 두지요."},{"who":"소미","text":"책방을 하시며 가장 보람 있었던 때는 언제인가요?"},{"who":"진다해","text":"어릴 때 오던 손님이 커서 자기 아이 손을 잡고 왔을 때요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_a#10','kor',6,2,'u2','','g6_2_kor_u2_review_a','unit_review','K6-2-u2-C5',2,'match','auto','「책방을 꾸리는 사람」 면담 속 말과 그 말이 나오는 진행 단계를 알맞게 이으세요.','{}'::text[],false,'{"seq":10,"concept":"K6-2-u2-C5","difficulty":2,"kind":"match","stem":"「책방을 꾸리는 사람」 면담 속 말과 그 말이 나오는 진행 단계를 알맞게 이으세요.","pairs":[{"l":"녹음하고 싶은데 괜찮으실까요?","r":"면담 열기"},{"l":"하루에 가장 많이 하시는 일은 무엇인가요?","r":"질문하기"},{"l":"보고서가 나오면 보여 드리겠습니다. 감사합니다.","r":"면담 마무리하기"}],"mis":"K6-2-u2-X05","explanation":["동의 구하기는 면담 열기예요.","세 갈래 질문은 질문하기예요.","확인과 감사는 마무리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_a#11','kor',6,2,'u2','','g6_2_kor_u2_review_a','unit_review','K6-2-u2-C7',2,'mc','auto','진다해 선생님이 「모둠 과제에만 써 주세요.」라고 하셨어요. 아침별 모둠이 할 일로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u2-X11']::text[],false,'{"seq":11,"concept":"K6-2-u2-C7","difficulty":2,"kind":"mc","stem":"진다해 선생님이 「모둠 과제에만 써 주세요.」라고 하셨어요. 아침별 모둠이 할 일로 알맞은 것은 어느 것인가요?","options":[{"t":"담아 둔 녹음은 보고서를 쓸 때만 쓰고 모둠 밖으로 내보내지 않는다","correct":true},{"t":"재미있는 부분을 잘라 반 누리집에 올린다","mis":"K6-2-u2-X11"},{"t":"다른 반 친구에게도 들려준다","mis":"K6-2-u2-X11"},{"t":"다음 학년 과제에도 가져다 쓴다","mis":"K6-2-u2-X11"}],"explanation":["선생님은 허락하시며 쓰임을 정해 주셨어요.","담아 둔 것은 그 범위 안에서만 써요.","밖으로 내보내지 않아요."],"asset":{"type":"speech","turns":[{"who":"다온","text":"안녕하세요? 바쁘신데 시간 내어 주셔서 감사합니다. 저희는 6학년 아침별 모둠입니다."},{"who":"예준","text":"오늘은 동네 책방을 꾸려 가는 일과 그 일의 보람을 여쭙고자 합니다."},{"who":"다온","text":"말씀을 정확히 남기려고 녹음하고 싶은데 괜찮으실까요?"},{"who":"진다해","text":"네, 괜찮아요. 다만 모둠 과제에만 써 주세요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_a#12','kor',6,2,'u2','','g6_2_kor_u2_review_a','unit_review','K6-2-u2-C4',2,'mc','auto','아침별 모둠의 면담 목적은 「동네 책방을 꾸려 가는 일과 그 일의 보람」을 알아보는 것이에요. 목적에서 벗어난 질문은 어느 것인가요?',ARRAY['K6-2-u2-X07']::text[],false,'{"seq":12,"concept":"K6-2-u2-C4","difficulty":2,"kind":"mc","stem":"아침별 모둠의 면담 목적은 「동네 책방을 꾸려 가는 일과 그 일의 보람」을 알아보는 것이에요. 목적에서 벗어난 질문은 어느 것인가요?","options":[{"t":"「가장 좋아하시는 음식은 무엇인가요?」","correct":true},{"t":"「책을 고르실 때 무엇을 가장 먼저 보시나요?」","mis":"K6-2-u2-X07"},{"t":"「책방을 하시며 힘들었던 때는 언제인가요?」","mis":"K6-2-u2-X07"},{"t":"「손님이 찾는 책이 없을 때는 어떻게 하시나요?」","mis":"K6-2-u2-X07"}],"explanation":["목적은 책방을 꾸리는 일과 보람이에요.","좋아하는 음식은 그 일을 알 수 있는 내용이 아니에요.","나머지는 목적과 이어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_a#13','kor',6,2,'u2','','g6_2_kor_u2_review_a','unit_review','K6-2-u2-C8',2,'mc','auto','「책방을 꾸리는 사람」 질문하기 부분을 가장 잘 간추린 것은 어느 것인가요?',ARRAY['K6-2-u2-X13']::text[],false,'{"seq":13,"concept":"K6-2-u2-C8","difficulty":2,"kind":"mc","stem":"「책방을 꾸리는 사람」 질문하기 부분을 가장 잘 간추린 것은 어느 것인가요?","options":[{"t":"책방 주인은 손님의 모습을 보고 못 찾은 책을 적어 두어 동네 사람들이 읽을 만한 책을 고르고, 어릴 때 손님이 아이와 올 때 보람을 느낀다","correct":true},{"t":"소미가 묻고 선생님이 답하고 예준이 묻고 선생님이 답하고 소미가 또 물었다","mis":"K6-2-u2-X13"},{"t":"책방 이야기를 많이 해 주셨다. 여러 가지를 하신다","mis":"K6-2-u2-X13"},{"t":"책방 주인은 들어오는 책을 모두 놓는다","mis":"K6-2-u2-X13"}],"explanation":["중요한 것이 남고 뜻이 이어져야 해요.","순서 늘어놓기·뭉뚱그리기는 간추린 것이 아니에요.","「모두 놓는다」는 답변의 뜻을 바꾼 것이에요."],"asset":{"type":"speech","turns":[{"who":"소미","text":"책방에서 하루에 가장 많이 하시는 일은 무엇인가요?"},{"who":"진다해","text":"책을 고르는 일이에요. 들어오는 책을 다 놓을 수는 없어서, 우리 동네 사람들이 읽을 만한 책을 골라 놓아요."},{"who":"예준","text":"방금 「우리 동네 사람들이 읽을 만한 책」이라고 하셨는데, 그건 어떻게 아시나요?"},{"who":"진다해","text":"손님이 책을 고르다 내려놓는 모습을 봐요. 무엇을 찾다가 못 찾았는지 여쭈어 공책에 적어 두지요."},{"who":"소미","text":"책방을 하시며 가장 보람 있었던 때는 언제인가요?"},{"who":"진다해","text":"어릴 때 오던 손님이 커서 자기 아이 손을 잡고 왔을 때요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_a#14','kor',6,2,'u2','','g6_2_kor_u2_review_a','unit_review','K6-2-u2-C10',2,'mc','auto','「사흘 걸린 다리」의 태건에게 할 불쾌한 질문을 바르게 고친 것은 어느 것인가요?',ARRAY['K6-2-u2-X17']::text[],false,'{"seq":14,"concept":"K6-2-u2-C10","difficulty":2,"kind":"mc","stem":"「사흘 걸린 다리」의 태건에게 할 불쾌한 질문을 바르게 고친 것은 어느 것인가요?","options":[{"t":"「혼자 돌 옮기는 거 바보 같지 않았어요?」 → 「혼자 돌을 옮기기로 마음먹은 까닭이 있었나요?」","correct":true},{"t":"「쌓은 돌이 무너졌을 때 울었죠?」 → 「울었다고 솔직히 말해 주세요.」","mis":"K6-2-u2-X17"},{"t":"「그것도 못 쌓았어요?」 → 「그것도 못 쌓으셨어요?」","mis":"K6-2-u2-X17"},{"t":"「왜 그렇게 쓸데없는 일을 했어요?」 → 「왜 그렇게 쓸모없는 일을 하셨어요?」","mis":"K6-2-u2-X17"}],"explanation":["깎아내리는 뜻을 빼고 까닭을 여쭈어요.","억지로 답하게 하면 안 돼요.","높임만 바꾸면 고친 것이 아니에요."],"asset":{"type":"passage","lines":["지난여름 큰비가 사흘 동안 내려 징검돌이 떠내려갔다.","할머니는 아랫마을 큰길로 한 시간을 돌아 밭에 다녔다.","어느 날 아침 태건은 혼자 떠내려간 돌을 굴려 올렸다.","돌 하나에 한나절. 거드는 사람도 말리는 사람도 없었다.","사흘째 되던 날 다시 비가 왔고, 이튿날 쌓은 돌이 흩어졌다.","태건은 젖은 모래밭에 주저앉았다.","그때 상우 아저씨가 지게를 지고 왔다. 「나도 좀 하자.」","그다음 날 아침 냇가에 어른 여섯이 나와 다리를 다시 놓았다."],"title":"「사흘 걸린 다리」 간추린 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_a#15','kor',6,2,'u2','','g6_2_kor_u2_review_a','unit_review','K6-2-u2-C2',2,'ox','auto','진다해 선생님께 「선생님 댁은 책방에서 가까운가요?」라고 여쭈어도 돼요.',ARRAY['K6-2-u2-X04']::text[],false,'{"seq":15,"concept":"K6-2-u2-C2","difficulty":2,"kind":"ox","stem":"진다해 선생님께 「선생님 댁은 책방에서 가까운가요?」라고 여쭈어도 돼요.","answer":"X","reason_options":[{"t":"사는 곳은 알리고 싶지 않을 수 있는 개인 정보이기 때문에","correct":true},{"t":"책방과 집이 가까운지는 책방 일과 관련 있기 때문에","mis":"K6-2-u2-X04"}],"mis":"K6-2-u2-X04","explanation":["사는 곳은 개인 정보예요.","궁금해도 묻지 않아요.","하시는 일·보람처럼 목적과 이어진 것을 물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_a#16','kor',6,2,'u2','','g6_2_kor_u2_review_a','unit_review','K6-2-u2-C8',2,'match','auto','모둠 역할과 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":16,"concept":"K6-2-u2-C8","difficulty":2,"kind":"match","stem":"모둠 역할과 하는 일을 알맞게 이으세요.","pairs":[{"l":"약속 담당","r":"예의를 갖추어 날짜·시간·장소를 정하고 모둠에 알린다"},{"l":"질문 담당","r":"질문을 모아 다듬고 진행 담당을 도와 묻는다"},{"l":"정리 담당","r":"핵심을 메모하고 보고서에 쓸 자료를 정리한다"}],"mis":"K6-2-u2-X19","explanation":["날짜를 정하는 것은 약속 담당이에요.","질문을 다듬는 것은 질문 담당이에요.","글로 남기는 것은 정리 담당이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_a#17','kor',6,2,'u2','','g6_2_kor_u2_review_a','unit_review','K6-2-u2-C5',3,'error','auto','「책방을 꾸리는 사람」 면담을 읽고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u2-X06']::text[],false,'{"seq":17,"concept":"K6-2-u2-C5","difficulty":3,"kind":"error","stem":"「책방을 꾸리는 사람」 면담을 읽고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"라온 — 「예준은 질문지에 없는 걸 물었으니 면담 순서를 어긴 거야.」","correct":true,"mis_target":"K6-2-u2-X06"},{"t":"여울 — 「예준은 답을 끝까지 듣고 그 말을 붙들어 물었어.」","mis":"K6-2-u2-X06"},{"t":"하랑 — 「그 덕분에 책을 고르는 방법이라는 중요한 답이 나왔어.」","mis":"K6-2-u2-X06"}],"explanation":["질문지는 지도이지 대본이 아니에요.","듣다가 궁금해지면 이어서 물어도 돼요.","여울과 하랑은 바르게 말했어요."],"asset":{"type":"speech","turns":[{"who":"소미","text":"책방에서 하루에 가장 많이 하시는 일은 무엇인가요?"},{"who":"진다해","text":"책을 고르는 일이에요. 들어오는 책을 다 놓을 수는 없어서, 우리 동네 사람들이 읽을 만한 책을 골라 놓아요."},{"who":"예준","text":"방금 「우리 동네 사람들이 읽을 만한 책」이라고 하셨는데, 그건 어떻게 아시나요?"},{"who":"진다해","text":"손님이 책을 고르다 내려놓는 모습을 봐요. 무엇을 찾다가 못 찾았는지 여쭈어 공책에 적어 두지요."},{"who":"소미","text":"책방을 하시며 가장 보람 있었던 때는 언제인가요?"},{"who":"진다해","text":"어릴 때 오던 손님이 커서 자기 아이 손을 잡고 왔을 때요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_a#18','kor',6,2,'u2','','g6_2_kor_u2_review_a','unit_review','K6-2-u2-C10',3,'mc','auto','태건에게 「사흘째 쌓은 돌이 흩어졌을 때 어떤 마음이 드셨나요?」라고 물었을 때 작품에 근거한 답은 어느 것인가요?',ARRAY['K6-2-u2-X16']::text[],false,'{"seq":18,"concept":"K6-2-u2-C10","difficulty":3,"kind":"mc","stem":"태건에게 「사흘째 쌓은 돌이 흩어졌을 때 어떤 마음이 드셨나요?」라고 물었을 때 작품에 근거한 답은 어느 것인가요?","options":[{"t":"「힘이 빠져 모래밭에 주저앉았어요.」","correct":true},{"t":"「바로 새 다리를 사러 읍내에 갔어요.」","mis":"K6-2-u2-X16"},{"t":"「돌이 흩어져서 오히려 기뻤어요.」","mis":"K6-2-u2-X16"},{"t":"「저는 원래 다리를 놓는 기술자라 괜찮았어요.」","mis":"K6-2-u2-X16"}],"explanation":["이야기에 「젖은 모래밭에 주저앉았다」가 나와요.","그 행동이 마음을 짐작하는 근거예요.","다른 보기는 이야기에 없는 내용이에요."],"asset":{"type":"passage","lines":["지난여름 큰비가 사흘 동안 내려 징검돌이 떠내려갔다.","할머니는 아랫마을 큰길로 한 시간을 돌아 밭에 다녔다.","어느 날 아침 태건은 혼자 떠내려간 돌을 굴려 올렸다.","돌 하나에 한나절. 거드는 사람도 말리는 사람도 없었다.","사흘째 되던 날 다시 비가 왔고, 이튿날 쌓은 돌이 흩어졌다.","태건은 젖은 모래밭에 주저앉았다.","그때 상우 아저씨가 지게를 지고 왔다. 「나도 좀 하자.」","그다음 날 아침 냇가에 어른 여섯이 나와 다리를 다시 놓았다."],"title":"「사흘 걸린 다리」 간추린 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_a#19','kor',6,2,'u2','','g6_2_kor_u2_review_a','unit_review','K6-2-u2-C9',3,'error','auto','아침별 모둠이 면담을 되돌아보며 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-2-u2-X14']::text[],false,'{"seq":19,"concept":"K6-2-u2-C9","difficulty":3,"kind":"error","stem":"아침별 모둠이 면담을 되돌아보며 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"예준 — 「소미 목소리가 작아서 면담이 별로였어.」","correct":true,"mis_target":"K6-2-u2-X14"},{"t":"다온 — 「녹음 허락을 먼저 받은 건 잘한 점이야.」","mis":"K6-2-u2-X14"},{"t":"소미 — 「다음에는 질문을 더 짧게 하기로 하자.」","mis":"K6-2-u2-X14"}],"explanation":["성찰은 사람 탓이 아니에요.","목소리 크기 같은 겉모습은 기준이 아니에요.","다온과 소미는 절차와 약속을 짚었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_a#20','kor',6,2,'u2','','g6_2_kor_u2_review_a','unit_review','K6-2-u2-C6',3,'mc','auto','「책방 그거 장사 잘돼요? 손님 많아요 적어요 그리고 쉬는 날은요?」를 점검할 때 고칠 점을 바르게 모은 것은 어느 것인가요?',ARRAY['K6-2-u2-X10','K6-2-u2-X07','K6-2-u2-X08']::text[],false,'{"seq":20,"concept":"K6-2-u2-C6","difficulty":3,"kind":"mc","stem":"「책방 그거 장사 잘돼요? 손님 많아요 적어요 그리고 쉬는 날은요?」를 점검할 때 고칠 점을 바르게 모은 것은 어느 것인가요?","options":[{"t":"여러 가지를 한꺼번에 물어 뜻이 흐리고 높임을 갖추지 않았다","correct":true},{"t":"질문이 너무 짧고 공손하다","mis":"K6-2-u2-X10"},{"t":"목적과 이어지지 않는 날씨를 물었다","mis":"K6-2-u2-X07"},{"t":"사실을 물어서 쓸 수 없다","mis":"K6-2-u2-X08"}],"explanation":["한 번에 세 가지를 묻고 있어요.","「잘돼요?」처럼 높임도 부족해요.","하나씩 짧고 공손하게 고쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_a#21','kor',6,2,'u2','','g6_2_kor_u2_review_a','unit_review','K6-2-u2-C3',3,'error','auto','면담 절차를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u2-X05']::text[],false,'{"seq":21,"concept":"K6-2-u2-C3","difficulty":3,"kind":"error","stem":"면담 절차를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태린 — 「동의를 구하는 일은 면담을 다 마치고 마무리할 때 해.」","correct":true,"mis_target":"K6-2-u2-X05"},{"t":"승우 — 「동의는 면담 열기에서 구해.」","mis":"K6-2-u2-X05"},{"t":"보람 — 「알게 된 것 확인은 마무리에서 해.」","mis":"K6-2-u2-X05"}],"explanation":["담기 전에 동의를 구해야 하니 면담 열기에서 해요.","확인과 감사는 마무리에서 해요.","승우와 보람은 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_a#22','kor',6,2,'u2','','g6_2_kor_u2_review_a','unit_review','K6-2-u2-C9',3,'mc','auto','아침별 모둠의 보고서 가운데 부분에 들어갈 문장으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u2-X15','K6-2-u2-X04']::text[],false,'{"seq":22,"concept":"K6-2-u2-C9","difficulty":3,"kind":"mc","stem":"아침별 모둠의 보고서 가운데 부분에 들어갈 문장으로 알맞은 것은 어느 것인가요?","options":[{"t":"첫째, 책은 손님이 내려놓는 모습과 못 찾은 책을 적어 둔 것을 보고 고른다고 하셨습니다.","correct":true},{"t":"우리 모둠은 책방 일이 궁금해 진다해 선생님과 면담하기로 했습니다.","mis":"K6-2-u2-X15"},{"t":"면담을 하며 책방이 사람을 오래 보는 곳이라는 것을 깨달았습니다.","mis":"K6-2-u2-X15"},{"t":"선생님 댁은 책방 바로 위층이라고 하셨습니다.","mis":"K6-2-u2-X04"}],"explanation":["가운데 부분은 새롭게 안 사실이에요.","첫째·둘째로 나누어 답변 중심으로 써요.","목적은 앞부분, 깨달은 점은 뒷부분이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_a#23','kor',6,2,'u2','','g6_2_kor_u2_review_a','unit_review','K6-2-u2-C1',4,'mc','auto','「책방을 꾸리는 사람」 면담이 면담의 세 특성(정보·준비·예의)을 모두 갖춘 근거를 바르게 짝지은 것은 어느 것인가요?',ARRAY['K6-2-u2-X04','K6-2-u2-X02','K6-2-u2-X06']::text[],false,'{"seq":23,"concept":"K6-2-u2-C1","difficulty":4,"kind":"mc","stem":"「책방을 꾸리는 사람」 면담이 면담의 세 특성(정보·준비·예의)을 모두 갖춘 근거를 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"정보 — 책을 고르는 방법과 보람을 들었다 / 준비 — 목적을 정하고 질문을 세 갈래로 만들었다 / 예의 — 감사·목적·동의로 열고 감사로 마무리했다","correct":true},{"t":"정보 — 선생님 나이를 알았다 / 준비 — 날짜를 정해 알려 드렸다 / 예의 — 녹음을 몰래 했다","mis":"K6-2-u2-X04"},{"t":"정보 — 책방 수를 알았다 / 준비 — 아무것도 찾지 않았다 / 예의 — 답을 끊고 물었다","mis":"K6-2-u2-X02"},{"t":"정보 — 재미있었다 / 준비 — 질문을 열 개 읽었다 / 예의 — 인사 없이 나왔다","mis":"K6-2-u2-X06"}],"explanation":["정보는 면담이라야 얻는 것이에요.","준비는 목적·질문, 예의는 열기와 마무리의 말이에요.","셋 다 면담 장면에서 근거를 찾을 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_a#24','kor',6,2,'u2','','g6_2_kor_u2_review_a','unit_review','K6-2-u2-C4',4,'essay','teacher','내가 다니는 학교의 도서관 사서 선생님과 면담한다고 할 때, 면담 목적을 한 문장으로 쓰고 질문을 세 갈래로 하나씩 만드세요. 그중 한 질문에 선생님이 답하셨다고 생각하고 할 수 있는 후속 질문도 하나 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-2-u2-C4","difficulty":4,"kind":"essay","stem":"내가 다니는 학교의 도서관 사서 선생님과 면담한다고 할 때, 면담 목적을 한 문장으로 쓰고 질문을 세 갈래로 하나씩 만드세요. 그중 한 질문에 선생님이 답하셨다고 생각하고 할 수 있는 후속 질문도 하나 쓰세요.","answer_guide":{"answer":"예: 목적 — 학교 도서관에 어떤 책을 어떻게 들여오는지 알아보려고. 사실 — 새 책은 한 해에 몇 번 들여오시나요? 생각이나 느낌 — 학생들이 빌려 간 책을 돌려주지 않을 때 어떤 마음이 드시나요? 계획이나 당부 — 앞으로 도서관에서 해 보고 싶은 일이 있으신가요? 후속 질문 — (「학생들이 신청한 책을 먼저 들여온다」는 답을 듣고) 신청한 책이 많을 때는 무엇을 보고 고르시나요?","scoring_points":["면담 목적을 분명하게 썼는가","세 갈래 질문을 목적에 맞게 하나씩 만들었는가","앞선 답을 붙든 후속 질문을 썼는가"]},"explanation":["목적이 분명하면 질문이 저절로 나와요.","세 갈래를 고루 만들어요.","후속 질문은 답의 말을 붙들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_a#25','kor',6,2,'u2','','g6_2_kor_u2_review_a','unit_review','K6-2-u2-C3',4,'essay','teacher','「책방을 꾸리는 사람」 면담을 면담 진행하기의 세 단계로 나누어, 단계마다 아침별 모둠이 한 일을 면담 장면에서 찾아 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K6-2-u2-C3","difficulty":4,"kind":"essay","stem":"「책방을 꾸리는 사람」 면담을 면담 진행하기의 세 단계로 나누어, 단계마다 아침별 모둠이 한 일을 면담 장면에서 찾아 쓰세요.","answer_guide":{"answer":"예: 면담 열기 — 다온이 바쁘신데 시간 내어 주셔서 감사하다고 인사하고, 예준이 책방을 꾸려 가는 일과 보람을 여쭙겠다고 목적을 밝혔으며, 다온이 녹음해도 괜찮은지 동의를 구했다. 질문하기 — 소미가 하루에 가장 많이 하는 일과 보람 있었던 때를 묻고, 예준이 「읽을 만한 책」을 어떻게 아는지 이어서 물었다. 면담 마무리하기 — 다온이 책을 고르는 일이 손님을 오래 보는 일이라는 말씀을 확인하고 감사 인사를 드렸다.","scoring_points":["세 단계로 바르게 나누었는가","단계마다 한 일을 면담 장면에서 찾아 썼는가","열기의 인사·목적·동의와 마무리의 확인·감사를 빠뜨리지 않았는가"]},"explanation":["열기 · 질문하기 · 마무리하기로 나눠요.","장면 속 말을 근거로 써요.","단계마다 하는 일이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_b#1','kor',6,2,'u2','','g6_2_kor_u2_review_b','unit_review','K6-2-u2-C1',1,'mc','auto','책방 주인 진다해 선생님께 여쭐 물음 가운데 면담이라야 답을 들을 수 있는 것은 어느 것인가요?',ARRAY['K6-2-u2-X02']::text[],false,'{"seq":1,"concept":"K6-2-u2-C1","difficulty":1,"kind":"mc","stem":"책방 주인 진다해 선생님께 여쭐 물음 가운데 면담이라야 답을 들을 수 있는 것은 어느 것인가요?","options":[{"t":"책방을 하시며 가장 보람 있었던 때는 언제인가요?","correct":true},{"t":"「책방」이라는 낱말의 사전 뜻은 무엇인가요?","mis":"K6-2-u2-X02"},{"t":"우리나라에 책방은 모두 몇 곳인가요?","mis":"K6-2-u2-X02"},{"t":"올해 가장 많이 팔린 책의 제목은 무엇인가요?","mis":"K6-2-u2-X02"}],"explanation":["보람 있었던 때는 그분만 아는 겪은 일이에요.","사전 뜻·수·판매 순위는 찾아보면 나와요.","면담이라야 얻는 것이 생생한 정보예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_b#2','kor',6,2,'u2','','g6_2_kor_u2_review_b','unit_review','K6-2-u2-C2',1,'mc','auto','면담 대상자께 물어도 되는 것은 어느 것인가요?',ARRAY['K6-2-u2-X04']::text[],false,'{"seq":2,"concept":"K6-2-u2-C2","difficulty":1,"kind":"mc","stem":"면담 대상자께 물어도 되는 것은 어느 것인가요?","options":[{"t":"그 일을 하게 된 까닭","correct":true},{"t":"사시는 곳","mis":"K6-2-u2-X04"},{"t":"나이","mis":"K6-2-u2-X04"},{"t":"가족이 몇 명인지","mis":"K6-2-u2-X04"}],"explanation":["물어도 되는 것은 목적과 이어진 것이에요.","하시는 일·까닭·어려운 점·보람 같은 것이에요.","사는 곳·나이·가족은 개인 정보예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_b#3','kor',6,2,'u2','','g6_2_kor_u2_review_b','unit_review','K6-2-u2-C3',1,'mc','auto','면담 정리하기에서 하는 일은 어느 것인가요?',ARRAY['K6-2-u2-X05']::text[],false,'{"seq":3,"concept":"K6-2-u2-C3","difficulty":1,"kind":"mc","stem":"면담 정리하기에서 하는 일은 어느 것인가요?","options":[{"t":"담아 둔 것과 메모로 내용을 간추리고 과정을 성찰해 보고서를 쓴다","correct":true},{"t":"목적에 알맞은 자료를 찾고 질문을 만든다","mis":"K6-2-u2-X05"},{"t":"동의를 구하고 목적에 맞게 묻는다","mis":"K6-2-u2-X05"},{"t":"대상자에게 면담을 요청한다","mis":"K6-2-u2-X05"}],"explanation":["정리하기는 만난 뒤에 해요.","간추리기 · 성찰하기 · 보고서 쓰기예요.","자료 찾기와 요청은 준비, 묻기는 진행이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_b#4','kor',6,2,'u2','','g6_2_kor_u2_review_b','unit_review','K6-2-u2-C4',1,'mc','auto','예준의 질문 「책방을 하고 싶은 학생에게 해 주실 말씀이 있나요?」는 어느 갈래인가요?',ARRAY['K6-2-u2-X08','K6-2-u2-X05']::text[],false,'{"seq":4,"concept":"K6-2-u2-C4","difficulty":1,"kind":"mc","stem":"예준의 질문 「책방을 하고 싶은 학생에게 해 주실 말씀이 있나요?」는 어느 갈래인가요?","options":[{"t":"앞으로의 계획이나 당부에 대한 질문","correct":true},{"t":"구체적인 사실에 대한 질문","mis":"K6-2-u2-X08"},{"t":"생각이나 느낌에 대한 질문","mis":"K6-2-u2-X08"},{"t":"면담 목적을 밝히는 말","mis":"K6-2-u2-X05"}],"explanation":["뒷사람에게 해 줄 말을 묻고 있어요.","당부에 대한 질문이에요.","면담 끝 무렵에 묻기 좋아요."],"asset":{"type":"speech","turns":[{"who":"예준","text":"책방을 하고 싶은 학생에게 해 주실 말씀이 있나요?"},{"who":"진다해","text":"책을 많이 읽는 것만큼 사람 이야기를 많이 들어 보세요."},{"who":"다온","text":"책을 고르는 일이 손님의 모습을 오래 보는 일이라는 말씀이 기억에 남습니다. 보고서가 나오면 보여 드리겠습니다. 감사합니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_b#5','kor',6,2,'u2','','g6_2_kor_u2_review_b','unit_review','K6-2-u2-C6',1,'ox','auto','면담을 마친 뒤에는 알게 된 것을 확인하고 감사 인사를 드려요.',ARRAY['K6-2-u2-X10']::text[],false,'{"seq":5,"concept":"K6-2-u2-C6","difficulty":1,"kind":"ox","stem":"면담을 마친 뒤에는 알게 된 것을 확인하고 감사 인사를 드려요.","answer":"O","reason_options":[{"t":"면담 마무리하기에서 결과를 확인하고 감사 인사를 하기 때문에","correct":true},{"t":"감사 인사는 보고서에만 쓰면 되기 때문에","mis":"K6-2-u2-X10"}],"mis":"K6-2-u2-X10","explanation":["마무리에서 알게 된 것을 확인해요.","시간을 내어 주신 데 감사드려요.","다온도 그렇게 마무리했어요."],"asset":{"type":"speech","turns":[{"who":"예준","text":"책방을 하고 싶은 학생에게 해 주실 말씀이 있나요?"},{"who":"진다해","text":"책을 많이 읽는 것만큼 사람 이야기를 많이 들어 보세요."},{"who":"다온","text":"책을 고르는 일이 손님의 모습을 오래 보는 일이라는 말씀이 기억에 남습니다. 보고서가 나오면 보여 드리겠습니다. 감사합니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_b#6','kor',6,2,'u2','','g6_2_kor_u2_review_b','unit_review','K6-2-u2-C7',1,'mc','auto','면담 준비하기에서 매체를 쓰는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u2-X12','K6-2-u2-X11']::text[],false,'{"seq":6,"concept":"K6-2-u2-C7","difficulty":1,"kind":"mc","stem":"면담 준비하기에서 매체를 쓰는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"누리집과 책에서 필요한 자료를 찾는다","correct":true},{"t":"담아 둔 것을 다시 들으며 간추린다","mis":"K6-2-u2-X12"},{"t":"녹음기로 대답을 담는다","mis":"K6-2-u2-X12"},{"t":"보고서를 누리집에 올린다","mis":"K6-2-u2-X11"}],"explanation":["준비할 때는 자료를 찾는 데 써요.","담기는 진행, 다시 듣기는 정리에서 해요.","절차마다 쓰임이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_b#7','kor',6,2,'u2','','g6_2_kor_u2_review_b','unit_review','K6-2-u2-C9',1,'mc','auto','「다음에는 감사 인사를 끝까지 드리고 나오자.」는 성찰의 어느 항목인가요?',ARRAY['K6-2-u2-X14','K6-2-u2-X15']::text[],false,'{"seq":7,"concept":"K6-2-u2-C9","difficulty":1,"kind":"mc","stem":"「다음에는 감사 인사를 끝까지 드리고 나오자.」는 성찰의 어느 항목인가요?","options":[{"t":"다음 면담에서 실천할 점","correct":true},{"t":"잘한 점","mis":"K6-2-u2-X14"},{"t":"더 알고 싶은 점","mis":"K6-2-u2-X14"},{"t":"면담 목적","mis":"K6-2-u2-X15"}],"explanation":["다음에 할 행동을 정했어요.","보완할 점을 바꾼 실천할 점이에요.","모둠의 약속이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_b#8','kor',6,2,'u2','','g6_2_kor_u2_review_b','unit_review','K6-2-u2-C11',1,'mc','auto','「넓다」는 어떻게 소리 나나요?',ARRAY['K6-2-u2-X18']::text[],false,'{"seq":8,"concept":"K6-2-u2-C11","difficulty":1,"kind":"mc","stem":"「넓다」는 어떻게 소리 나나요?","options":[{"t":"[널따]","correct":true},{"t":"[넙따]","mis":"K6-2-u2-X18"},{"t":"[널븐]","mis":"K6-2-u2-X18"},{"t":"[너따]","mis":"K6-2-u2-X18"}],"explanation":["「넓다」는 낱말 하나로 있어요.","겹받침 ㄼ 가운데 ㄹ만 소리 나요.","그래서 [널따]예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_b#9','kor',6,2,'u2','','g6_2_kor_u2_review_b','unit_review','K6-2-u2-C5',2,'mc','auto','진다해 선생님의 답 「무엇을 찾다가 못 찾았는지 여쭈어 공책에 적어 두지요.」를 듣고 할 수 있는 후속 질문은 어느 것인가요?',ARRAY['K6-2-u2-X06','K6-2-u2-X07','K6-2-u2-X02']::text[],false,'{"seq":9,"concept":"K6-2-u2-C5","difficulty":2,"kind":"mc","stem":"진다해 선생님의 답 「무엇을 찾다가 못 찾았는지 여쭈어 공책에 적어 두지요.」를 듣고 할 수 있는 후속 질문은 어느 것인가요?","options":[{"t":"「공책에 적어 두신 것은 책을 고를 때 어떻게 쓰이나요?」","correct":true},{"t":"「다음 질문입니다. 책방 이름은 누가 지었나요?」","mis":"K6-2-u2-X06"},{"t":"「점심은 어디서 드시나요?」","mis":"K6-2-u2-X07"},{"t":"「우리나라 사람들은 한 해에 책을 몇 권 읽나요?」","mis":"K6-2-u2-X02"}],"explanation":["앞선 답의 「공책에 적어 두지요」를 붙들었어요.","더 자세히 알려고 이어서 물었어요.","답을 듣지 않았다면 만들 수 없는 질문이에요."],"asset":{"type":"speech","turns":[{"who":"소미","text":"책방에서 하루에 가장 많이 하시는 일은 무엇인가요?"},{"who":"진다해","text":"책을 고르는 일이에요. 들어오는 책을 다 놓을 수는 없어서, 우리 동네 사람들이 읽을 만한 책을 골라 놓아요."},{"who":"예준","text":"방금 「우리 동네 사람들이 읽을 만한 책」이라고 하셨는데, 그건 어떻게 아시나요?"},{"who":"진다해","text":"손님이 책을 고르다 내려놓는 모습을 봐요. 무엇을 찾다가 못 찾았는지 여쭈어 공책에 적어 두지요."},{"who":"소미","text":"책방을 하시며 가장 보람 있었던 때는 언제인가요?"},{"who":"진다해","text":"어릴 때 오던 손님이 커서 자기 아이 손을 잡고 왔을 때요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_b#10','kor',6,2,'u2','','g6_2_kor_u2_review_b','unit_review','K6-2-u2-C3',2,'mc','auto','다온과 예준이 면담 열기에서 한 일을 바르게 모은 것은 어느 것인가요?',ARRAY['K6-2-u2-X05','K6-2-u2-X06','K6-2-u2-X04']::text[],false,'{"seq":10,"concept":"K6-2-u2-C3","difficulty":2,"kind":"mc","stem":"다온과 예준이 면담 열기에서 한 일을 바르게 모은 것은 어느 것인가요?","options":[{"t":"인사와 감사 · 면담 목적 밝히기 · 녹음 동의 구하기","correct":true},{"t":"인사와 감사 · 알게 된 것 확인하기 · 보고서 쓰기","mis":"K6-2-u2-X05"},{"t":"녹음 동의 구하기 · 질문 열 개 읽기 · 헤어지기","mis":"K6-2-u2-X06"},{"t":"목적 밝히기 · 선생님 나이 여쭙기 · 사는 곳 여쭙기","mis":"K6-2-u2-X04"}],"explanation":["다온이 인사와 감사를 드렸어요.","예준이 목적을 밝히고 다온이 녹음 동의를 구했어요.","면담 열기의 세 가지를 모두 갖추었어요."],"asset":{"type":"speech","turns":[{"who":"다온","text":"안녕하세요? 바쁘신데 시간 내어 주셔서 감사합니다. 저희는 6학년 아침별 모둠입니다."},{"who":"예준","text":"오늘은 동네 책방을 꾸려 가는 일과 그 일의 보람을 여쭙고자 합니다."},{"who":"다온","text":"말씀을 정확히 남기려고 녹음하고 싶은데 괜찮으실까요?"},{"who":"진다해","text":"네, 괜찮아요. 다만 모둠 과제에만 써 주세요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_b#11','kor',6,2,'u2','','g6_2_kor_u2_review_b','unit_review','K6-2-u2-C7',2,'mc','auto','진다해 선생님이 멀리 이사 가셔서 직접 뵙기 어렵다면 알맞은 면담 방식은 어느 것인가요?',ARRAY['K6-2-u2-X03','K6-2-u2-X02','K6-2-u2-X11']::text[],false,'{"seq":11,"concept":"K6-2-u2-C7","difficulty":2,"kind":"mc","stem":"진다해 선생님이 멀리 이사 가셔서 직접 뵙기 어렵다면 알맞은 면담 방식은 어느 것인가요?","options":[{"t":"영상 통화로 하는 비대면 면담","correct":true},{"t":"허락 없이 책방 앞에서 기다리는 대면 면담","mis":"K6-2-u2-X03"},{"t":"면담을 하지 않고 누리집 글만 옮기기","mis":"K6-2-u2-X02"},{"t":"전화를 걸어 바로 녹음부터 하기","mis":"K6-2-u2-X11"}],"explanation":["대면이 어려우면 비대면으로 정해요.","영상 통화나 전자 우편으로 할 수 있어요.","그분의 사정에 맞추어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_b#12','kor',6,2,'u2','','g6_2_kor_u2_review_b','unit_review','K6-2-u2-C4',2,'mc','auto','아침별 모둠이 미리 찾은 자료가 「동네 책방은 주인이 고른 책을 놓는다」였어요. 이 자료를 바탕으로 더 깊이 물은 질문은 어느 것인가요?',ARRAY['K6-2-u2-X02','K6-2-u2-X07']::text[],false,'{"seq":12,"concept":"K6-2-u2-C4","difficulty":2,"kind":"mc","stem":"아침별 모둠이 미리 찾은 자료가 「동네 책방은 주인이 고른 책을 놓는다」였어요. 이 자료를 바탕으로 더 깊이 물은 질문은 어느 것인가요?","options":[{"t":"「책을 고르실 때 어떤 기준으로 고르시나요?」","correct":true},{"t":"「책방은 무엇을 하는 곳인가요?」","mis":"K6-2-u2-X02"},{"t":"「책방에는 책이 있나요?」","mis":"K6-2-u2-X02"},{"t":"「책방은 몇 시에 문을 닫나요?」","mis":"K6-2-u2-X07"}],"explanation":["찾아 둔 자료로 「주인이 고른다」는 것을 알았어요.","그래서 「무슨 일 하세요?」 대신 고르는 기준을 물었어요.","자료를 찾으면 한 걸음 더 깊이 물을 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_b#13','kor',6,2,'u2','','g6_2_kor_u2_review_b','unit_review','K6-2-u2-C8',2,'mc','auto','면담 내용을 간추리다가 「책을 다 놓을 수는 없어서」를 「책을 다 놓는다」로 적었다면 무엇이 잘못되었나요?',ARRAY['K6-2-u2-X13']::text[],false,'{"seq":13,"concept":"K6-2-u2-C8","difficulty":2,"kind":"mc","stem":"면담 내용을 간추리다가 「책을 다 놓을 수는 없어서」를 「책을 다 놓는다」로 적었다면 무엇이 잘못되었나요?","options":[{"t":"줄인 것이 아니라 답변의 뜻을 바꾸었다","correct":true},{"t":"너무 짧게 줄였다","mis":"K6-2-u2-X13"},{"t":"중요하지 않은 것을 덜어 냈다","mis":"K6-2-u2-X13"},{"t":"내 말로 다시 세웠다","mis":"K6-2-u2-X13"}],"explanation":["줄이는 것과 바꾸는 것은 달라요.","「다 놓을 수는 없어서」와 「다 놓는다」는 뜻이 반대예요.","간추려도 뜻은 그대로여야 해요."],"asset":{"type":"speech","turns":[{"who":"소미","text":"책방에서 하루에 가장 많이 하시는 일은 무엇인가요?"},{"who":"진다해","text":"책을 고르는 일이에요. 들어오는 책을 다 놓을 수는 없어서, 우리 동네 사람들이 읽을 만한 책을 골라 놓아요."},{"who":"예준","text":"방금 「우리 동네 사람들이 읽을 만한 책」이라고 하셨는데, 그건 어떻게 아시나요?"},{"who":"진다해","text":"손님이 책을 고르다 내려놓는 모습을 봐요. 무엇을 찾다가 못 찾았는지 여쭈어 공책에 적어 두지요."},{"who":"소미","text":"책방을 하시며 가장 보람 있었던 때는 언제인가요?"},{"who":"진다해","text":"어릴 때 오던 손님이 커서 자기 아이 손을 잡고 왔을 때요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_b#14','kor',6,2,'u2','','g6_2_kor_u2_review_b','unit_review','K6-2-u2-C10',2,'mc','auto','태건에게 하는 질문 가운데 바람직한 질문은 어느 것인가요?',ARRAY['K6-2-u2-X17']::text[],false,'{"seq":14,"concept":"K6-2-u2-C10","difficulty":2,"kind":"mc","stem":"태건에게 하는 질문 가운데 바람직한 질문은 어느 것인가요?","options":[{"t":"「쌓은 돌이 흩어졌을 때 어떤 마음이 드셨나요?」","correct":true},{"t":"「돌이 흩어진 건 쌓는 방법이 엉터리라서죠?」","mis":"K6-2-u2-X17"},{"t":"「주저앉은 거 창피하지 않았어요?」","mis":"K6-2-u2-X17"},{"t":"「아무도 안 도와준 건 친구가 없어서예요?」","mis":"K6-2-u2-X17"}],"explanation":["바람직한 질문은 마음을 헤아려요.","모자란 곳을 파고들지 않아요.","답할 사람이 고를 여지를 남겨요."],"asset":{"type":"passage","lines":["지난여름 큰비가 사흘 동안 내려 징검돌이 떠내려갔다.","할머니는 아랫마을 큰길로 한 시간을 돌아 밭에 다녔다.","어느 날 아침 태건은 혼자 떠내려간 돌을 굴려 올렸다.","돌 하나에 한나절. 거드는 사람도 말리는 사람도 없었다.","사흘째 되던 날 다시 비가 왔고, 이튿날 쌓은 돌이 흩어졌다.","태건은 젖은 모래밭에 주저앉았다.","그때 상우 아저씨가 지게를 지고 왔다. 「나도 좀 하자.」","그다음 날 아침 냇가에 어른 여섯이 나와 다리를 다시 놓았다."],"title":"「사흘 걸린 다리」 간추린 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_b#15','kor',6,2,'u2','','g6_2_kor_u2_review_b','unit_review','K6-2-u2-C2',2,'mc','auto','아침별 모둠이 진다해 선생님께 면담을 부탁드리는 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u2-X03','K6-2-u2-X04']::text[],false,'{"seq":15,"concept":"K6-2-u2-C2","difficulty":2,"kind":"mc","stem":"아침별 모둠이 진다해 선생님께 면담을 부탁드리는 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「저희는 6학년 아침별 모둠입니다. 책방을 꾸리는 일을 여쭙고 싶은데, 삼십 분쯤 다음 주에 괜찮으신 때가 있을까요?」","correct":true},{"t":"「내일 세 시에 갈게요. 그때 몇 가지 물어볼게요.」","mis":"K6-2-u2-X03"},{"t":"「뭐 좀 물어보려고요. 아무 때나 알아서 말씀해 주세요.」","mis":"K6-2-u2-X03"},{"t":"「선생님 나이랑 사시는 곳도 여쭤봐도 되죠?」","mis":"K6-2-u2-X04"}],"explanation":["누구·목적·시간·날짜를 밝혀요.","정해서 알리지 않고 여쭈어 맞추어요.","개인 정보는 묻지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_b#16','kor',6,2,'u2','','g6_2_kor_u2_review_b','unit_review','K6-2-u2-C8',2,'mc','auto','면담의 전 과정을 살피고 시간을 조절하는 역할은 어느 것인가요?',ARRAY['K6-2-u2-X19']::text[],false,'{"seq":16,"concept":"K6-2-u2-C8","difficulty":2,"kind":"mc","stem":"면담의 전 과정을 살피고 시간을 조절하는 역할은 어느 것인가요?","options":[{"t":"진행 담당","correct":true},{"t":"매체 담당","mis":"K6-2-u2-X19"},{"t":"약속 담당","mis":"K6-2-u2-X19"},{"t":"정리 담당","mis":"K6-2-u2-X19"}],"explanation":["진행 담당은 면담 전체의 흐름을 맡아요.","시간이 모자라거나 넘치지 않게 조절해요.","기기는 매체 담당이 맡아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_b#17','kor',6,2,'u2','','g6_2_kor_u2_review_b','unit_review','K6-2-u2-C6',3,'error','auto','면담 예절을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u2-X10']::text[],false,'{"seq":17,"concept":"K6-2-u2-C6","difficulty":3,"kind":"error","stem":"면담 예절을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"세아 — 「설명을 길게 붙여 물어야 상대가 잘 알아들어.」","correct":true,"mis_target":"K6-2-u2-X10"},{"t":"민호 — 「질문은 짧고 분명하게 해.」","mis":"K6-2-u2-X10"},{"t":"지안 — 「말씀 도중에는 끊지 말고 메모해 둬.」","mis":"K6-2-u2-X10"}],"explanation":["설명이 길면 무엇을 묻는지 흐려져요.","질문은 짧게 해요.","민호와 지안은 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_b#18','kor',6,2,'u2','','g6_2_kor_u2_review_b','unit_review','K6-2-u2-C10',3,'mc','auto','상우 아저씨에게 「왜 지게를 지고 오셨나요?」라고 물었을 때 작품에 근거한 답으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u2-X16']::text[],false,'{"seq":18,"concept":"K6-2-u2-C10","difficulty":3,"kind":"mc","stem":"상우 아저씨에게 「왜 지게를 지고 오셨나요?」라고 물었을 때 작품에 근거한 답으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「혼자 돌을 옮기던 태건이 주저앉은 것을 보고 함께하려고 왔어요.」","correct":true},{"t":"「나라에서 다리를 놓으라고 시켜서 왔어요.」","mis":"K6-2-u2-X16"},{"t":"「제 밭에 가는 길이 막혀서 화가 나서 왔어요.」","mis":"K6-2-u2-X16"},{"t":"「돈을 받기로 해서 왔어요.」","mis":"K6-2-u2-X16"}],"explanation":["태건이 주저앉은 「그때」 아저씨가 왔어요.","「나도 좀 하자.」에 함께하려는 마음이 보여요.","나라·돈은 이야기에 없어요."],"asset":{"type":"passage","lines":["지난여름 큰비가 사흘 동안 내려 징검돌이 떠내려갔다.","할머니는 아랫마을 큰길로 한 시간을 돌아 밭에 다녔다.","어느 날 아침 태건은 혼자 떠내려간 돌을 굴려 올렸다.","돌 하나에 한나절. 거드는 사람도 말리는 사람도 없었다.","사흘째 되던 날 다시 비가 왔고, 이튿날 쌓은 돌이 흩어졌다.","태건은 젖은 모래밭에 주저앉았다.","그때 상우 아저씨가 지게를 지고 왔다. 「나도 좀 하자.」","그다음 날 아침 냇가에 어른 여섯이 나와 다리를 다시 놓았다."],"title":"「사흘 걸린 다리」 간추린 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_b#19','kor',6,2,'u2','','g6_2_kor_u2_review_b','unit_review','K6-2-u2-C9',3,'mc','auto','아침별 모둠의 성찰 가운데 「더 알고 싶은 점」으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u2-X14']::text[],false,'{"seq":19,"concept":"K6-2-u2-C9","difficulty":3,"kind":"mc","stem":"아침별 모둠의 성찰 가운데 「더 알고 싶은 점」으로 알맞은 것은 어느 것인가요?","options":[{"t":"공책에 적은 못 찾은 책을 실제로 들여놓으시는지 궁금해졌다","correct":true},{"t":"녹음 허락을 먼저 받았다","mis":"K6-2-u2-X14"},{"t":"감사 인사를 서둘러 드렸다","mis":"K6-2-u2-X14"},{"t":"예준이 질문을 너무 많이 했다","mis":"K6-2-u2-X14"}],"explanation":["더 알고 싶은 점은 답을 듣고 새로 생긴 궁금함이에요.","허락은 잘한 점, 서두른 인사는 보완할 점이에요.","사람을 가리키는 말은 성찰이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_b#20','kor',6,2,'u2','','g6_2_kor_u2_review_b','unit_review','K6-2-u2-C6',3,'mc','auto','「손님 줄면 망하는 거 아니에요?」를 점검해 바르게 고친 것은 어느 것인가요?',ARRAY['K6-2-u2-X17','K6-2-u2-X04']::text[],false,'{"seq":20,"concept":"K6-2-u2-C6","difficulty":3,"kind":"mc","stem":"「손님 줄면 망하는 거 아니에요?」를 점검해 바르게 고친 것은 어느 것인가요?","options":[{"t":"「손님이 줄었을 때는 어떻게 하시나요?」","correct":true},{"t":"「손님 줄면 망하시는 거 아니에요?」","mis":"K6-2-u2-X17"},{"t":"「망하면 어떡하실 거예요? 꼭 말해 주세요.」","mis":"K6-2-u2-X17"},{"t":"「손님은 하루에 몇 명이에요? 돈은요?」","mis":"K6-2-u2-X04"}],"explanation":["「망하는」은 깎아내리는 말이에요.","예의를 갖추고 목적에 맞게 고쳐요.","어떻게 하시는지 여쭈면 그분의 일을 들을 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_b#21','kor',6,2,'u2','','g6_2_kor_u2_review_b','unit_review','K6-2-u2-C3',3,'mc','auto','아침별 모둠의 준비 과정을 차례대로 바르게 늘어놓은 것은 어느 것인가요?',ARRAY['K6-2-u2-X05']::text[],false,'{"seq":21,"concept":"K6-2-u2-C3","difficulty":3,"kind":"mc","stem":"아침별 모둠의 준비 과정을 차례대로 바르게 늘어놓은 것은 어느 것인가요?","options":[{"t":"목적 정하기 → 대상자 정하기 → 자료 찾기 → 질문 만들기 → 요청하고 허락 구하기","correct":true},{"t":"질문 만들기 → 목적 정하기 → 자료 찾기 → 대상자 정하기 → 요청하기","mis":"K6-2-u2-X05"},{"t":"요청하기 → 목적 정하기 → 질문 만들기 → 대상자 정하기 → 자료 찾기","mis":"K6-2-u2-X05"},{"t":"자료 찾기 → 요청하기 → 목적 정하기 → 대상자 정하기 → 질문 만들기","mis":"K6-2-u2-X05"}],"explanation":["목적이 맨 먼저예요.","대상자를 정하고 자료를 찾아 질문을 만들어요.","그다음 요청하고 허락을 구해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_b#22','kor',6,2,'u2','','g6_2_kor_u2_review_b','unit_review','K6-2-u2-C9',3,'mc','auto','아침별 모둠의 보고서 앞부분에 들어갈 문장으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u2-X15','K6-2-u2-X11']::text[],false,'{"seq":22,"concept":"K6-2-u2-C9","difficulty":3,"kind":"mc","stem":"아침별 모둠의 보고서 앞부분에 들어갈 문장으로 알맞은 것은 어느 것인가요?","options":[{"t":"우리 모둠은 동네 책방을 꾸리는 일이 궁금해, 책방 주인 진다해 선생님과 면담을 했습니다.","correct":true},{"t":"어릴 때 오던 손님이 아이와 왔을 때 보람을 느끼신다고 하셨습니다.","mis":"K6-2-u2-X15"},{"t":"다음에는 책을 살 때 주인이 고른 까닭을 생각해 보려 합니다.","mis":"K6-2-u2-X15"},{"t":"녹음 파일은 반 누리집에서 들을 수 있습니다.","mis":"K6-2-u2-X11"}],"explanation":["앞부분은 왜·누구를·어떻게 준비했는지예요.","보람은 가운데, 다음 다짐은 뒷부분이에요.","녹음 파일은 나누지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_b#23','kor',6,2,'u2','','g6_2_kor_u2_review_b','unit_review','K6-2-u2-C5',4,'mc','auto','아침별 모둠이 「책을 고른다」는 답을 듣고 후속 질문을 하지 않고 바로 다음 질문으로 넘어갔다면 어떻게 되었을까요?',ARRAY['K6-2-u2-X06','K6-2-u2-X07','K6-2-u2-X11']::text[],false,'{"seq":23,"concept":"K6-2-u2-C5","difficulty":4,"kind":"mc","stem":"아침별 모둠이 「책을 고른다」는 답을 듣고 후속 질문을 하지 않고 바로 다음 질문으로 넘어갔다면 어떻게 되었을까요?","options":[{"t":"손님의 모습을 보고 못 찾은 책을 적어 둔다는 가장 중요한 답을 듣지 못했을 것이다","correct":true},{"t":"면담 시간이 짧아져 더 좋은 면담이 되었을 것이다","mis":"K6-2-u2-X06"},{"t":"목적에서 벗어난 이야기로 흘러갔을 것이다","mis":"K6-2-u2-X07"},{"t":"녹음 허락을 받지 못했을 것이다","mis":"K6-2-u2-X11"}],"explanation":["후속 질문은 질문지에 없는 물음이에요.","예준의 후속 질문 덕분에 중요한 답이 나왔어요.","답을 끝까지 듣고 이어서 묻는 것이 면담의 깊이를 정해요."],"asset":{"type":"speech","turns":[{"who":"소미","text":"책방에서 하루에 가장 많이 하시는 일은 무엇인가요?"},{"who":"진다해","text":"책을 고르는 일이에요. 들어오는 책을 다 놓을 수는 없어서, 우리 동네 사람들이 읽을 만한 책을 골라 놓아요."},{"who":"예준","text":"방금 「우리 동네 사람들이 읽을 만한 책」이라고 하셨는데, 그건 어떻게 아시나요?"},{"who":"진다해","text":"손님이 책을 고르다 내려놓는 모습을 봐요. 무엇을 찾다가 못 찾았는지 여쭈어 공책에 적어 두지요."},{"who":"소미","text":"책방을 하시며 가장 보람 있었던 때는 언제인가요?"},{"who":"진다해","text":"어릴 때 오던 손님이 커서 자기 아이 손을 잡고 왔을 때요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_b#24','kor',6,2,'u2','','g6_2_kor_u2_review_b','unit_review','K6-2-u2-C9',4,'essay','teacher','「책방을 꾸리는 사람」 면담을 바탕으로 아침별 모둠의 면담 보고서 가운데 부분을 쓰세요. 새롭게 안 사실을 「첫째·둘째」로 나누어 답변 중심으로 쓰되 답변의 뜻을 바꾸지 마세요.','{}'::text[],false,'{"seq":24,"concept":"K6-2-u2-C9","difficulty":4,"kind":"essay","stem":"「책방을 꾸리는 사람」 면담을 바탕으로 아침별 모둠의 면담 보고서 가운데 부분을 쓰세요. 새롭게 안 사실을 「첫째·둘째」로 나누어 답변 중심으로 쓰되 답변의 뜻을 바꾸지 마세요.","answer_guide":{"answer":"예: 면담으로 새롭게 알게 된 것은 두 가지입니다. 첫째, 책방에서 하루에 가장 많이 하시는 일은 책을 고르는 일입니다. 들어오는 책을 다 놓을 수는 없어서, 손님이 책을 고르다 내려놓는 모습을 보고 못 찾은 책을 여쭈어 공책에 적어 두었다가 동네 사람들이 읽을 만한 책을 고른다고 하셨습니다. 둘째, 가장 보람 있었던 때는 어릴 때 오던 손님이 커서 자기 아이 손을 잡고 왔을 때라고 하셨습니다.","scoring_points":["새롭게 안 사실을 첫째·둘째로 나누어 썼는가","면담 답변을 중심으로 간추려 썼는가","답변의 뜻을 바꾸지 않았는가"]},"explanation":["가운데 부분은 새롭게 안 사실이에요.","갈래로 나누면 한눈에 들어와요.","줄이되 뜻은 바꾸지 않아요."],"asset":{"type":"speech","turns":[{"who":"소미","text":"책방에서 하루에 가장 많이 하시는 일은 무엇인가요?"},{"who":"진다해","text":"책을 고르는 일이에요. 들어오는 책을 다 놓을 수는 없어서, 우리 동네 사람들이 읽을 만한 책을 골라 놓아요."},{"who":"예준","text":"방금 「우리 동네 사람들이 읽을 만한 책」이라고 하셨는데, 그건 어떻게 아시나요?"},{"who":"진다해","text":"손님이 책을 고르다 내려놓는 모습을 봐요. 무엇을 찾다가 못 찾았는지 여쭈어 공책에 적어 두지요."},{"who":"소미","text":"책방을 하시며 가장 보람 있었던 때는 언제인가요?"},{"who":"진다해","text":"어릴 때 오던 손님이 커서 자기 아이 손을 잡고 왔을 때요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_b#25','kor',6,2,'u2','','g6_2_kor_u2_review_b','unit_review','K6-2-u2-C8',4,'essay','teacher','「책방을 꾸리는 사람」 질문하기 부분을 두 문장으로 간추리고, 간추리면서 덜어 낸 것과 고른 것을 각각 하나씩 밝히세요.','{}'::text[],false,'{"seq":25,"concept":"K6-2-u2-C8","difficulty":4,"kind":"essay","stem":"「책방을 꾸리는 사람」 질문하기 부분을 두 문장으로 간추리고, 간추리면서 덜어 낸 것과 고른 것을 각각 하나씩 밝히세요.","answer_guide":{"answer":"예: 책방 주인은 들어오는 책을 다 놓을 수 없어서, 손님이 내려놓는 모습과 못 찾은 책을 적어 둔 것을 보고 동네 사람들이 읽을 만한 책을 고른다. 가장 보람 있었던 때는 어릴 때 오던 손님이 커서 자기 아이와 왔을 때이다. 누가 어떤 차례로 물었는지는 덜어 냈고(삭제), 여러 답 가운데 책을 고르는 방법과 보람을 골랐다(선택).","scoring_points":["두 문장으로 중요한 내용을 간추렸는가","답변의 뜻을 바꾸지 않았는가","덜어 낸 것과 고른 것을 바르게 밝혔는가"]},"explanation":["중요한 것을 골라요.","덜 중요한 것은 덜어 내요.","뜻은 그대로 내 말로 써요."],"asset":{"type":"speech","turns":[{"who":"소미","text":"책방에서 하루에 가장 많이 하시는 일은 무엇인가요?"},{"who":"진다해","text":"책을 고르는 일이에요. 들어오는 책을 다 놓을 수는 없어서, 우리 동네 사람들이 읽을 만한 책을 골라 놓아요."},{"who":"예준","text":"방금 「우리 동네 사람들이 읽을 만한 책」이라고 하셨는데, 그건 어떻게 아시나요?"},{"who":"진다해","text":"손님이 책을 고르다 내려놓는 모습을 봐요. 무엇을 찾다가 못 찾았는지 여쭈어 공책에 적어 두지요."},{"who":"소미","text":"책방을 하시며 가장 보람 있었던 때는 언제인가요?"},{"who":"진다해","text":"어릴 때 오던 손님이 커서 자기 아이 손을 잡고 왔을 때요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_c#1','kor',6,2,'u2','','g6_2_kor_u2_review_c','unit_review','K6-2-u2-C1',1,'ox','auto','면담에서는 면담하는 사람이 답하는 사람보다 훨씬 많이 말해야 해요.',ARRAY['K6-2-u2-X01']::text[],false,'{"seq":1,"concept":"K6-2-u2-C1","difficulty":1,"kind":"ox","stem":"면담에서는 면담하는 사람이 답하는 사람보다 훨씬 많이 말해야 해요.","answer":"X","reason_options":[{"t":"답하는 쪽이 훨씬 많이 말하고 면담자는 잘 묻고 잘 듣는 사람이기 때문에","correct":true},{"t":"묻는 사람이 많이 말해야 면담을 이끌 수 있기 때문에","mis":"K6-2-u2-X01"}],"mis":"K6-2-u2-X01","explanation":["일상 대화는 주고받는 양이 비슷해요.","면담은 답하는 쪽이 훨씬 많이 말해요.","면담자는 잘 묻고 잘 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_c#2','kor',6,2,'u2','','g6_2_kor_u2_review_c','unit_review','K6-2-u2-C2',1,'ox','auto','면담을 부탁드릴 때 「아무 때나 괜찮으니까 알아서 말씀해 주세요.」라고만 하면 충분해요.',ARRAY['K6-2-u2-X03']::text[],false,'{"seq":2,"concept":"K6-2-u2-C2","difficulty":1,"kind":"ox","stem":"면담을 부탁드릴 때 「아무 때나 괜찮으니까 알아서 말씀해 주세요.」라고만 하면 충분해요.","answer":"X","reason_options":[{"t":"누구인지·목적·걸리는 시간·바라는 날짜를 함께 밝혀야 상대가 정할 수 있기 때문에","correct":true},{"t":"날짜를 상대가 정하게 했으니 예의를 다 갖춘 것이기 때문에","mis":"K6-2-u2-X03"}],"mis":"K6-2-u2-X03","explanation":["무엇을 물을지, 얼마나 걸릴지 모르면 정하기 어려워요.","누구 · 왜 · 얼마나 · 언제를 넣어요.","그다음 상대의 사정에 맞추어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_c#3','kor',6,2,'u2','','g6_2_kor_u2_review_c','unit_review','K6-2-u2-C3',1,'ox','auto','면담 준비하기에서는 목적을 정한 뒤에 대상자를 정해요.',ARRAY['K6-2-u2-X05']::text[],false,'{"seq":3,"concept":"K6-2-u2-C3","difficulty":1,"kind":"ox","stem":"면담 준비하기에서는 목적을 정한 뒤에 대상자를 정해요.","answer":"O","reason_options":[{"t":"무엇을 알고 싶은지가 정해져야 누구를 만날지 정할 수 있기 때문에","correct":true},{"t":"대상자를 먼저 정해야 목적을 아무렇게나 정할 수 있기 때문에","mis":"K6-2-u2-X05"}],"mis":"K6-2-u2-X05","explanation":["목적이 맨 먼저예요.","목적에 맞는 분을 대상자로 정해요.","그다음 방식·자료·질문·역할·요청이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_c#4','kor',6,2,'u2','','g6_2_kor_u2_review_c','unit_review','K6-2-u2-C4',1,'mc','auto','소미의 질문 「책방을 하시며 가장 보람 있었던 때는 언제인가요?」는 어느 갈래인가요?',ARRAY['K6-2-u2-X08','K6-2-u2-X05']::text[],false,'{"seq":4,"concept":"K6-2-u2-C4","difficulty":1,"kind":"mc","stem":"소미의 질문 「책방을 하시며 가장 보람 있었던 때는 언제인가요?」는 어느 갈래인가요?","options":[{"t":"생각이나 느낌에 대한 질문","correct":true},{"t":"구체적인 사실에 대한 질문","mis":"K6-2-u2-X08"},{"t":"앞으로의 계획이나 당부에 대한 질문","mis":"K6-2-u2-X08"},{"t":"면담을 여는 인사","mis":"K6-2-u2-X05"}],"explanation":["보람은 그 일을 하며 느낀 마음이에요.","생각이나 느낌에 대한 질문이에요.","그분의 마음까지 들을 수 있어요."],"asset":{"type":"speech","turns":[{"who":"소미","text":"책방에서 하루에 가장 많이 하시는 일은 무엇인가요?"},{"who":"진다해","text":"책을 고르는 일이에요. 들어오는 책을 다 놓을 수는 없어서, 우리 동네 사람들이 읽을 만한 책을 골라 놓아요."},{"who":"예준","text":"방금 「우리 동네 사람들이 읽을 만한 책」이라고 하셨는데, 그건 어떻게 아시나요?"},{"who":"진다해","text":"손님이 책을 고르다 내려놓는 모습을 봐요. 무엇을 찾다가 못 찾았는지 여쭈어 공책에 적어 두지요."},{"who":"소미","text":"책방을 하시며 가장 보람 있었던 때는 언제인가요?"},{"who":"진다해","text":"어릴 때 오던 손님이 커서 자기 아이 손을 잡고 왔을 때요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_c#5','kor',6,2,'u2','','g6_2_kor_u2_review_c','unit_review','K6-2-u2-C6',1,'mc','auto','면담 열기에서 다온이 한 말 「바쁘신데 시간 내어 주셔서 감사합니다.」에 담긴 예의는 어느 것인가요?',ARRAY['K6-2-u2-X05','K6-2-u2-X11']::text[],false,'{"seq":5,"concept":"K6-2-u2-C6","difficulty":1,"kind":"mc","stem":"면담 열기에서 다온이 한 말 「바쁘신데 시간 내어 주셔서 감사합니다.」에 담긴 예의는 어느 것인가요?","options":[{"t":"시간을 내어 주신 데 감사하기","correct":true},{"t":"면담 목적 밝히기","mis":"K6-2-u2-X05"},{"t":"담기 전에 동의 구하기","mis":"K6-2-u2-X11"},{"t":"알게 된 것 확인하기","mis":"K6-2-u2-X05"}],"explanation":["면담 열기에는 인사·감사·목적·동의가 들어가요.","다온은 시간을 내어 주신 데 감사드렸어요.","목적은 예준이 밝혔어요."],"asset":{"type":"speech","turns":[{"who":"다온","text":"안녕하세요? 바쁘신데 시간 내어 주셔서 감사합니다. 저희는 6학년 아침별 모둠입니다."},{"who":"예준","text":"오늘은 동네 책방을 꾸려 가는 일과 그 일의 보람을 여쭙고자 합니다."},{"who":"다온","text":"말씀을 정확히 남기려고 녹음하고 싶은데 괜찮으실까요?"},{"who":"진다해","text":"네, 괜찮아요. 다만 모둠 과제에만 써 주세요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_c#6','kor',6,2,'u2','','g6_2_kor_u2_review_c','unit_review','K6-2-u2-C7',1,'ox','auto','담아 둔 면담 녹음은 친구들이 궁금해하면 나누어 주어도 돼요.',ARRAY['K6-2-u2-X11']::text[],false,'{"seq":6,"concept":"K6-2-u2-C7","difficulty":1,"kind":"ox","stem":"담아 둔 면담 녹음은 친구들이 궁금해하면 나누어 주어도 돼요.","answer":"X","reason_options":[{"t":"담아 둔 것은 보고서를 쓸 때만 쓰고 밖으로 내보내지 않기 때문에","correct":true},{"t":"친구들도 면담 내용을 알면 좋기 때문에","mis":"K6-2-u2-X11"}],"mis":"K6-2-u2-X11","explanation":["담아 둔 자료는 빌려 온 것이에요.","그분의 허락 안에서만 써요.","친구들과는 간추린 보고서를 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_c#7','kor',6,2,'u2','','g6_2_kor_u2_review_c','unit_review','K6-2-u2-C9',1,'ox','auto','면담 과정을 되돌아볼 때는 막연한 기분보다 절차마다 무엇을 했는지 짚어 봐요.',ARRAY['K6-2-u2-X14']::text[],false,'{"seq":7,"concept":"K6-2-u2-C9","difficulty":1,"kind":"ox","stem":"면담 과정을 되돌아볼 때는 막연한 기분보다 절차마다 무엇을 했는지 짚어 봐요.","answer":"O","reason_options":[{"t":"절차마다 한 일을 짚어야 잘한 점과 보완할 점이 드러나기 때문에","correct":true},{"t":"기분이 좋았으면 잘한 면담이기 때문에","mis":"K6-2-u2-X14"}],"mis":"K6-2-u2-X14","explanation":["「좋았다」, 「별로였다」로는 다음에 할 일이 남지 않아요.","준비·진행·정리마다 짚어요.","그래야 보완할 점이 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_c#8','kor',6,2,'u2','','g6_2_kor_u2_review_c','unit_review','K6-2-u2-C11',1,'mc','auto','「짧다」는 어떻게 소리 나나요?',ARRAY['K6-2-u2-X18']::text[],false,'{"seq":8,"concept":"K6-2-u2-C11","difficulty":1,"kind":"mc","stem":"「짧다」는 어떻게 소리 나나요?","options":[{"t":"[짤따]","correct":true},{"t":"[짭따]","mis":"K6-2-u2-X18"},{"t":"[짤바]","mis":"K6-2-u2-X18"},{"t":"[짜따]","mis":"K6-2-u2-X18"}],"explanation":["낱말 하나로 있을 때는 하나만 소리 나요.","「짧다」는 ㄹ이 소리 나요.","그래서 [짤따]예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_c#9','kor',6,2,'u2','','g6_2_kor_u2_review_c','unit_review','K6-2-u2-C5',2,'ox','auto','예준의 「그건 어떻게 아시나요?」는 질문지에 미리 적어 간 질문이에요.',ARRAY['K6-2-u2-X06']::text[],false,'{"seq":9,"concept":"K6-2-u2-C5","difficulty":2,"kind":"ox","stem":"예준의 「그건 어떻게 아시나요?」는 질문지에 미리 적어 간 질문이에요.","answer":"X","reason_options":[{"t":"앞선 답에 나온 「우리 동네 사람들이 읽을 만한 책」을 듣고 이어서 물은 후속 질문이기 때문에","correct":true},{"t":"「어떻게」로 묻는 질문은 모두 미리 준비하는 질문이기 때문에","mis":"K6-2-u2-X06"}],"mis":"K6-2-u2-X06","explanation":["예준은 답을 끝까지 들었어요.","그 안의 말을 붙들어 이어서 물었어요.","후속 질문은 듣고 있어야만 나와요."],"asset":{"type":"speech","turns":[{"who":"소미","text":"책방에서 하루에 가장 많이 하시는 일은 무엇인가요?"},{"who":"진다해","text":"책을 고르는 일이에요. 들어오는 책을 다 놓을 수는 없어서, 우리 동네 사람들이 읽을 만한 책을 골라 놓아요."},{"who":"예준","text":"방금 「우리 동네 사람들이 읽을 만한 책」이라고 하셨는데, 그건 어떻게 아시나요?"},{"who":"진다해","text":"손님이 책을 고르다 내려놓는 모습을 봐요. 무엇을 찾다가 못 찾았는지 여쭈어 공책에 적어 두지요."},{"who":"소미","text":"책방을 하시며 가장 보람 있었던 때는 언제인가요?"},{"who":"진다해","text":"어릴 때 오던 손님이 커서 자기 아이 손을 잡고 왔을 때요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_c#10','kor',6,2,'u2','','g6_2_kor_u2_review_c','unit_review','K6-2-u2-C3',2,'mc','auto','다온이 마무리에서 「책을 고르는 일이 손님의 모습을 오래 보는 일이라는 말씀이 기억에 남습니다.」라고 한 까닭은 어느 것인가요?',ARRAY['K6-2-u2-X05']::text[],false,'{"seq":10,"concept":"K6-2-u2-C3","difficulty":2,"kind":"mc","stem":"다온이 마무리에서 「책을 고르는 일이 손님의 모습을 오래 보는 일이라는 말씀이 기억에 남습니다.」라고 한 까닭은 어느 것인가요?","options":[{"t":"면담 결과를 확인하려고","correct":true},{"t":"새로운 질문을 시작하려고","mis":"K6-2-u2-X05"},{"t":"녹음 동의를 구하려고","mis":"K6-2-u2-X05"},{"t":"면담 목적을 처음 밝히려고","mis":"K6-2-u2-X05"}],"explanation":["마무리에서는 알게 된 것을 확인해요.","그다음 감사 인사를 드려요.","목적·동의는 면담 열기에서 해요."],"asset":{"type":"speech","turns":[{"who":"예준","text":"책방을 하고 싶은 학생에게 해 주실 말씀이 있나요?"},{"who":"진다해","text":"책을 많이 읽는 것만큼 사람 이야기를 많이 들어 보세요."},{"who":"다온","text":"책을 고르는 일이 손님의 모습을 오래 보는 일이라는 말씀이 기억에 남습니다. 보고서가 나오면 보여 드리겠습니다. 감사합니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_c#11','kor',6,2,'u2','','g6_2_kor_u2_review_c','unit_review','K6-2-u2-C7',2,'mc','auto','아침별 모둠이 면담을 정리할 때 매체를 쓰는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u2-X13','K6-2-u2-X12','K6-2-u2-X11']::text[],false,'{"seq":11,"concept":"K6-2-u2-C7","difficulty":2,"kind":"mc","stem":"아침별 모둠이 면담을 정리할 때 매체를 쓰는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"담아 둔 녹음을 다시 들으며 중요한 내용을 간추린다","correct":true},{"t":"녹음을 그대로 보고서에 붙인다","mis":"K6-2-u2-X13"},{"t":"누리집에서 책방 자료를 처음 찾는다","mis":"K6-2-u2-X12"},{"t":"녹음을 친구에게 보내 대신 정리하게 한다","mis":"K6-2-u2-X11"}],"explanation":["정리할 때는 담아 둔 것을 다시 들어요.","중요한 것을 골라 간추려요.","자료 찾기는 준비할 때 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_c#12','kor',6,2,'u2','','g6_2_kor_u2_review_c','unit_review','K6-2-u2-C4',2,'ox','auto','「책방 하시면 돈은 많이 버시나요?」는 아침별 모둠이 물어도 되는 질문이에요.',ARRAY['K6-2-u2-X04']::text[],false,'{"seq":12,"concept":"K6-2-u2-C4","difficulty":2,"kind":"ox","stem":"「책방 하시면 돈은 많이 버시나요?」는 아침별 모둠이 물어도 되는 질문이에요.","answer":"X","reason_options":[{"t":"버는 돈은 알리고 싶지 않을 수 있는 개인 정보이고 목적과 이어지지 않기 때문에","correct":true},{"t":"책방을 꾸리는 일과 관련 있는 질문이기 때문에","mis":"K6-2-u2-X04"}],"mis":"K6-2-u2-X04","explanation":["목적과 이어진 듯해도 개인 정보예요.","「이 질문을 내가 받으면 어떨까?」 되짚어 봐요.","보람이나 어려운 점을 묻는 것으로 바꿔요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_c#13','kor',6,2,'u2','','g6_2_kor_u2_review_c','unit_review','K6-2-u2-C8',2,'mc','auto','간추리기 방법 가운데 「잘게 나뉜 내용을 하나로 묶는 말로 바꾸기」는 어느 것인가요?',ARRAY['K6-2-u2-X13']::text[],false,'{"seq":13,"concept":"K6-2-u2-C8","difficulty":2,"kind":"mc","stem":"간추리기 방법 가운데 「잘게 나뉜 내용을 하나로 묶는 말로 바꾸기」는 어느 것인가요?","options":[{"t":"대체","correct":true},{"t":"삭제","mis":"K6-2-u2-X13"},{"t":"선택","mis":"K6-2-u2-X13"},{"t":"구성","mis":"K6-2-u2-X13"}],"explanation":["삭제는 덜어 내기, 선택은 고르기예요.","구성은 알아볼 수 있는 문장으로 새로 쓰기예요.","하나로 묶는 말로 바꾸는 것이 대체예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_c#14','kor',6,2,'u2','','g6_2_kor_u2_review_c','unit_review','K6-2-u2-C10',2,'ox','auto','「그런 것도 몰랐던 거예요?」는 상대의 마음을 헤아린 바람직한 질문이에요.',ARRAY['K6-2-u2-X17']::text[],false,'{"seq":14,"concept":"K6-2-u2-C10","difficulty":2,"kind":"ox","stem":"「그런 것도 몰랐던 거예요?」는 상대의 마음을 헤아린 바람직한 질문이에요.","answer":"X","reason_options":[{"t":"모자란 곳을 파고들어 깎아내리는 뜻이 드러나는 불쾌한 질문이기 때문에","correct":true},{"t":"궁금한 것을 솔직하게 물었기 때문에","mis":"K6-2-u2-X17"}],"mis":"K6-2-u2-X17","explanation":["「그런 것도」에 깎아내리는 뜻이 있어요.","상대가 불쾌해져 답이 깊어지지 않아요.","「그때는 어떻게 아셨나요?」처럼 고쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_c#15','kor',6,2,'u2','','g6_2_kor_u2_review_c','unit_review','K6-2-u2-C2',2,'mc','auto','면담 질문을 만든 뒤 「이 질문을 내가 받으면 어떨까」 되짚어 보는 까닭은 어느 것인가요?',ARRAY['K6-2-u2-X04','K6-2-u2-X08','K6-2-u2-X07']::text[],false,'{"seq":15,"concept":"K6-2-u2-C2","difficulty":2,"kind":"mc","stem":"면담 질문을 만든 뒤 「이 질문을 내가 받으면 어떨까」 되짚어 보는 까닭은 어느 것인가요?","options":[{"t":"상대가 알리고 싶지 않거나 답하기 곤란한 질문을 덜어 내려고","correct":true},{"t":"질문을 더 길게 늘이려고","mis":"K6-2-u2-X04"},{"t":"질문 수를 셋으로 맞추려고","mis":"K6-2-u2-X08"},{"t":"질문을 재미있게 바꾸려고","mis":"K6-2-u2-X07"}],"explanation":["궁금하다고 다 물어도 되는 것은 아니에요.","받는 사람 쪽에서 생각해 보아요.","불편한 질문은 덜어 내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_c#16','kor',6,2,'u2','','g6_2_kor_u2_review_c','unit_review','K6-2-u2-C8',2,'ox','auto','아침별 모둠에서 녹음 기기를 준비하고 허락을 받아 담는 일은 정리 담당이 맡아요.',ARRAY['K6-2-u2-X19']::text[],false,'{"seq":16,"concept":"K6-2-u2-C8","difficulty":2,"kind":"ox","stem":"아침별 모둠에서 녹음 기기를 준비하고 허락을 받아 담는 일은 정리 담당이 맡아요.","answer":"X","reason_options":[{"t":"기기를 준비하고 허락받아 담아 모둠과 나누는 것은 매체 담당이 하는 일이기 때문에","correct":true},{"t":"녹음한 것을 정리하니까 정리 담당이 맡기 때문에","mis":"K6-2-u2-X19"}],"mis":"K6-2-u2-X19","explanation":["매체 담당이 기기와 담기를 맡아요.","정리 담당은 메모와 보고서 자료를 맡아요.","역할이 나뉘어야 면담이 흘러가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_c#17','kor',6,2,'u2','','g6_2_kor_u2_review_c','unit_review','K6-2-u2-C5',3,'error','auto','좋은 면담을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u2-X07','K6-2-u2-X06']::text[],false,'{"seq":17,"concept":"K6-2-u2-C5","difficulty":3,"kind":"error","stem":"좋은 면담을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도담 — 「준비는 필요 없어. 가서 떠오르는 대로 물으면 돼.」","correct":true,"mis_target":"K6-2-u2-X07"},{"t":"이서 — 「준비한 질문으로 길을 잡아야 해.」","mis":"K6-2-u2-X07"},{"t":"윤호 — 「듣다가 생긴 물음으로 깊이 들어가야 해.」","mis":"K6-2-u2-X06"}],"explanation":["준비 없이 가면 목적에서 벗어난 이야기로 흘러가요.","준비한 질문으로 길을 잡고 후속 질문으로 깊이 들어가요.","이서와 윤호는 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_c#18','kor',6,2,'u2','','g6_2_kor_u2_review_c','unit_review','K6-2-u2-C10',3,'ox','auto','태건이 되어 「할머니가 시켜서 돌을 옮겼어요.」라고 답하는 것은 작품에 근거한 답이에요.',ARRAY['K6-2-u2-X16']::text[],false,'{"seq":18,"concept":"K6-2-u2-C10","difficulty":3,"kind":"ox","stem":"태건이 되어 「할머니가 시켜서 돌을 옮겼어요.」라고 답하는 것은 작품에 근거한 답이에요.","answer":"X","reason_options":[{"t":"이야기에는 태건이 「혼자」 돌을 굴려 올렸다고만 나오고 할머니가 시켰다는 말이 없기 때문에","correct":true},{"t":"할머니의 밭에 가는 길이니 할머니가 시켰을 것이기 때문에","mis":"K6-2-u2-X16"}],"mis":"K6-2-u2-X16","explanation":["이야기 안에서만 답해요.","「어느 날 아침 태건은 혼자」라고 나와요.","없는 내용을 짐작으로 지어내지 않아요."],"asset":{"type":"passage","lines":["지난여름 큰비가 사흘 동안 내려 징검돌이 떠내려갔다.","할머니는 아랫마을 큰길로 한 시간을 돌아 밭에 다녔다.","어느 날 아침 태건은 혼자 떠내려간 돌을 굴려 올렸다.","돌 하나에 한나절. 거드는 사람도 말리는 사람도 없었다.","사흘째 되던 날 다시 비가 왔고, 이튿날 쌓은 돌이 흩어졌다.","태건은 젖은 모래밭에 주저앉았다.","그때 상우 아저씨가 지게를 지고 왔다. 「나도 좀 하자.」","그다음 날 아침 냇가에 어른 여섯이 나와 다리를 다시 놓았다."],"title":"「사흘 걸린 다리」 간추린 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_c#19','kor',6,2,'u2','','g6_2_kor_u2_review_c','unit_review','K6-2-u2-C9',3,'mc','auto','「질문을 길게 해서 선생님이 다시 물으셨다.」를 다음 면담에서 실천할 점으로 바르게 바꾼 것은 어느 것인가요?',ARRAY['K6-2-u2-X14','K6-2-u2-X10']::text[],false,'{"seq":19,"concept":"K6-2-u2-C9","difficulty":3,"kind":"mc","stem":"「질문을 길게 해서 선생님이 다시 물으셨다.」를 다음 면담에서 실천할 점으로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"다음에는 질문을 하나씩 짧고 분명하게 하자","correct":true},{"t":"다음에는 질문을 길게 한 사람은 빠지자","mis":"K6-2-u2-X14"},{"t":"다음에는 열심히 하자","mis":"K6-2-u2-X14"},{"t":"다음에도 길게 묻되 더 빨리 말하자","mis":"K6-2-u2-X10"}],"explanation":["실천할 점은 다음에 할 행동이에요.","사람을 빼거나 막연하면 남지 않아요.","짧고 분명하게 묻는 것이 약속이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_c#20','kor',6,2,'u2','','g6_2_kor_u2_review_c','unit_review','K6-2-u2-C6',3,'ox','auto','질문을 점검할 때는 「목적에 맞는가 · 예의를 갖추었는가 · 뜻이 분명한가」를 살펴요.',ARRAY['K6-2-u2-X07']::text[],false,'{"seq":20,"concept":"K6-2-u2-C6","difficulty":3,"kind":"ox","stem":"질문을 점검할 때는 「목적에 맞는가 · 예의를 갖추었는가 · 뜻이 분명한가」를 살펴요.","answer":"O","reason_options":[{"t":"이 세 가지가 맞아야 상대가 편하게 알아듣고 목적에 맞는 답을 줄 수 있기 때문에","correct":true},{"t":"질문 개수가 열 개를 넘는지가 가장 중요하기 때문에","mis":"K6-2-u2-X07"}],"mis":"K6-2-u2-X07","explanation":["개수나 재미는 기준이 아니에요.","목적 · 예의 · 명료함을 봐요.","점검한 뒤 고쳐서 가져가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_c#21','kor',6,2,'u2','','g6_2_kor_u2_review_c','unit_review','K6-2-u2-C3',3,'match','auto','면담 절차와 그때 할 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":21,"concept":"K6-2-u2-C3","difficulty":3,"kind":"match","stem":"면담 절차와 그때 할 일을 알맞게 이으세요.","pairs":[{"l":"면담 준비하기","r":"목적에 알맞은 자료를 찾고 질문을 만들며 약속을 잡는다"},{"l":"면담 진행하기","r":"동의를 구하고 목적에 맞게 물으며 답변을 예의 바르게 듣는다"},{"l":"면담 정리하기","r":"담아 둔 것과 메모로 간추리고 과정을 성찰해 보고서를 쓴다"}],"mis":"K6-2-u2-X05","explanation":["만나기 전에는 준비해요.","만나는 동안에는 진행해요.","만난 뒤에는 정리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_c#22','kor',6,2,'u2','','g6_2_kor_u2_review_c','unit_review','K6-2-u2-C9',3,'mc','auto','아침별 모둠의 보고서 뒷부분을 가장 잘 쓴 것은 어느 것인가요?',ARRAY['K6-2-u2-X15','K6-2-u2-X14']::text[],false,'{"seq":22,"concept":"K6-2-u2-C9","difficulty":3,"kind":"mc","stem":"아침별 모둠의 보고서 뒷부분을 가장 잘 쓴 것은 어느 것인가요?","options":[{"t":"책을 고르는 일이 손님을 오래 보는 일이라는 말씀을 듣고, 앞으로는 책방에서 주인이 고른 까닭을 생각하며 책을 보기로 했다","correct":true},{"t":"아주 재미있었다. 또 가고 싶다.","mis":"K6-2-u2-X15"},{"t":"면담은 네 시에 시작해 네 시 반에 끝났다.","mis":"K6-2-u2-X15"},{"t":"소미가 질문을 잘 못해서 아쉬웠다.","mis":"K6-2-u2-X14"}],"explanation":["뒷부분은 무엇 때문에 무엇이 달라졌는지 써요.","느낌·시각만 적으면 남는 것이 적어요.","사람 탓은 보고서에 쓰지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_c#23','kor',6,2,'u2','','g6_2_kor_u2_review_c','unit_review','K6-2-u2-C7',4,'mc','auto','아침별 모둠이 매체를 고려하여 면담했다고 할 수 있는 근거를 바르게 모은 것은 어느 것인가요?',ARRAY['K6-2-u2-X11','K6-2-u2-X13','K6-2-u2-X12']::text[],false,'{"seq":23,"concept":"K6-2-u2-C7","difficulty":4,"kind":"mc","stem":"아침별 모둠이 매체를 고려하여 면담했다고 할 수 있는 근거를 바르게 모은 것은 어느 것인가요?","options":[{"t":"준비할 때 자료를 찾고, 진행할 때 허락을 받아 녹음하고, 정리할 때 다시 들으며 간추리고 녹음은 모둠 과제에만 쓴다","correct":true},{"t":"허락 없이 녹음하고, 녹음을 누리집에 올려 모두 듣게 한다","mis":"K6-2-u2-X11"},{"t":"자료는 찾지 않고, 녹음을 그대로 보고서에 붙인다","mis":"K6-2-u2-X13"},{"t":"대면이 더 좋으니 선생님이 멀리 계셔도 꼭 찾아간다","mis":"K6-2-u2-X12"}],"explanation":["매체는 절차마다 쓰임이 달라요.","담기 전에 허락, 쓰임은 허락 안에서예요.","정리할 때 다시 들으며 간추려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_c#24','kor',6,2,'u2','','g6_2_kor_u2_review_c','unit_review','K6-2-u2-C7',4,'essay','teacher','진다해 선생님이 「모둠 과제에만 써 주세요.」라고 하셨어요. 아침별 모둠이 녹음을 담기 전·담은 뒤·보고서를 나눌 때 각각 지켜야 할 것을 쓰고, 그렇게 해야 하는 까닭을 한 문장으로 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-2-u2-C7","difficulty":4,"kind":"essay","stem":"진다해 선생님이 「모둠 과제에만 써 주세요.」라고 하셨어요. 아침별 모둠이 녹음을 담기 전·담은 뒤·보고서를 나눌 때 각각 지켜야 할 것을 쓰고, 그렇게 해야 하는 까닭을 한 문장으로 쓰세요.","answer_guide":{"answer":"예: 담기 전에는 먼저 여쭈어 허락을 받는다. 담은 뒤에는 녹음을 보고서를 쓸 때만 쓰고 모둠 안에서만 나눈다. 보고서를 나눌 때는 간추려 쓴 보고서만 나누고 녹음 파일은 올리지 않는다. 담아 둔 녹음에는 선생님의 목소리와 말씀이 들어 있어 내 것이 아니라 빌려 온 것이므로 선생님이 허락한 범위 안에서만 써야 하기 때문이다.","scoring_points":["담기 전 허락을 썼는가","담은 뒤 보고서에만 쓰고 밖으로 내보내지 않음을 썼는가","빌려 온 것이라는 까닭을 썼는가"]},"explanation":["허락이 먼저예요.","보고서에만 쓰고 밖으로 내보내지 않아요.","담아 둔 것은 빌려 온 것이에요."],"asset":{"type":"speech","turns":[{"who":"다온","text":"안녕하세요? 바쁘신데 시간 내어 주셔서 감사합니다. 저희는 6학년 아침별 모둠입니다."},{"who":"예준","text":"오늘은 동네 책방을 꾸려 가는 일과 그 일의 보람을 여쭙고자 합니다."},{"who":"다온","text":"말씀을 정확히 남기려고 녹음하고 싶은데 괜찮으실까요?"},{"who":"진다해","text":"네, 괜찮아요. 다만 모둠 과제에만 써 주세요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_c#25','kor',6,2,'u2','','g6_2_kor_u2_review_c','unit_review','K6-2-u2-C9',4,'essay','teacher','아침별 모둠이 면담을 되돌아본다고 할 때, 면담 장면을 근거로 잘한 점·보완할 점·더 알고 싶은 점을 하나씩 쓰고, 보완할 점을 다음 면담에서 실천할 점으로 바꾸어 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K6-2-u2-C9","difficulty":4,"kind":"essay","stem":"아침별 모둠이 면담을 되돌아본다고 할 때, 면담 장면을 근거로 잘한 점·보완할 점·더 알고 싶은 점을 하나씩 쓰고, 보완할 점을 다음 면담에서 실천할 점으로 바꾸어 쓰세요.","answer_guide":{"answer":"예: 잘한 점 — 면담 열기에서 녹음 동의를 먼저 구했고, 예준이 답을 듣고 후속 질문을 했다. 보완할 점 — 진다해 선생님이 하신 당부를 메모로 남기지 못했다. 더 알고 싶은 점 — 공책에 적은 못 찾은 책을 실제로 들여놓으시는지 궁금하다. 실천할 점 — 다음 면담에서는 정리 담당과 질문 담당이 나누어 메모하자.","scoring_points":["면담 장면을 근거로 세 항목을 하나씩 썼는가","사람 탓이 아니라 절차를 짚어 썼는가","보완할 점을 구체적인 실천할 점으로 바꾸었는가"]},"explanation":["절차마다 무엇을 했는지 짚어요.","사람이 아니라 일을 봐요.","보완할 점은 다음 약속이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_d#1','kor',6,2,'u2','','g6_2_kor_u2_review_d','unit_review','K6-2-u2-C1',1,'sa','auto','면담의 세 가지 특성 「○○ · 준비 · 예의」에서 ○○에 알맞은 두 글자를 쓰세요. (대화를 주고받는 과정에서 얻는 것)','{}'::text[],false,'{"seq":1,"concept":"K6-2-u2-C1","difficulty":1,"kind":"sa","stem":"면담의 세 가지 특성 「○○ · 준비 · 예의」에서 ○○에 알맞은 두 글자를 쓰세요. (대화를 주고받는 과정에서 얻는 것)","answer":["정보"],"explanation":["면담으로 얻는 것은 정보예요.","만나기 전에는 준비, 만나는 동안에는 예의예요.","셋이 함께 있어야 면담이에요."],"mis":"K6-2-u2-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_d#2','kor',6,2,'u2','','g6_2_kor_u2_review_d','unit_review','K6-2-u2-C2',1,'sa','auto','면담을 부탁드릴 때 어느 방법이든 먼저 상대에게 구해야 하는 것은 무엇인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K6-2-u2-C2","difficulty":1,"kind":"sa","stem":"면담을 부탁드릴 때 어느 방법이든 먼저 상대에게 구해야 하는 것은 무엇인가요? 두 글자로 쓰세요.","answer":["허락"],"explanation":["찾아가기·전화·전자 우편·누리집 글이 있어요.","방법은 달라도 먼저 허락을 구해요.","허락 없이 찾아가면 면담이 시작되지 않아요."],"mis":"K6-2-u2-X03"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_d#3','kor',6,2,'u2','','g6_2_kor_u2_review_d','unit_review','K6-2-u2-C3',1,'sa','auto','면담의 세 절차는 「면담 준비하기 → 면담 ○○하기 → 면담 정리하기」예요. ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"K6-2-u2-C3","difficulty":1,"kind":"sa","stem":"면담의 세 절차는 「면담 준비하기 → 면담 ○○하기 → 면담 정리하기」예요. ○○에 알맞은 두 글자를 쓰세요.","answer":["진행"],"explanation":["만나기 전에 준비해요.","만나는 동안 진행해요.","만난 뒤에 정리해요."],"mis":"K6-2-u2-X05"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_d#4','kor',6,2,'u2','','g6_2_kor_u2_review_d','unit_review','K6-2-u2-C4',1,'ox','auto','면담 질문은 사실·생각이나 느낌·앞으로의 계획이나 당부의 세 갈래로 골고루 만드는 것이 좋아요.',ARRAY['K6-2-u2-X08']::text[],false,'{"seq":4,"concept":"K6-2-u2-C4","difficulty":1,"kind":"ox","stem":"면담 질문은 사실·생각이나 느낌·앞으로의 계획이나 당부의 세 갈래로 골고루 만드는 것이 좋아요.","answer":"O","reason_options":[{"t":"갈래가 다르면 얻는 것이 달라 면담이 한쪽으로 치우치지 않기 때문에","correct":true},{"t":"질문 수를 꼭 셋으로 맞추어야 하기 때문에","mis":"K6-2-u2-X08"}],"mis":"K6-2-u2-X08","explanation":["사실만 물으면 자료 읽기와 같아요.","마음과 앞일도 함께 물어요.","세 갈래가 고루 있어야 알찬 면담이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_d#5','kor',6,2,'u2','','g6_2_kor_u2_review_d','unit_review','K6-2-u2-C6',1,'mc','auto','진로 자료를 고를 때 먼저 확인할 것은 어느 것인가요?',ARRAY['K6-2-u2-X09']::text[],false,'{"seq":5,"concept":"K6-2-u2-C6","difficulty":1,"kind":"mc","stem":"진로 자료를 고를 때 먼저 확인할 것은 어느 것인가요?","options":[{"t":"누가 언제 만든 자료인지","correct":true},{"t":"사진이 몇 장 있는지","mis":"K6-2-u2-X09"},{"t":"검색했을 때 몇 번째로 나오는지","mis":"K6-2-u2-X09"},{"t":"글씨가 얼마나 큰지","mis":"K6-2-u2-X09"}],"explanation":["믿을 만한 출처인지가 먼저예요.","누가·언제 만들었는지 밝혀져야 해요.","사진·순서·글씨 크기는 기준이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_d#6','kor',6,2,'u2','','g6_2_kor_u2_review_d','unit_review','K6-2-u2-C7',1,'sa','auto','소통을 이어 주는 도구와 환경을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"K6-2-u2-C7","difficulty":1,"kind":"sa","stem":"소통을 이어 주는 도구와 환경을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["매체"],"explanation":["책·스마트폰·누리집이 모두 이것이에요.","면담에서도 절차마다 써요.","이것을 매체라고 해요."],"mis":"K6-2-u2-X12"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_d#7','kor',6,2,'u2','','g6_2_kor_u2_review_d','unit_review','K6-2-u2-C9',1,'sa','auto','면담 과정을 되돌아볼 때 「잘한 점 · ○○할 점 · 더 알고 싶은 점」으로 나누어 적어요. ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"K6-2-u2-C9","difficulty":1,"kind":"sa","stem":"면담 과정을 되돌아볼 때 「잘한 점 · ○○할 점 · 더 알고 싶은 점」으로 나누어 적어요. ○○에 알맞은 두 글자를 쓰세요.","answer":["보완"],"explanation":["잘한 점과 놓친 점을 나누어요.","놓친 것, 다음에 다르게 할 것은 보완할 점이에요.","보완할 점은 다음 약속으로 바꿔요."],"mis":"K6-2-u2-X14"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_d#8','kor',6,2,'u2','','g6_2_kor_u2_review_d','unit_review','K6-2-u2-C11',1,'mc','auto','「운동장이 넓은 것 같다」에서 「넓은」은 어떻게 소리 나나요?',ARRAY['K6-2-u2-X18']::text[],false,'{"seq":8,"concept":"K6-2-u2-C11","difficulty":1,"kind":"mc","stem":"「운동장이 넓은 것 같다」에서 「넓은」은 어떻게 소리 나나요?","options":[{"t":"[널븐]","correct":true},{"t":"[너븐]","mis":"K6-2-u2-X18"},{"t":"[널은]","mis":"K6-2-u2-X18"},{"t":"[넙븐]","mis":"K6-2-u2-X18"}],"explanation":["뒤에 모음 「은」이 붙었어요.","ㄹ은 받침으로 남고 ㅂ이 넘어가요.","그래서 [널븐]이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_d#9','kor',6,2,'u2','','g6_2_kor_u2_review_d','unit_review','K6-2-u2-C5',2,'mc','auto','예준의 후속 질문 덕분에 얻은 정보로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u2-X06','K6-2-u2-X13']::text[],false,'{"seq":9,"concept":"K6-2-u2-C5","difficulty":2,"kind":"mc","stem":"예준의 후속 질문 덕분에 얻은 정보로 알맞은 것은 어느 것인가요?","options":[{"t":"손님이 책을 고르다 내려놓는 모습을 보고, 못 찾은 책을 여쭈어 적어 둔다","correct":true},{"t":"책방에서 하루에 가장 많이 하는 일은 책 고르기이다","mis":"K6-2-u2-X06"},{"t":"어릴 때 오던 손님이 아이와 왔을 때 보람을 느낀다","mis":"K6-2-u2-X06"},{"t":"책방 주인은 책을 많이 읽어야 한다","mis":"K6-2-u2-X13"}],"explanation":["예준의 질문 바로 뒤의 답을 보아요.","「내려놓는 모습」, 「공책에 적어」가 새로 나온 정보예요.","질문지에 없던 물음으로 중요한 답이 나왔어요."],"asset":{"type":"speech","turns":[{"who":"소미","text":"책방에서 하루에 가장 많이 하시는 일은 무엇인가요?"},{"who":"진다해","text":"책을 고르는 일이에요. 들어오는 책을 다 놓을 수는 없어서, 우리 동네 사람들이 읽을 만한 책을 골라 놓아요."},{"who":"예준","text":"방금 「우리 동네 사람들이 읽을 만한 책」이라고 하셨는데, 그건 어떻게 아시나요?"},{"who":"진다해","text":"손님이 책을 고르다 내려놓는 모습을 봐요. 무엇을 찾다가 못 찾았는지 여쭈어 공책에 적어 두지요."},{"who":"소미","text":"책방을 하시며 가장 보람 있었던 때는 언제인가요?"},{"who":"진다해","text":"어릴 때 오던 손님이 커서 자기 아이 손을 잡고 왔을 때요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_d#10','kor',6,2,'u2','','g6_2_kor_u2_review_d','unit_review','K6-2-u2-C3',2,'ox','auto','「책방을 꾸리는 사람」 면담은 열기 → 질문하기 → 마무리하기의 차례를 갖추었어요.',ARRAY['K6-2-u2-X05']::text[],false,'{"seq":10,"concept":"K6-2-u2-C3","difficulty":2,"kind":"ox","stem":"「책방을 꾸리는 사람」 면담은 열기 → 질문하기 → 마무리하기의 차례를 갖추었어요.","answer":"O","reason_options":[{"t":"인사·목적·동의로 열고, 세 갈래로 묻고, 확인과 감사로 마무리했기 때문에","correct":true},{"t":"질문이 세 개뿐이어서 차례가 필요 없기 때문에","mis":"K6-2-u2-X05"}],"mis":"K6-2-u2-X05","explanation":["다온·예준이 열기를 했어요.","소미·예준이 묻고 이어서 물었어요.","다온이 확인하고 감사드렸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_d#11','kor',6,2,'u2','','g6_2_kor_u2_review_d','unit_review','K6-2-u2-C7',2,'error','auto','아침별 모둠이 녹음을 두고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u2-X11']::text[],false,'{"seq":11,"concept":"K6-2-u2-C7","difficulty":2,"kind":"error","stem":"아침별 모둠이 녹음을 두고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"소미 — 「허락받았으니까 녹음 파일을 누리집에 올려도 돼.」","correct":true,"mis_target":"K6-2-u2-X11"},{"t":"다온 — 「담기 전에 먼저 여쭈어 허락을 받았어.」","mis":"K6-2-u2-X11"},{"t":"예준 — 「보고서를 다 쓰면 밖으로 내보내지 않을 거야.」","mis":"K6-2-u2-X11"}],"explanation":["허락은 모둠 과제에만 쓰라는 것이었어요.","누리집에 올리는 것은 허락 밖의 일이에요.","다온과 예준은 바르게 말했어요."],"asset":{"type":"speech","turns":[{"who":"다온","text":"안녕하세요? 바쁘신데 시간 내어 주셔서 감사합니다. 저희는 6학년 아침별 모둠입니다."},{"who":"예준","text":"오늘은 동네 책방을 꾸려 가는 일과 그 일의 보람을 여쭙고자 합니다."},{"who":"다온","text":"말씀을 정확히 남기려고 녹음하고 싶은데 괜찮으실까요?"},{"who":"진다해","text":"네, 괜찮아요. 다만 모둠 과제에만 써 주세요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_d#12','kor',6,2,'u2','','g6_2_kor_u2_review_d','unit_review','K6-2-u2-C4',2,'match','auto','아침별 모둠의 질문과 갈래를 알맞게 이으세요.','{}'::text[],false,'{"seq":12,"concept":"K6-2-u2-C4","difficulty":2,"kind":"match","stem":"아침별 모둠의 질문과 갈래를 알맞게 이으세요.","pairs":[{"l":"하루에 책이 몇 권쯤 들어오나요?","r":"구체적인 사실에 대한 질문"},{"l":"손님이 책을 내려놓고 갈 때 어떤 마음이 드시나요?","r":"생각이나 느낌에 대한 질문"},{"l":"앞으로 책방에서 해 보고 싶은 일이 있으신가요?","r":"앞으로의 계획이나 당부에 대한 질문"}],"mis":"K6-2-u2-X08","explanation":["몇 권은 있는 그대로의 일이에요.","어떤 마음은 느낌이에요.","해 보고 싶은 일은 앞으로의 계획이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_d#13','kor',6,2,'u2','','g6_2_kor_u2_review_d','unit_review','K6-2-u2-C8',2,'ox','auto','면담 내용을 정리할 때 들은 말을 한 마디도 빠뜨리지 않고 그대로 옮겨 적는 것이 가장 좋아요.',ARRAY['K6-2-u2-X13']::text[],false,'{"seq":13,"concept":"K6-2-u2-C8","difficulty":2,"kind":"ox","stem":"면담 내용을 정리할 때 들은 말을 한 마디도 빠뜨리지 않고 그대로 옮겨 적는 것이 가장 좋아요.","answer":"X","reason_options":[{"t":"정리는 내가 듣고 이해한 것을 골라 내 말로 다시 세우는 일이기 때문에","correct":true},{"t":"그대로 옮겨야 뜻이 바뀌지 않기 때문에","mis":"K6-2-u2-X13"}],"mis":"K6-2-u2-X13","explanation":["통째로 옮기면 무엇이 중요한지 몰라요.","삭제·대체·선택·구성으로 간추려요.","뜻만 바꾸지 않으면 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_d#14','kor',6,2,'u2','','g6_2_kor_u2_review_d','unit_review','K6-2-u2-C10',2,'error','auto','태건에게 할 질문을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u2-X17']::text[],false,'{"seq":14,"concept":"K6-2-u2-C10","difficulty":2,"kind":"error","stem":"태건에게 할 질문을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서율 — 「곤란해해도 꼭 답하게 해야 진짜 면담이야.」","correct":true,"mis_target":"K6-2-u2-X17"},{"t":"도경 — 「답할 사람이 고를 여지를 남겨 두어야 해.」","mis":"K6-2-u2-X17"},{"t":"채원 — 「깎아내리는 말은 빼고 까닭을 여쭈어야 해.」","mis":"K6-2-u2-X17"}],"explanation":["억지로 답하게 하는 질문은 불쾌한 질문이에요.","도경과 채원은 바르게 말했어요.","궁금함과 배려를 함께 담아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_d#15','kor',6,2,'u2','','g6_2_kor_u2_review_d','unit_review','K6-2-u2-C2',2,'match','auto','면담을 요청할 때 밝히는 것과 그 예를 알맞게 이으세요.','{}'::text[],false,'{"seq":15,"concept":"K6-2-u2-C2","difficulty":2,"kind":"match","stem":"면담을 요청할 때 밝히는 것과 그 예를 알맞게 이으세요.","pairs":[{"l":"우리가 누구인지","r":"6학년 아침별 모둠입니다"},{"l":"면담 목적","r":"책방을 꾸리는 일을 알리는 글을 쓰려고 합니다"},{"l":"걸리는 시간","r":"삼십 분 정도면 될 것 같습니다"},{"l":"바라는 날짜","r":"다음 주 목요일 오후는 괜찮으실까요?"}],"mis":"K6-2-u2-X03","explanation":["이 네 가지를 밝혀야 상대가 정할 수 있어요.","날짜는 「괜찮으실까요?」로 여쭈어요.","정해서 알리지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_d#16','kor',6,2,'u2','','g6_2_kor_u2_review_d','unit_review','K6-2-u2-C8',2,'mc','auto','말 걸기를 어려워하는 친구가 모둠 면담에서 처음 맡기 좋은 일로 알맞은 것은 어느 것인가요?',ARRAY['K6-2-u2-X19','K6-2-u2-X11']::text[],false,'{"seq":16,"concept":"K6-2-u2-C8","difficulty":2,"kind":"mc","stem":"말 걸기를 어려워하는 친구가 모둠 면담에서 처음 맡기 좋은 일로 알맞은 것은 어느 것인가요?","options":[{"t":"메모나 정리를 맡아 함께한다","correct":true},{"t":"모둠에서 빠져 혼자 기다린다","mis":"K6-2-u2-X19"},{"t":"억지로 첫 질문을 크게 한다","mis":"K6-2-u2-X19"},{"t":"녹음 허락 없이 담는 일을 맡는다","mis":"K6-2-u2-X11"}],"explanation":["어려워하는 것은 잘못이 아니에요.","할 수 있는 만큼부터 함께해요.","메모·정리를 맡거나 지켜보는 것부터 시작해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_d#17','kor',6,2,'u2','','g6_2_kor_u2_review_d','unit_review','K6-2-u2-C6',3,'error','auto','진로 면담 자료를 찾는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u2-X09']::text[],false,'{"seq":17,"concept":"K6-2-u2-C6","difficulty":3,"kind":"error","stem":"진로 면담 자료를 찾는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「검색하면 맨 위에 나오는 자료가 가장 믿을 만해.」","correct":true,"mis_target":"K6-2-u2-X09"},{"t":"주호 — 「누가 만든 자료인지 확인해야 해.」","mis":"K6-2-u2-X09"},{"t":"서아 — 「언제 만든 자료인지도 살펴봐.」","mis":"K6-2-u2-X09"}],"explanation":["검색 순서는 믿을 만한지와 상관없어요.","누가·언제 만들었는지 확인해요.","주호와 서아는 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_d#18','kor',6,2,'u2','','g6_2_kor_u2_review_d','unit_review','K6-2-u2-C10',3,'error','auto','짝과 태건 면담 놀이를 했어요. 작품에 근거하지 않고 답한 친구는 누구인가요?',ARRAY['K6-2-u2-X16']::text[],false,'{"seq":18,"concept":"K6-2-u2-C10","difficulty":3,"kind":"error","stem":"짝과 태건 면담 놀이를 했어요. 작품에 근거하지 않고 답한 친구는 누구인가요?","options":[{"t":"하윤 — 「(태건이 되어) 마을에서 상을 준다고 해서 돌을 옮겼어요.」","correct":true,"mis_target":"K6-2-u2-X16"},{"t":"지호 — 「(태건이 되어) 할머니가 한 시간을 돌아 다니시는 게 마음에 걸렸어요.」","mis":"K6-2-u2-X16"},{"t":"나은 — 「(태건이 되어) 그건 이야기에 나오지 않습니다.」","mis":"K6-2-u2-X16"}],"explanation":["상을 준다는 말은 이야기에 없어요.","지호는 이야기 속 사건으로 답했어요.","나은처럼 없는 것은 없다고 말해도 돼요."],"asset":{"type":"passage","lines":["지난여름 큰비가 사흘 동안 내려 징검돌이 떠내려갔다.","할머니는 아랫마을 큰길로 한 시간을 돌아 밭에 다녔다.","어느 날 아침 태건은 혼자 떠내려간 돌을 굴려 올렸다.","돌 하나에 한나절. 거드는 사람도 말리는 사람도 없었다.","사흘째 되던 날 다시 비가 왔고, 이튿날 쌓은 돌이 흩어졌다.","태건은 젖은 모래밭에 주저앉았다.","그때 상우 아저씨가 지게를 지고 왔다. 「나도 좀 하자.」","그다음 날 아침 냇가에 어른 여섯이 나와 다리를 다시 놓았다."],"title":"「사흘 걸린 다리」 간추린 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_d#19','kor',6,2,'u2','','g6_2_kor_u2_review_d','unit_review','K6-2-u2-C9',3,'ox','auto','「면담이 재미있었다.」는 면담 과정을 성찰하는 말로 충분해요.',ARRAY['K6-2-u2-X14']::text[],false,'{"seq":19,"concept":"K6-2-u2-C9","difficulty":3,"kind":"ox","stem":"「면담이 재미있었다.」는 면담 과정을 성찰하는 말로 충분해요.","answer":"X","reason_options":[{"t":"절차마다 무엇을 했는지 짚어 잘한 점·보완할 점·더 알고 싶은 점으로 나누어야 하기 때문에","correct":true},{"t":"재미있었으면 잘한 면담이기 때문에","mis":"K6-2-u2-X14"}],"mis":"K6-2-u2-X14","explanation":["막연한 기분으로는 다음에 할 일이 남지 않아요.","절차마다 짚어요.","세 항목으로 나누어 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_d#20','kor',6,2,'u2','','g6_2_kor_u2_review_d','unit_review','K6-2-u2-C6',3,'error','auto','아침별 모둠이 질문을 점검하며 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K6-2-u2-X07']::text[],false,'{"seq":20,"concept":"K6-2-u2-C6","difficulty":3,"kind":"error","stem":"아침별 모둠이 질문을 점검하며 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"예준 — 「질문이 열 개를 넘으면 점검은 안 해도 돼.」","correct":true,"mis_target":"K6-2-u2-X07"},{"t":"다온 — 「목적에 맞는지부터 살펴보자.」","mis":"K6-2-u2-X07"},{"t":"소미 — 「‘그거’, ‘그때’ 같은 말은 뜻이 분명하게 바꾸자.」","mis":"K6-2-u2-X07"}],"explanation":["개수는 점검의 기준이 아니에요.","목적·예의·명료함을 살펴요.","다온과 소미는 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_d#21','kor',6,2,'u2','','g6_2_kor_u2_review_d','unit_review','K6-2-u2-C3',3,'ox','auto','아침별 모둠은 진다해 선생님께 감사 인사를 드리고 헤어졌으니 면담이 모두 끝났어요.',ARRAY['K6-2-u2-X05']::text[],false,'{"seq":21,"concept":"K6-2-u2-C3","difficulty":3,"kind":"ox","stem":"아침별 모둠은 진다해 선생님께 감사 인사를 드리고 헤어졌으니 면담이 모두 끝났어요.","answer":"X","reason_options":[{"t":"들은 것을 간추리고 성찰해 보고서로 남기는 면담 정리하기가 남았기 때문에","correct":true},{"t":"감사 인사가 면담의 마지막 일이기 때문에","mis":"K6-2-u2-X05"}],"mis":"K6-2-u2-X05","explanation":["헤어진 뒤에도 할 일이 있어요.","내용 정리 · 성찰 · 보고서 쓰기예요.","다온도 「보고서가 나오면 보여 드리겠습니다」라고 했어요."],"asset":{"type":"speech","turns":[{"who":"예준","text":"책방을 하고 싶은 학생에게 해 주실 말씀이 있나요?"},{"who":"진다해","text":"책을 많이 읽는 것만큼 사람 이야기를 많이 들어 보세요."},{"who":"다온","text":"책을 고르는 일이 손님의 모습을 오래 보는 일이라는 말씀이 기억에 남습니다. 보고서가 나오면 보여 드리겠습니다. 감사합니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_d#22','kor',6,2,'u2','','g6_2_kor_u2_review_d','unit_review','K6-2-u2-C9',3,'ox','auto','아침별 모둠이 보고서를 반 알림판에 붙이고 진다해 선생님께도 보여 드리는 것은 알맞아요.',ARRAY['K6-2-u2-X11']::text[],false,'{"seq":22,"concept":"K6-2-u2-C9","difficulty":3,"kind":"ox","stem":"아침별 모둠이 보고서를 반 알림판에 붙이고 진다해 선생님께도 보여 드리는 것은 알맞아요.","answer":"O","reason_options":[{"t":"간추려 쓴 보고서는 함께 읽어도 되고 면담 대상자께 보여 드리는 것이 좋기 때문에","correct":true},{"t":"보고서에 녹음 파일을 함께 붙이면 더 좋기 때문에","mis":"K6-2-u2-X11"}],"mis":"K6-2-u2-X11","explanation":["간추려 쓴 보고서는 나눠도 돼요.","면담 대상자께 보여 드리기로 약속했어요.","담아 둔 목소리는 나누지 않아요."],"asset":{"type":"speech","turns":[{"who":"예준","text":"책방을 하고 싶은 학생에게 해 주실 말씀이 있나요?"},{"who":"진다해","text":"책을 많이 읽는 것만큼 사람 이야기를 많이 들어 보세요."},{"who":"다온","text":"책을 고르는 일이 손님의 모습을 오래 보는 일이라는 말씀이 기억에 남습니다. 보고서가 나오면 보여 드리겠습니다. 감사합니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_d#23','kor',6,2,'u2','','g6_2_kor_u2_review_d','unit_review','K6-2-u2-C10',4,'mc','auto','태건과의 인물 면담에서 바람직한 질문과 작품에 근거한 답을 바르게 짝지은 것은 어느 것인가요?',ARRAY['K6-2-u2-X17','K6-2-u2-X16']::text[],false,'{"seq":23,"concept":"K6-2-u2-C10","difficulty":4,"kind":"mc","stem":"태건과의 인물 면담에서 바람직한 질문과 작품에 근거한 답을 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"질문 「혼자 돌을 옮기기로 마음먹은 까닭이 있었나요?」 — 답 「할머니가 한 시간을 돌아 다니시는 게 마음에 걸렸어요.」","correct":true},{"t":"질문 「혼자 하는 거 바보 같지 않았어요?」 — 답 「네, 바보 같았어요.」","mis":"K6-2-u2-X17"},{"t":"질문 「혼자 돌을 옮기기로 마음먹은 까닭이 있었나요?」 — 답 「상을 받으려고요.」","mis":"K6-2-u2-X16"},{"t":"질문 「왜 친구가 하나도 없었어요?」 — 답 「그건 이야기에 나오지 않습니다.」","mis":"K6-2-u2-X17"}],"explanation":["질문은 마음을 헤아려 까닭을 여쭈어요.","답은 「할머니는 … 한 시간을 돌아」 같은 이야기 속 사건에서 나와요.","둘 다 갖추어야 좋은 인물 면담이에요."],"asset":{"type":"passage","lines":["지난여름 큰비가 사흘 동안 내려 징검돌이 떠내려갔다.","할머니는 아랫마을 큰길로 한 시간을 돌아 밭에 다녔다.","어느 날 아침 태건은 혼자 떠내려간 돌을 굴려 올렸다.","돌 하나에 한나절. 거드는 사람도 말리는 사람도 없었다.","사흘째 되던 날 다시 비가 왔고, 이튿날 쌓은 돌이 흩어졌다.","태건은 젖은 모래밭에 주저앉았다.","그때 상우 아저씨가 지게를 지고 왔다. 「나도 좀 하자.」","그다음 날 아침 냇가에 어른 여섯이 나와 다리를 다시 놓았다."],"title":"「사흘 걸린 다리」 간추린 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_d#24','kor',6,2,'u2','','g6_2_kor_u2_review_d','unit_review','K6-2-u2-C10',4,'essay','teacher','「사흘 걸린 다리」의 태건에게 할 질문을 세 갈래로 하나씩 만들고, 그중 하나에 태건이 되어 작품을 근거로 답해 보세요. 불쾌한 질문이 되지 않게 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-2-u2-C10","difficulty":4,"kind":"essay","stem":"「사흘 걸린 다리」의 태건에게 할 질문을 세 갈래로 하나씩 만들고, 그중 하나에 태건이 되어 작품을 근거로 답해 보세요. 불쾌한 질문이 되지 않게 쓰세요.","answer_guide":{"answer":"예: 사실 — 떠내려간 돌을 며칠 동안 옮기셨나요? 생각이나 느낌 — 쌓은 돌이 흩어졌을 때 어떤 마음이 드셨나요? 계획이나 당부 — 혼자 무언가를 시작하려는 친구에게 해 줄 말이 있나요? 답(생각이나 느낌) — 사흘 동안 쌓은 돌이 흩어져 힘이 빠졌고 젖은 모래밭에 주저앉았어요. 그런데 그때 상우 아저씨가 지게를 지고 와 「나도 좀 하자.」라고 하셔서 다시 힘이 났어요.","scoring_points":["세 갈래로 질문을 하나씩 만들었는가","질문이 상대의 마음을 헤아리는 바람직한 질문인가","작품 속 사건·행동을 근거로 답했는가"]},"explanation":["인물에게도 세 갈래로 물어요.","깎아내리지 않고 마음을 헤아려요.","답은 이야기 안에서만 찾아요."],"asset":{"type":"passage","lines":["지난여름 큰비가 사흘 동안 내려 징검돌이 떠내려갔다.","할머니는 아랫마을 큰길로 한 시간을 돌아 밭에 다녔다.","어느 날 아침 태건은 혼자 떠내려간 돌을 굴려 올렸다.","돌 하나에 한나절. 거드는 사람도 말리는 사람도 없었다.","사흘째 되던 날 다시 비가 왔고, 이튿날 쌓은 돌이 흩어졌다.","태건은 젖은 모래밭에 주저앉았다.","그때 상우 아저씨가 지게를 지고 왔다. 「나도 좀 하자.」","그다음 날 아침 냇가에 어른 여섯이 나와 다리를 다시 놓았다."],"title":"「사흘 걸린 다리」 간추린 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_kor_u2_review_d#25','kor',6,2,'u2','','g6_2_kor_u2_review_d','unit_review','K6-2-u2-C11',4,'essay','teacher','「밝다」와 「굵다」에 모음으로 시작하는 말을 붙여 문장을 하나씩 만들고, 밑줄 친 말이 어떻게 소리 나는지와 그렇게 소리 나는 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K6-2-u2-C11","difficulty":4,"kind":"essay","stem":"「밝다」와 「굵다」에 모음으로 시작하는 말을 붙여 문장을 하나씩 만들고, 밑줄 친 말이 어떻게 소리 나는지와 그렇게 소리 나는 까닭을 쓰세요.","answer_guide":{"answer":"예: 「보름달이 밝아서 길이 잘 보인다.」에서 「밝아」는 [발가], 「나무 밑동이 굵어 안을 수 없다.」에서 「굵어」는 [굴거]로 소리 난다. 뒤에 모음으로 시작하는 말이 붙으면 겹받침의 앞 자음 ㄹ은 받침으로 남고 뒤 자음 ㄱ이 넘어가 소리 나기 때문이다.","scoring_points":["두 낱말에 모음으로 시작하는 말을 붙여 문장을 만들었는가","발음을 바르게 썼는가","앞 자음은 남고 뒤 자음이 넘어간다는 까닭을 썼는가"]},"explanation":["모음이 붙으면 뒤 자음이 넘어가요.","밝아[발가] · 굵어[굴거]예요.","낱말 하나일 때는 [박따] · [국따]예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
